export const GM_ITEMS = {"胡麻":{"qi":"甘，平，无毒。士良曰︰初食利大小肠，久食即否，去陈留新。《镜源》曰︰巨胜可煮丹砂。","zhi":"伤中虚羸，补五内，益气力，长肌肉，填髓脑。久服，轻身不老（《本经》）。坚筋骨，明耳目，耐饥渴，延年。疗金疮止痛，及伤寒温疟大吐后，虚热羸困（《别录》）。补中益气，润养五脏，补肺气，止心惊，利大小肠，耐寒暑，逐风湿气、游风、头风，治劳气，产后羸困，催生落胞。细研涂髪令长。白蜜蒸饵，治百病（《日华》）。炒食，不生风。病风人久食，则步履端正，语言不蹇（李廷飞）。生嚼涂小儿头疮，煎汤浴恶疮、妇人阴疮，大效（苏恭）。","fufang":[],"vol":"谷部"},"白油麻":{"qi":"甘，大寒，无毒。宗奭曰︰白脂麻，世用不可一日阙者，亦不至于大寒也。原曰︰生者性寒而治疾，炒者性热而发病，蒸者性温而补人。诜曰︰久食抽人肌肉。其汁停久者，饮之发霍乱。","zhi":"治虚劳，滑肠胃，行风气，通血脉，去头上浮风，润肌肉。食后生啖一合，终身勿辍。又与乳母服之，孩子永不生病。客热，可作饮汁服之。生嚼，敷小儿头上诸疮，良（孟诜）。仙方蒸以辟谷（苏颂）。","fufang":[{"text":"《抱朴子》云︰用上党胡麻三斗，淘净甑蒸，令气遍，日干，以水淘去沫再蒸，如此九度，以汤脱去皮，簸净，炒香为末，白蜜或枣膏丸弹子大。每温酒化下一丸，日三服。忌毒鱼、狗肉、生菜。服至百日，能除一切痼疾；一年，身面光泽不饥；二年，白发返黑；三年，齿落更生；四年，水火不能害；五年，行及奔马；久服，长生。若欲下之，饮葵菜汁。孙真人云︰用胡麻三升，去黄褐者，蒸三十遍，微炒香为末。入白蜜三升，杵三百下，丸梧桐子大。每旦服五十丸。人过四十以上，久服明目洞视，肠柔如筋也。《神仙传》云︰鲁女生服胡麻饵术，绝谷八十余年，甚少壮，日行三百里，走及獐鹿。服食巨胜，治五脏虚损，益气力，坚筋骨。用巨胜，九蒸九曝，收贮。每服二合，汤浸布去皮再研，水滤汁煎饮，和粳米煮粥食之。时珍曰︰古有服食胡麻、巨胜二法。方不出于一人，故有二法，其实一物也。白发返黑︰乌麻，九蒸九晒，研末，枣膏丸，服之。","src":"千金方"},{"text":"腰脚疼痛︰新胡麻一升，熬香杵末。日服一小升，服至一斗永瘥。温酒、蜜汤、姜汁皆可手脚酸痛微肿︰用脂麻五升熬研，酒一升，浸一宿。随意饮。","src":"外台"},{"text":"入水肢肿作痛︰生胡麻捣涂之。","src":"千金"},{"text":"偶感风寒︰脂麻炒焦，乘热擂酒饮之，暖卧取微汗出良。中暑毒死︰救生散︰用新胡麻一升，微炒令黑，摊冷为末，新汲水调服三钱。或丸弹子大呕不止︰白油麻一大合，清酒半升，煎取三合，去麻顿服。","src":"近效方"},{"text":"牙齿痛肿︰胡麻五升，水一斗，煮汁五升。含漱吐之，不过二剂，神良。","src":"肘后"},{"text":"热淋茎痛︰乌麻子、蔓荆子各五合，炒黄，绯袋盛，以井华水三升浸之。每食前服一钱。","src":"圣惠方"},{"text":"小儿下痢赤白︰用油麻一合捣，和蜜汤服之。","src":"外台"},{"text":"解下胎毒︰小儿初生，嚼生脂麻，绵包，与儿咂之，其毒自下。小儿急疳︰油麻嚼敷之。","src":"外台"}],"vol":"谷部"},"亚麻":{"qi":"甘，微温，无毒。","zhi":"大风疮癣（苏颂）。","fufang":[],"vol":"谷部"},"大麻":{"qi":"辛，温，无毒。甄权曰︰苦，微热，无毒。畏牡蛎。入行血药，以䗪虫为之使。","zhi":"一百二十种恶风，黑色遍身苦痒，逐诸风恶血，治女人经候不通（《药性》）。治健忘及金疮内漏（时珍）。","fufang":[{"text":"旧一，新二。瘰&#30311;初起︰七月七日麻花、五月五日艾叶，等分，作炷，灸之百壮。","src":"外台秘要"},{"text":"金疮内漏︰麻勃一两，蒲黄二两，为末。酒服一钱匕，日三，夜一。","src":"同上"}],"vol":"谷部"},"小麦":{"qi":"甘、咸，寒，无毒。【主治】益气除热，止自汗盗汗，骨蒸虚热，妇人劳热（时珍）。麦麸[编辑]【主治】时疾热疮，汤火疮烂，扑损伤折瘀血，醋炒贴之（《日华》）。和面作饼，止泄痢，调中去热健人。以醋拌蒸热，袋盛，包熨人马冷失腰脚伤折处，止痛散血（藏器）。醋蒸，熨手足风湿痺痛，寒湿脚气，互易至汗出，并良。末服，止虚汗（时珍）。【发明】时珍曰︰麸乃麦皮也。与浮麦同性，而止汗之功次于浮麦，盖浮麦无肉也。凡人身体疼痛及疮疡肿烂沾渍，或小儿暑月出痘疮，溃烂不能著席睡卧者，并用夹褥盛麸缝合藉卧，性凉而软，诚妙法也。【附方】新七。虚汗盗汗︰《卫生宝鉴》︰用浮小麦（文武火炒），为末。每服二钱半，米饮下，日三服。或煎汤代茶饮。一方︰以猪觜唇煮熟切片，蘸食亦良。产后虚汗︰小麦麸、牡蛎等分，为末。以猪肉汁调服二钱，日二服。（胡氏《妇人方》）。走气作痛︰用酽醋拌麸皮炒热，袋盛熨之。（《生生编》）。灭诸瘢痕︰春夏用大麦麸，秋冬用小麦麸，筛粉和酥敷之。（《总录》）。小儿眉疮︰小麦麸炒黑，研末，酒调敷之。小便尿血︰面麸炒香，以肥猪肉蘸食之。《集玄》。面[编辑]【气味】甘，温，有微毒。不能消热止烦（《别录》）。大明曰︰性壅热，小动风气，发丹石毒。思邈曰︰多食，长宿，加客气。畏汉椒、萝卜。【主治】补虚。久食，实人肤体，浓肠胃，强气力（藏器）。养气，补不足，助五脏（《日华》）。水调服，治人中暑，马病肺热（宗奭）。敷痈肿损伤，散血止痛。生食，利大肠。水调服，止鼻衄吐血（时珍）。【发明】诜曰︰面有热毒者，多是陈黝之色，又为磨中石末在内故也。但杵食之，即良藏器曰︰面性热，惟第二磨者凉，为其近麸也。河渭以西，白麦面性凉，以其春种，阙二气也。颖曰︰东南卑湿，春多雨水，麦已受湿气，又不曾出汗，故食之作渴，动风气，助湿发热。西北高燥，春雨又少，麦不受湿，复入地窖出汗，北人禀浓少湿，故常食而不病也。时珍曰︰北面性温，食之不渴；南面性热，食之烦渴；西边面性凉，皆地气使然也。吞汉椒、食萝卜，皆能解其毒，见萝卜条。医方中往往用飞罗面，取其无石末而性平易尔。陈麦面，水煮食之，无毒。以糟发胀者，能发病发疮，惟作蒸饼和药，取其易消也。按︰李鹏飞《延寿书》云︰北多霜雪，故面无毒；南方雪少，故面有毒。顾元庆《檐曝偶谈》云︰江南麦花夜发，故发病；江北麦花昼发，故宜人。又曰︰鱼稻宜江淮，羊面宜京洛，亦五方有宜不宜也。面性虽热，而寒食日以纸袋盛悬风处，数十年亦不坏，则热性皆去而无毒矣，入药尤良。【附方】旧六，新二十三。热渴心闷︰温水一盏，调面一两，饮之。（《圣济总录》）。中暍卒死︰井水和面一大抄，服之。（《千金》）。夜出盗汗︰麦面作弹丸，空心、卧时煮食之。次早服妙香散一帖取效。内损吐血︰飞罗面略炒，以京墨汁或藕节汁，调服二钱。（《医学集成》）。大衄血出︰口耳皆出者。用白面入盐少许，冷水调服三钱。（《普济方》）。中蛊吐血︰小麦面二合，水调服。半日当下出。（《广记》）。呕哕不止︰醋和面，作弹丸二、三十枚，以沸汤煮熟，漉出投浆水中，待温吞三、两枚。哕定，即不用再吞。未定，至晚再吞。（《兵部手集》）。寒痢白色︰炒面，每以方寸匕入粥中食之。能疗日泻百行，师不救者。（《外台》）。泄痢不固︰白面一斤，炒焦黄。每日空心温水服一、二匙。（《正要》）。诸疟久疟︰用三姓人家寒食面各一合，五月五日午时采青蒿，擂自然汁，和丸绿豆大。临头皮虚肿，薄如蒸饼，状如裹水︰以口嚼面敷之良。（《梅师方》）。咽喉肿痛，卒不下食︰白面和醋，涂喉外肿处。（《普济方》）。妇人吹奶︰水调面煮糊，欲熟，即投无灰酒一盏，搅匀热饮。令人徐徐按之，药行即瘳。（《经验方》）。乳痈不消︰白面半斤炒黄，醋煮为糊，涂之即消。（《圣惠方》）。破伤风病︰白面、烧盐各一撮。新水调，涂之。（《普济方》）。金疮血出不止︰用生面干敷，五、七日即愈。（《蔺氏经验方》）。远行脚趼成泡者︰水调生面涂之，一夜即平。（《海上》）。折伤瘀损︰白面、栀子仁同捣，以水调，敷之即散。火燎成疮︰炒面，入栀子仁末，和油敷之。（《千金》）。疮中恶肉︰寒食面二两，巴豆五分。水和作饼，烧末掺之。（《仙传外科》）。白秃头疮︰白面、豆豉和研，酢和敷之。（《普济方》）。小儿口疮︰寒食面五钱，硝石七钱，水调半钱，涂足心，男左女右。（《普济方》）。妇人断产︰白面一升，酒一升，煮沸去渣，分三服。经水至时前日夜、次日早及天明服之阴冷闷痛，渐入腹肿满︰醋和面熨之。（《千金方》）。一切漏疮︰盐、面和团，烧研敷之。（《千金方》）。瘭疽出汁，生手足肩背，累累如赤豆︰剥净，以酒和面敷之。（《千金方》）。一切疔肿︰面和腊猪脂封之良。（《梅师方》）。伤米食积︰白面一两，白酒曲二丸，炒为末。每服二匙，白汤调下。如伤肉食，山楂汤下。（《简便方》）麦粉[编辑]【气味】甘，凉，无毒。【主治】补中，益气脉，和五脏，调经络。又炒一合，汤服，断下痢（孟诜）。醋熬成膏，消一切痈肿、汤火伤（时珍）。【发明】时珍曰︰麦粉乃是麸面，面洗筋澄出浆粉。今人浆衣多用之，古方鲜用。按︰万表《积善堂方》云︰乌龙膏︰治一切痈肿发背，无名肿毒，初发热未破者，取效如神。用隔年小粉，愈久者愈佳，以锅炒之。初炒如饧，久炒则干，成黄黑色，冷定研末。陈米醋调成糊，熬如黑漆，瓷罐收之。用时摊纸上，剪孔贴之，即如冰冷，疼痛即止。少顷觉痒，干亦不能动。久则肿毒自消，药力亦尽而脱落，甚妙。此方苏州杜水庵所传，屡用有验。药易而功大，济生者宜收藏之。面筋[编辑]【气味】甘，凉，无毒。【主治】解热和中，劳热人宜煮食之（时珍）。宽中益气（宁原）。【发明】时珍曰︰面筋，以麸与面水中揉洗而成者。古人罕知，今为素食要物，煮食甚良。今人多以油炒，则性热矣。宗奭曰︰生嚼白面成筋，可粘禽、虫。麦𪎊[编辑]（即糗也。以麦蒸，磨成屑）【气味】甘，微寒，无毒。【主治】消渴，止烦（《蜀本》）。麦苗[编辑]（《拾遗》）【气味】辛，寒，无毒。【主治】消酒毒暴热，酒疸目黄，并捣烂绞汁日饮之。又解蛊毒，煮汁滤服（藏器）。除烦闷，解时疾狂热，退胸膈热，利小肠，作虀食甚益颜色（日华）麦奴[编辑]藏器曰︰麦穗将熟时，上有黑霉者也。【主治】热烦，天行热毒。解丹石毒（藏器）。治阳毒温毒，热极发狂大渴，及温疟（时珍）。【发明】时珍曰︰朱肱《南阳活人书》︰治阳毒温毒热极发狂发斑大渴倍常者，用黑奴丸，水化服一丸，汗出或微利即愈。其方用小麦奴、梁上尘、釜底煤、灶突墨，同黄芩、麻黄、硝、黄等分为末，蜜丸弹子大。盖取火化者从治之义也。麦乃心之谷，属火，而奴则麦实将成，为湿热所蒸，上黑霉者，与釜煤、灶墨同一理也。其方出陈延之《短剧方》，名麦奴丸，初虞世《古今录验》名高堂丸、水解丸，诚救急良药也。秆[编辑]【主治】烧灰，入去疣痣、蚀恶肉膏中用（时珍）。","zhi":"除客热，止烦渴咽燥，利小便，养肝气，止漏血唾血。令女人易孕（《别录》）。养心气，心病宜食之（思邈）。煎汤饮，治暴淋（宗奭）。熬末服，杀肠中蛔虫（《药性》）。陈者煎汤饮，止虚汗。烧存性，油调，涂诸疮汤火伤灼（时珍）。","fufang":[{"text":"用小麦作饭及粥食。","src":"心镜"},{"text":"老人五淋，身热腹满︰小麦一升，通草二两，水三升，煮一升，饮之即愈。","src":"奉亲书"},{"text":"项下瘿气︰用小麦一升，醋一升，渍之，晒干为末。以海藻洗，研末三两，和匀。每以酒服方寸匕，日三。","src":"短剧"},{"text":"眉炼头疮︰用小麦烧存性，为末。油调敷。","src":"儒门事亲"},{"text":"白癜风癣︰用小麦摊石上，烧铁物压出油，搽之甚效。","src":"医学正传"},{"text":"汤火伤灼，未成疮者︰用小麦炒黑，研入腻粉，油调涂之。勿犯冷水，必致烂。","src":"袖珍方"},{"text":"金疮肠出︰用小麦五升，水九升，煮取四升，绵滤取汁，待极冷。令病患卧席上，含汁使肠自入。十日中，但略食羹物。慎勿惊动，即杀人。","src":"刘涓子鬼遗方"}],"vol":"谷部"},"大麦":{"qi":"咸，温、微寒，无毒。为五谷长，令人多热。诜曰︰暴食似脚弱，为下气故也。久服宜人。熟则有益，带生则冷而损人。石蜜为之使。","zhi":"消渴除热，益气调中（《别录》）。补虚劣，壮血脉，益颜色，实五脏，化谷食，止泄，不动风气。久食，令人肥白，滑肌肤。为面，胜于小麦，无躁热（士良）。面︰平胃止渴，消食疗胀满（苏恭）。久食，头发不白。和针砂、没石子等，染发黑色（孟诜）。宽胸下","fufang":[{"text":"旧三，新六。食饱烦胀，但欲卧者︰大麦面熬微香，每白汤服方寸匕，佳。","src":"肘后方"},{"text":"膜外水气︰大麦面、甘遂末各半两，水和作饼，炙熟食，取利。","src":"总录"},{"text":"小儿伤乳，腹胀烦闷欲睡︰大麦面生用，水调一钱服。白面微炒亦可。","src":"保幼大全"},{"text":"蠷尿疮︰大麦嚼敷之，日三上。","src":"伤寒类要"},{"text":"肿毒已破︰青大麦。","src":"去须，炒"},{"text":"暴花为末，敷之。成靥，揭去又敷。数次即愈。麦芒入目︰大麦煮汁洗之，即出。","src":"孙真人方"},{"text":"汤火伤灼︰大麦炒黑，研末，油调搽之。被伤肠出︰以大麦粥汁洗肠推入，但饮米糜，百日乃可。","src":"千金"},{"text":"卒患淋痛︰大麦三两煎汤，入姜汁、蜂蜜，代茶饮。","src":"圣惠方"}],"vol":"谷部"},"穬麦":{"qi":"甘，微寒，无毒。弘景曰︰此麦性热而云微寒，恐是作屑与合壳异也。恭曰︰麦性寒，陶云性热，非矣。江东少有故也。大明曰︰暴食似动冷气，久即益人。","zhi":"轻身除热。久服，令人多力健行。作，温中消食（《别录》）。补中，不动风气。作饼食，良（萧炳）。","fufang":[],"vol":"谷部"},"雀麦":{"qi":"甘，平，无毒。","zhi":"充饥滑肠（时珍）。苗【气味】甘，平，无毒。【主治】女人产不出，煮汁饮之（苏恭）。","fufang":[{"text":"旧三。胎死腹中，胞衣不下上抢心︰用雀麦一把，水五升，煮二升，温服。","src":"子母秘录"},{"text":"齿并虫，积年不瘥，从少至老者︰用雀麦，一名杜姥草，俗名牛星草。用苦瓠叶三十枚，洗净。取草剪长二寸，以瓠叶作五包包之，广一寸，浓五分。以三年酢渍之。至日中，以两包火中炮令热，纳口中，熨齿外边，冷更易之。取包置水中解视，即有虫长三分。老者黄色，少者白色。多即二、三十枚，少即一、二十枚。此方甚妙。","src":"外台秘要"}],"vol":"谷部"},"荞麦":{"qi":"甘，平，寒，无毒。思邈曰︰酸，微寒。食之难消。久食动风，令人头眩。作面和猪、羊肉热食，不过八、九顿，即患热风，须眉脱落，还生亦希。泾、以北，多此疾。又不可合黄鱼食。","zhi":"实肠胃，益气力，续精神，能炼五脏滓秽（孟诜）。作饭食，压丹石毒，甚良（萧炳）。以醋调粉，涂小儿丹毒赤肿热疮（吴瑞）。降气宽肠，磨积滞，消热肿风痛，除白浊白带，脾积泄泻。以沙糖水调炒面二钱服，治痢疾。炒焦，热水冲服，治绞肠沙痛（时珍）。","fufang":[{"text":"荞麦粉四两，茶末二钱，生蜜二两，水一碗，顺手搅千下。饮之，良久下气不十水肿喘︰生大戟一钱，荞麦面二钱，水和作饼，炙熟为末。空心茶服，以大小便利为度男子白浊︰魏元君济生丹︰用麦炒焦为末，鸡子白和，丸梧子大。每服五十丸，盐汤下，日三服。赤白带下︰方同上。禁口痢疾︰荞麦面每服二钱，沙糖水调下。","src":"坦仙方"},{"text":"痈疽发背，一切肿毒︰麦面、硫黄各二两，为末，井华水和作饼，晒收。每用一饼，磨疮头黑凹︰荞麦面煮食之，即发起。","src":"直指"},{"text":"痘疮溃烂︰用荞麦粉频频敷之。","src":"痘疹方"},{"text":"汤火伤灼︰用荞麦面，炒黄研末，水和敷之，如神。","src":"奇效方"},{"text":"蛇盘瘰&#30311;，围接项上︰用荞麦。","src":"炒去壳"},{"text":"等分，为末。白梅浸汤，取肉减半，和丸绿豆大。每服六、七十丸，食后、临卧米饮下，日五服。其毒当从大便泄去积聚败血︰通仙散︰治男子败积，女人败血，不动真气。用麦面三钱，大黄二钱半，为头风畏冷︰李楼云︰一人头风，首裹重绵，三十年不愈。予以荞麦粉二升，水调作二饼，更互合头上，微汗即愈。","src":"怪证奇方"},{"text":"头风风眼︰荞麦作钱大饼，贴眼四角，以米大艾炷灸之，即效如神。染发令黑︰荞麦、针砂各二钱，醋和，先以浆水洗净涂之，荷叶包至一更，洗去。再以无去即黑。","src":"普济"},{"text":"绞肠沙痛︰荞麦面一撮，炒黄，水烹服。","src":"简便方"}],"vol":"谷部"},"苦荞麦":{"qi":"甘、苦，温，有小毒。时珍曰︰多食伤胃，发风动气，能发诸病，黄疾人尤当禁之。","zhi":"","fufang":[{"text":"苦荞皮、黑豆皮、绿豆皮、决明子、菊花，同作枕，至老明目。","src":"邓才《杂兴"}],"vol":"谷部"},"稻":{"qi":"苦，温，无毒。思邈曰︰味甘。宗奭曰︰性温。颂曰︰糯米性寒，作酒则热，糟乃温平，亦如大豆与豉、酱之性不同也。诜曰︰凉。发风动气，使人多睡，不可多食。藏器曰︰久食令人身软，缓人筋也。小猫、犬食之，亦脚屈不能行。马食之，足重。妊妇杂肉食之，令子不利。萧炳曰︰拥诸经络气，使四肢不收，发风昏昏。士良曰︰久食发心悸，及痈疽疮疖中痛。合酒食之，醉难醒。时珍曰︰糯性粘滞难化，小儿、病患最宜忌之。","zhi":"作饭温中，令人多热，大便坚（《别录》）。能行营卫中血积，解芫青、斑蝥毒（士良）。益气止泄（思邈）。补中益气。止霍乱后吐逆不止，以一合研水服之（大明）。以骆驼脂作煎饼食，主痔疾（萧炳）。作糜一斗食，主消渴（藏器）。暖脾胃，止虚寒泄痢，缩小便，收自汗，发痘疮（时珍）。","fufang":[{"text":"旧五，新十六。霍乱烦渴不止︰糯米三合，水五升，蜜一合，研汁分服，或煮汁服。","src":"杨氏《产乳"},{"text":"消渴饮水︰方同上。三消渴病︰梅花汤︰用糯谷。","src":"炒出白花"},{"text":"、桑根白皮等分。每用一两，水二碗，煎汁饮之。下痢禁口︰糯谷一升。","src":"炒出白花去壳，用姜汁拌湿再炒"},{"text":"为末。每服一匙，汤下，三服久泄食减︰糯米一升。水浸一宿沥干，慢炒熟，磨筛，入怀庆山药一两。每日清晨用半盏，入砂糖二匙，胡椒末少许，以极滚汤调食。其味极佳，大有滋补。久服令人精暖有子，秘方也。","src":"松篁经验方"},{"text":"鼻衄不止，服药不应︰独圣散︰用糯米微炒黄，为末。每服二钱，新汲水调下。仍吹少许劳心吐血︰糯米半两，莲子心七枚，为末，酒服。孙仲盈云︰曾用多效。或以墨汁作丸服自汗不止︰糯米、小麦麸同炒，为末。每服三钱，米饮下。或煮猪肉点食。小便白浊︰白糯丸︰治人夜小便脚停白浊，老人、虚人多此证，令人卒死，大能耗人精液，主头昏重。用糯米五升。","src":"炒赤黑"},{"text":"白芷一两，为末，糯粉糊丸梧子大。每服五十丸，木馒头煎汤下。无此，用《局方》补肾汤下。若后生禀赋怯弱，房室太过，小便太多，水管蹇涩，小便如膏脂，入石菖蒲、牡蛎粉甚效。","src":"经验良方"},{"text":"女人白淫︰糙糯米、花椒等分。炒为末，醋糊丸梧子大。每服三、四十丸，食前醋汤下。","src":"杨起《简便方"},{"text":"胎动不安，下黄水︰用糯米一合，黄、芎各五钱，水一升，煎八合，分服。","src":"产宝"}],"vol":"谷部"},"粳":{"qi":"甘、苦，平，无毒。思邈曰︰生者寒，燔者热。时珍曰︰北粳凉，南粳温。赤粳热，白粳凉，晚白粳寒。新粳热，陈粳凉。凡人嗜生米，久成米瘕，治之以鸡屎白。颖曰︰新米乍食，动风气。陈者下气，病患尤宜。诜曰︰常食干粳饭，令人热中，唇口干。不可同马肉食，发痼疾。不可和苍耳食，令人卒心痛，急烧仓米灰和蜜浆服之，不尔即死。","zhi":"益气，止烦止渴止泄（《别录》）。温中，和胃气，长肌肉（《蜀本》）。补中，壮筋骨，益肠胃（《日华》）。煮汁，主心痛，止渴，断热毒下痢（孟诜）。合芡实作粥食，益精强志，聪耳明目（好古）。通血脉，和五脏，好颜色（时珍。出《养生集要》）。常食干粳饭","fufang":[{"text":"旧二，新十。霍乱吐泻，烦渴欲绝︰用粳米二合研粉，入水二盏研汁，和淡竹沥一合，顿服。","src":"普济"},{"text":"赤痢热躁︰粳米半升，水研取汁，入油瓷瓶中，蜡纸封口，沉井底一夜，平旦服之。吴内翰家乳母病此，服之有效。","src":"普济方"},{"text":"自汗不止︰粳米粉绢包，频频扑之。五种尸病︰粳米二升，水六升，煮一沸服，日三。","src":"肘后方"},{"text":"卒心气痛︰粳米二升。水六升，煮六、七沸，服。","src":"肘后方"},{"text":"米症嗜米，有人好哑米，久则成症，不得米则吐出清水，得米即止，米不消化，久亦毙人︰用白米五合，鸡屎一升，同炒焦为末。水一升，顿服。少时吐出症，如研米汁，或白沫淡水，乃愈也。","src":"千金方"},{"text":"小儿初生三日，应开肠胃、助谷神者︰碎米浓作汁饮，如乳酪，频以豆许与儿饮之。二七日可与哺，慎不得与杂药也。","src":"肘后方"},{"text":"初生无皮色赤，但有红肉，乃受胎未足也︰用早白米粉扑之，肌肤自生。","src":"普济方"},{"text":"小儿甜疮，生于面耳︰令母频嚼白米，卧时涂之。不过三、五次，即愈。荒年辟谷︰粳米一斗，酒三升渍之，曝干又渍，酒尽止。取出稍食之，可辟三十日。足一斛三升，辟谷一年。","src":"肘后方"}],"vol":"谷部"},"籼":{"qi":"甘，温，无毒。","zhi":"温中益气，养胃和脾，除湿止泄（时珍）。秆【主治】反胃，烧灰淋汁温服，令吐。盖胃中有虫，能杀之也（《普济》）。此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/谷之一&amp;oldid=2009577”分类：PD-old此页面最后编辑于2020年12月24日(星期四)09:24。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。（请参阅使用条款）在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权（含署名权）永久有效（详情）。Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501(c)(3)免税、非营利、慈善机构。隐私政策关于维基文库免责声明法律与安全事项联系方式行为准则开发者统计Cookie声明移动版视图搜索搜索开关目录本草纲目/谷之一添加语言添加话题","fufang":[],"vol":"谷部"},"稷":{"qi":"甘，寒，无毒。诜曰︰多食，发三十六种冷病气。不与瓠子同食，发冷病，但饮黍穰汁即瘥。又不可与附子同服。","zhi":"益气，补不足（《别录》）。治热，压丹石毒发热，解苦瓠毒（《日华》）。作饭食，安中利胃宜脾（《心镜》）。凉血解暑（时珍。《生生编》）。","fufang":[{"text":"羊肉一脚，熬汤，入河西稷米、葱、盐，煮粥食之。","src":"饮膳正要"},{"text":"卒不止︰粢米粉，井华水服之良。","src":"肘后"},{"text":"痈疽发背︰粢米粉熬黑，以鸡子白和涂练上，剪孔贴之，干则易，神效。","src":"葛氏方"},{"text":"辟除瘟疫，令不相染︰以米为末，顿服之。","src":"肘后方"}],"vol":"谷部"},"黍":{"qi":"甘，温，无毒。久食令人多热烦（《别录》）。诜曰︰性寒，有小毒，发故疾。久食昏五脏，令人好睡，缓人筋骨，绝血脉。小儿多食，令久不能行。小猫、犬食之，其脚屈。合葵菜食，成痼疾。合牛肉、白酒食，生寸白李鹏飞曰︰五种黍米，多食闭气。","zhi":"益气，补中（《别录》）。烧灰和油，涂杖疮，止痛，不作瘢（孟诜）。嚼浓汁，涂小儿鹅口疮，有效（时珍）。","fufang":[{"text":"黍米二两，煮薄粥，和酒饮，发汗即愈。","src":"圣济总录"},{"text":"心痛不瘥，四十年者︰黍米淘汁，温服随意。","src":"经验方"},{"text":"汤火灼伤，未成疮者︰黍米、女曲等分，各炒焦研末，鸡子白调涂之。煮粥亦可。","src":"肘后方"}],"vol":"谷部"},"丹黍米":{"qi":"甘，微寒，无毒。思邈曰︰微温。大明曰︰温，有小毒。不可合蜜及葵同食。宗奭曰︰动风性热，多食难消。余同黍米。","zhi":"咳逆上气，霍乱，止泄利，除热，止烦渴（《别录》）。下气，止咳嗽，退热（大明）。治鳖瘕，以新熟者淘泔汁，生服一升，不过三、二度愈（孟诜）。","fufang":[{"text":"用丹黍米三两，煮薄饮，酒和饮之，令发汗即愈。","src":"伤寒类要"},{"text":"小儿鹅口，不乳者︰丹黍米嚼汁涂之。","src":"子母秘录"},{"text":"饮酒不醉︰取赤黍渍以狐血，阴干。酒饮时，取一丸置舌下含之，令人不醉。","src":"万毕术》方"},{"text":"同薏苡等分，为丸。常服之。","src":"同上"},{"text":"天行豌疮，不拘人畜︰用黍穰浓煮汁洗之。一茎者是穰，不可用。","src":"千金"},{"text":"疮肿伤风，中水痛剧者︰黍穰烧烟，熏令汗出，愈。","src":"千金方"}],"vol":"谷部"},"蜀黍":{"qi":"甘，涩，温，无毒。","zhi":"温中，涩肠胃，止霍乱。粘者与黍米功同（时珍）。根【主治】煮汁服，利小便，止喘满。烧灰酒服，治产难有效（时珍）。","fufang":[],"vol":"谷部"},"玉蜀黍":{"qi":"甘，平，无毒。","zhi":"调中开胃（时珍）。根叶【气味】原缺【主治】小便淋沥沙石，痛不可忍，煎汤频饮（时珍）。","fufang":[],"vol":"谷部"},"黄粱米":{"qi":"甘，平，无毒。","zhi":"益气，和中，止泄（《别录》）。去客风顽痺（《日华》）。止霍乱下痢，利小便，除烦热（时珍）。","fufang":[{"text":"黄粱米粉半升，水升半，和绞如白饮，顿服。","src":"外台"},{"text":"霍乱大渴不止，多饮则杀人︰黄粱米五升。水一斗，煮清三升，稍稍饮之。","src":"肘后"},{"text":"小儿鼻干无涕，脑热也︰用黄米粉、生矾末各一两。每以一钱，水调贴囟上，日二次。","src":"普济"},{"text":"小儿赤丹︰用土番黄米粉，和鸡子白涂之。","src":"兵部手集"},{"text":"小儿生疮，满身面如火烧︰以黄粱米一升研粉，和蜜水调之，以瘥为度。","src":"外台"}],"vol":"谷部"},"白粱米":{"qi":"甘，微寒，无毒。","zhi":"除热，益气（《别录》）。除胸膈中客热，移五脏气，缓筋骨。凡患胃虚并呕吐食及水者，以米汁二合，生姜汁一合，和服之，佳（孟诜）。炊饭食之，和中，止烦渴（时珍）","fufang":[{"text":"白粱米粉五合。水一升，和煮粥食。","src":"千金翼"},{"text":"手足生疣︰取白粱米粉，铁铫炒赤研末。以众人唾和涂之，浓一寸，即消。","src":"肘后"}],"vol":"谷部"},"青粱米":{"qi":"甘，微寒，无毒。","zhi":"胃痺，热中消渴，止泄痢，利小便，益气补中，轻身长年。煮粥食之（《别录》）。健脾，治泄精（大明）。","fufang":[{"text":"羊肉汤入青粱米、葱、盐，煮粥食。","src":"正要"},{"text":"脾虚泄痢︰青粱米半升，神曲炙捣罗为末一合，日日煮粥食，即愈。","src":"养老书"},{"text":"冷气心痛︰桃仁二两去皮尖，水研绞汁，入青粱米四合，煮粥常食。","src":"养老书"},{"text":"五淋涩痛︰青粱米四合，入浆水二升煮粥，下土苏末三两，每日空心食之。","src":"同上"},{"text":"老人血淋︰车前五合，绵裹煮汁，入青粱米四合，煮粥饮汁。亦能明目，引热下行。","src":"同上"},{"text":"乳石发渴︰青粱米，煮汁饮之。","src":"外台"},{"text":"一切毒药及鸩毒，烦懑不止︰用甘草三两。","src":"水五升，煮取二升，去滓"},{"text":"入黍米粉一两，白蜜三两。煎如薄粥食之。","src":"外台"}],"vol":"谷部"},"粟米":{"qi":"咸，微寒，无毒。时珍曰︰咸、淡。宗奭曰︰生者难化。熟者滞气，隔食，生虫。藏器曰︰胃冷者不宜多食。粟浸水至败者，损人。瑞曰︰与杏仁同食，令人吐泻。雁食粟，翼重不能飞。","zhi":"养肾气，去脾胃中热，益气。陈者︰苦，寒。治胃热消渴，利小便（《别录》）。止痢，压丹石热（孟诜）。水煮服，治热腹痛及鼻衄。为粉，和水滤汁，解诸毒，治霍乱及转筋入腹，又治卒得鬼打（藏器）。解小麦毒，发热（士良）。治反胃热痢。煮粥食，益丹田，","fufang":[{"text":"以陈粟米炊饭，食之，良。","src":"食医心镜"},{"text":"反胃吐食，脾胃气弱，食不消化，汤饮不下︰用粟米半升杵粉，水丸梧子大。七枚煮熟，入少盐，空心和汁吞下。或云︰纳醋中吞之，得下便已。","src":"心镜"},{"text":"鼻衄不止︰粟米粉，水煮服之。","src":"普济"},{"text":"婴孩初生七日，助谷神以导达肠胃︰研粟米煮粥如饴。每日哺少许。","src":"姚和众方"},{"text":"孩子赤丹︰嚼粟米敷之。","src":"兵部手集"},{"text":"小儿重舌︰嚼粟米哺之。","src":"秘录"},{"text":"杂物瞇目不出︰用生粟米七粒，嚼烂取汁，洗之即出。","src":"总录"},{"text":"汤火灼伤︰粟米炒焦投水，澄取汁，煎稠如糖。频敷之，能止痛，灭瘢痕。一方︰半生半炒，研末，酒调敷之。","src":"崔行功《纂要"}],"vol":"谷部"},"秫":{"qi":"甘，微寒，无毒。诜曰︰性平。不可常食，拥五脏气，动风，迷闷人。时珍曰︰按︰《养生集》云︰味酸性热，粘滞，易成黄积病，小儿不宜多食。","zhi":"寒热，利大肠，疗漆疮（《别录》）。治筋骨挛急，杀疮疥毒热。生捣，和鸡子白，敷毒肿，良（孟诜）。主犬咬，冻疮，嚼敷之（《日华》）。治肺疟，及阳盛阴虚，夜不得眠，及食鹅鸭成症，妊娠下黄汁（时珍）。","fufang":[{"text":"秫米一把，鲫鱼二脔，薤白一虎口，煮粥食之。","src":"普济方"},{"text":"筋骨挛急︰诜曰︰用秫米一石，曲三斗，地黄一斤，茵陈蒿。","src":"炙黄"},{"text":"半斤。一依酿酒法服之肺疟寒热，痰聚胸中，病至令人心寒，寒甚乃热，善惊如有所见︰恒山三钱，甘草半钱，秫米三十五粒，水煎。未发时，分作三次服。","src":"千金"},{"text":"妊娠下水，黄色如胶，或如小豆汁︰秫米、黄各一两，水七升，煎三升，分三服。","src":"梅师"},{"text":"浸淫恶疮有汁，多发于心，不早治，周身则杀人︰熬秫米令黄黑，杵末敷之。","src":"肘后方"},{"text":"久泄胃弱︰黄米炒为粉。每用数匙，沙糖拌食。","src":"简便"}],"vol":"谷部"},"参子":{"qi":"甘，涩，无毒。","zhi":"补中益气，浓肠胃，济饥。","fufang":[],"vol":"谷部"},"稗":{"qi":"辛、甘、苦，微寒，无毒。颖曰︰辛、脆。","zhi":"作饭食，益气宜脾，故曹植有芳菰精稗之称（时珍）。苗根【主治】金疮及伤损，血出不已。捣敷或研末掺之即止，甚验（时珍）。","fufang":[],"vol":"谷部"},"野狼尾草":{"qi":"甘，平，无毒。","zhi":"作饭食之，令人不饥（藏器）。【附录】蒯草藏器曰︰蒯草苗似茅，可织席为索。子亦堪食，如粳米。","fufang":[],"vol":"谷部"},"东":{"qi":"甘，平，无毒。","zhi":"益气轻身。久服，不饥，坚筋骨，能步行（藏器）。","fufang":[],"vol":"谷部"},"菰米":{"qi":"甘，冷，无毒。","zhi":"止渴（藏器）。解烦热，调肠胃（时珍）。","fufang":[],"vol":"谷部"},"蓬草子":{"qi":"酸、涩，平，无毒。","zhi":"作饭食之，益饥，无异粳米（藏器）。","fufang":[],"vol":"谷部"},"草":{"qi":"甘，平，无毒。","zhi":"不饥，轻身（藏器）。补虚羸损乏，温肠胃，止呕逆。久食健人（李）。","fufang":[],"vol":"谷部"},"薏苡仁":{"qi":"甘，微寒，无毒。诜曰︰平。","zhi":"筋急拘挛，不可屈伸，久风湿痺，下气。久服，轻身益气（《本经》）。除筋骨中邪气不仁，利肠胃，消水肿，令人能食（《别录》）。炊饭作面食，主不饥，温气。煮饮，止消渴，杀蛔虫（藏器）。治肺痿肺气，积脓血，咳嗽涕唾，上气。煎服，破毒肿（甄权）。去干湿脚气，大验（孟诜）。健脾益胃，补肺清热，去风胜湿。炊饭食，治冷气。煎饮，利小便","fufang":[{"text":"旧七，新七。薏苡仁饭，治冷气︰用薏苡仁舂熟，炊为饭食。气味欲如麦饭乃佳。或煮粥亦好。","src":"广济方"},{"text":"薏苡仁粥，治久风湿痺，补正气，利肠胃，消水肿，除胸中邪气，治筋脉拘挛︰薏苡仁为末，同粳米煮粥，日日食之，良。","src":"食医心镜"},{"text":"风湿身疼，日晡剧者，张仲景麻黄杏仁薏苡仁汤主之︰麻黄三两，杏仁二十枚，甘草、薏水肿喘急︰用郁李仁三两。","src":""},{"text":"以水滤汁，煮薏苡仁饭，日二食之。","src":"独行方"},{"text":"沙石热淋，痛不可忍︰用玉秫，即薏苡仁也，子、叶、根皆可用，水煎热饮。夏月冷冻饮料。以通为度。","src":"杨氏经验方"},{"text":"消渴饮水︰薏苡仁煮粥饮，并煮粥食之。周痺缓急偏者︰薏苡仁十五两，大附子十枚。","src":""},{"text":"为末。每服方寸匕，日三。","src":"张仲景方"},{"text":"肺痿，咳唾脓血︰薏苡仁十两。","src":"杵破"}],"vol":"谷部"},"罂子粟":{"qi":"甘，平，无毒。颂曰︰性寒。多食利二便，动膀胱气。","zhi":"丹石发动，不下饮食，和竹沥煮作粥食，极美（《开宝》）。寇曰︰服石人研此水煮，加蜜作汤饮，甚宜）。行风气，逐邪热，治反胃胸中痰滞（颂）。治泻痢，润燥（时珍）","fufang":[{"text":"罂粟粥︰用白罂粟米三合，人参末三大钱，生山芋五寸。","src":"细切，研"},{"text":"三物以水一升二合，煮取六合，入生姜汁及盐花少许，和匀分服。不计早晚，亦不妨别服汤丸。","src":"泄痢赤白︰罂粟子（炒"},{"text":"等分为末，炼蜜丸梧子大。每服三十丸，米饮下。有人经验。","src":"百一选方"}],"vol":"谷部"},"阿芙蓉":{"qi":"酸，涩，温，微毒。","zhi":"泻痢脱肛不止，能涩丈夫精气（时珍）。","fufang":[{"text":"阿芙蓉小豆许，空心温水化下，日一服。忌葱、蒜、浆水。若渴，饮蜜水解之。（赤白痢下︰鸦片、木香、黄连、白术各一分，研末，饭丸小豆大。壮者一分，老幼半分，空心米饮下。忌酸物、生冷、油腻、茶、酒、面，无不止者。口渴，略饮米汤。一方︰罂粟花未开时，外有两片青叶包之，花开即落，收取为末。每米饮服一钱，神效。赤痢用红花者；白痢用白花者。一粒金丹︰真阿芙蓉一分，粳米饭捣作三丸。每服一丸，未效再进一丸，不可多服。忌醋，令人肠断。风瘫，热酒下；口目邪，羌活汤下；百节痛，独活汤下。正头风，羌活汤下。偏头风，川芎汤下。眩晕，防风汤下。阴毒，豆淋酒下。疟疾，桃、柳枝汤下。痰喘，葶苈汤下。久嗽，干姜、阿胶汤下；劳嗽，款冬花汤下。吐泄，藿香汤下。赤痢，黄连汤下。白痢，干姜汤下。禁口痢，白术汤下。诸气痛，木香酒下。热痛，栀子汤下。脐下痛，灯汤下。小肠气，川楝子汤下。膀胱气，小茴香汤下。血气痛，乳香汤下。胁痛，热酒下。噎食。","src":"龚云林《医鉴"},{"text":"此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/谷之二&amp;oldid=2196690”分类：PD-old此页面最后编辑于2022年11月27日。","src":"星期日"},{"text":"03:56。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。","src":"请参阅使用条款"},{"text":"在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权。","src":"含署名权"},{"text":"Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501。","src":"c"}],"vol":"谷部"},"大豆":{"qi":"甘，平，无毒。久服，令人身重。岐伯曰︰生温，熟寒。藏器曰︰大豆生平，炒食极热，煮食甚寒，作豉极冷，造酱及生黄卷则平。牛食之温，马食之冷。一体之中，用之数变。之才曰︰恶五参、龙胆，得前胡、乌喙、杏仁、牡蛎、诸胆汁良。诜曰︰大豆黄屑忌猪肉。小儿以炒豆、猪肉同食，必壅气致死，十有八、九。十岁已上不畏也。时珍曰︰服蓖麻子者，忌炒豆，犯之胀满致死。服浓朴者亦忌之，动气也。","zhi":"生研，涂痈肿。煮汁饮，杀鬼毒，止痛（《本经》）。逐水胀，除胃中热痺，伤中淋露，下瘀血，散五脏结积内寒，杀乌头毒。炒为屑，主胃中热，除痺去肿，止腹胀消谷（《别录》）。煮食，治温毒水肿（《蜀本》）。调中下气，通关脉，制金石药毒、治牛马温毒（《日华》）。煮汁，解石、砒石、甘遂、天雄、附子、射罔、巴豆、芫青、斑蝥、百药之毒及蛊毒。入药，治下痢脐痛。冲酒，治风痉及阴毒腹痛。牛胆贮之，止消渴（时珍）。炒黑，热投酒中饮之，治风痺瘫缓口噤，产后头风。食罢生吞半两，去心胸烦热，热风恍惚，明目镇心，温补。久服，好颜色，变白不老。煮食性寒，下热气肿，压丹石烦热，汁消肿（藏器）。主中风脚弱，产后诸疾。同甘草煮汤饮，去一切热毒气，治风毒脚气。煮食，治心痛筋挛膝痛胀满。同桑柴灰汁煮食，下水鼓腹胀。和饭捣，涂一切毒肿。疗男女阴肿，以绵裹纳之（孟诜）。治肾病，利水下气，制诸风热，活血，解诸毒（时珍）。","fufang":[{"text":"旧三十一，新三十六。服食大豆，令人长肌肤，益颜色，填骨髓，加气力，补虚能食，不过两剂︰大豆五升，如作酱法，取黄捣末，以猪肪炼膏和丸梧子大。每服五十丸至百丸，温酒下。神验秘方也。肥人不可服之。","src":"延年秘录"},{"text":"救荒济饥︰《博物志》云︰左慈荒年法︰用大豆粗细调匀者，生熟令光，暖彻豆内。先日不食，以冷水顿服讫。一切鱼肉菜果，不得复经口。渴即饮冷水。初小困，十数日后，体力壮健，不复思食也。黄山谷救荒法︰黑豆、贯众各一升，煮熟去众，晒干。每日空心啖五、七粒。食百木枝叶皆有味，可饱也。王氏《农书》云︰辟谷之方，见于石刻。水旱虫荒，国有代有，甚则怀金立鹄，易子炊骸，为民父母者，不可不知此法也。昔晋惠帝永宁二年，黄门侍郎刘景先表奏︰臣遇太白山隐士，传济饥辟谷仙方。臣家大小七十余口，更不食别物。若不如斯，臣一家甘受刑戮。其方︰用大豆五斗淘净，蒸三遍，去皮。用大麻子三斗浸一宿，亦蒸三遍，令口开取仁。各捣为末，和捣作团如拳大。入甑内蒸，从戌至子时止，寅时出甑，午时晒干为末。干服之，以饱为度。不得食一切物。第一顿得七日不饥，第二顿得四十九日不饥，第三顿三百日不饥，第四顿得二千四百日不饥，更不必服，永不饥也。不问老少，但依法服食，令人强壮，容貌红白，永不憔悴。口渴，即研大麻子汤饮之，转更滋润脏腑。若要重吃物，用葵子三合研末，煎汤冷服，取下药如金色，任吃诸物，并无所损。前知随州朱颂教民用之有验，序其首尾，勒石于汉阳大别山太平兴国寺。又方︰用黑豆五斗淘净，蒸三遍，晒干，去皮为末。秋麻子三升，浸去皮，晒研。糯米三斗作粥，和捣为剂如拳大，入甑中蒸一宿，取晒为末。用红小枣五斗，煮去皮核，和为剂如拳大，再蒸一夜。服之，至饱为度。如渴，饮麻子水，便滋润脏腑也。脂麻亦可。但不得食一切之物。炒豆紫汤︰颂曰︰古方有紫汤，破血去风，除气防热，产后两日尤宜服之。用乌豆五升，清酒一斗，炒豆令烟绝，投酒中，待酒紫赤色，去豆。量性服之，可日夜三盏，神验。中风口噤，加鸡屎白二升，和炒，投之。豆淋酒法︰宗奭曰︰治产后百病，或血热，觉有余血水气，或中风困笃，或背强口噤，或但烦热螈口渴，或身头皆肿，或身痒呕逆直视，或手足顽痺，头旋眼眩，此皆虚热中风也。用大豆三升熬熟，至微烟出，入瓶中，以酒五升沃之，经一日以上。服酒一升，温覆令少汗出，身润即愈。口噤者，加独活半斤，微微捶破，同沃之。产后宜常服，以防风气，又消结血。中风口︰即上方，日服一升。","src":"千金"},{"text":"头风头痛︰即上方，密封七日，温服。","src":"千金"},{"text":"破伤中风口噤︰《千金方》︰用大豆一升，熬去腥气，勿使太熟，杵末，蒸令气遍，取下甑，以酒一升淋之。温服一升，取汗。敷膏疮上，即愈。《经验方》︰用黑豆四十枚，朱砂二十文，同研末。以酒半盏，调一字服之。颈项强硬，不得顾视︰大豆一升，蒸变色，囊裹枕之。","src":"千金"},{"text":"暴得风疾，四肢挛缩不能行。取大豆三升，淘净湿蒸，以醋二升，倾入瓶中，铺于地上，更蒸豆再作，并饮荆沥汤。如此三日三夜即休。","src":"崔氏《纂要"},{"text":"风入脏中，治新久肿，风入脏中︰以大豆一斗，水五斗，煮取一斗二升，去滓。入美酒斗半，煎取九升。旦服三升取汗，神验。","src":"千金翼"},{"text":"风毒攻心，烦躁恍惚︰大豆半升淘净，以水二升，煮取七合，食后服之。","src":"心镜"},{"text":"卒风不语︰大豆煮汁，煎稠如饴，含之，并饮汁。","src":"肘后方"}],"vol":"谷部"},"大豆黄卷":{"qi":"甘，平，无毒。普曰︰得前胡、杏子、牡蛎、乌喙、天雄、鼠屎，共蜜和良。恶海藻、龙胆。","zhi":"湿痹，筋挛膝痛（《本经》）。五脏不足，胃气结积，益气止痛，去黑皯，润肌肤皮毛（《别录》）。破妇人恶血（孟诜。颂曰：古方蓐妇药中多用之）。宜肾（思邈）。除胃中积热，消水病胀满（时珍）。","fufang":[{"text":"治周痺在血脉之中，随脉上下，本痺不痛，今能上下周身，故名。治周痺注，五脏留滞，胃中结聚，益气出毒，润皮毛，补肾气。用大豆一斤。","src":"炒香"},{"text":"为末。每服半钱，温酒调下，空心，加至一钱，日三服。","src":"宣明方"},{"text":"诸风湿痺，筋挛膝痛，胃中积热口疮烦闷，大便秘涩︰黄卷散︰用大豆黄卷。","src":"炒熟捣末"},{"text":"一水病肿满喘急，大小便涩︰大豆黄卷。","src":"醋炒"},{"text":"等分。为细末。葱、橘皮汤服二小儿撮口︰初生豆芽研烂，绞汁和乳，灌少许，良。","src":"普济方"}],"vol":"谷部"},"黄大豆":{"qi":"甘，温，无毒。时珍曰︰生温，炒热微毒。多食，壅气生痰动嗽，令人身重，发面黄疮疥。","zhi":"宽中下气，利大肠，消水胀肿毒（宁原）。研末，熟水和，涂痘后痈（时珍）。","fufang":[],"vol":"谷部"},"赤小豆":{"qi":"甘、酸，平，无毒。思邈曰︰甘、咸，冷。合鱼食成消渴，作酱同饭食成口疮。藏器曰︰驴食足轻，人食身重。","zhi":"下水肿，排痈肿脓血（《本经》）。疗寒热热中消渴，止泄痢，利小便，下腹胀满，吐逆卒（《别录》）。消热毒，散恶血，除烦满，通气，健脾胃，令人美食。捣末同鸡子白，涂一切热毒痈肿。煮汁，洗小儿黄烂疮，不过三度（权）。缩气行风，坚筋骨，抽肌肉。久食瘦人（士良）。散气，去关节烦热，令人心孔开。暴痢后，气满不能食者，煮食一顿即辟瘟疫，治产难，下胞衣，通乳汁。和鲤鱼、蠡鱼、鲫鱼、黄雌鸡煮食，并能利水消肿（时珍）。","fufang":[{"text":"颂曰︰用赤小豆五合，大蒜一颗，生姜五钱，商陆根一条，并碎破，同水煮烂，去药，空心食豆，旋旋啜汁令尽，肿立消也。韦宙《独行方》︰治水肿从脚起，入腹则杀人。赤小豆一斗，煮极烂，取汁五升，温渍足膝。若已入腹，但食小豆，勿杂食，亦愈。《梅师》︰治水肿。以东行花桑枝烧灰一升，淋汁，煮赤小豆一升，以代饭，良。水蛊腹大，动摇有声，皮肤黑者︰用赤小豆三升，白茅根一握，水煮食豆，以消为度。辟禳瘟疫︰《五行书》云︰正月朔旦及十五日，以赤小豆二七枚，麻子七枚，投井中，辟瘟疫甚效。又正月七日，新布囊盛赤小豆置井中，三日取出，男吞七枚，女吞二七枚，竟年无病也。","src":"肘后方"},{"text":"辟厌疾病︰正月元旦，面东，以齑水吞赤小豆三七枚，一年无诸疾。又七月立秋日，面西伤寒狐惑︰张仲景曰︰狐惑病，脉数，无热微烦，默默但欲卧，汗出。初得三、四日，目赤如鸠眼；七、八日，目四黄黑。若能食者，脓已成也。赤豆当归散主之。赤小豆三升（下部卒痛，如鸟啄之状︰用小豆、大豆各一升，蒸熟，作二囊，更互坐之，即止。","src":"肘后方"},{"text":"水谷痢疾︰小豆一合，熔蜡三两，顿服取效。","src":"必效方"},{"text":"热毒下血，或因食热物发动︰赤小豆末，水服方寸匕。","src":"梅师方"},{"text":"肠痔下血︰小豆二升，苦酒五升，煮熟日干，再浸至酒尽乃止，为末。酒服一钱，日三服。","src":"肘后方"},{"text":"舌上出血，如簪孔︰小豆一升，杵碎，水三升和，绞汁服。","src":"肘后方"},{"text":"热淋血淋，不拘男女︰用赤小豆三合，慢火炒为末，煨葱一茎，擂酒热调二钱服。","src":"修真秘旨"},{"text":"重舌鹅口︰赤小豆末，醋和涂之。","src":"普济方"}],"vol":"谷部"},"腐婢":{"qi":"辛，平，无毒。","zhi":"疟，寒热邪气，泄痢，阴不起。止消渴。病酒头痛（《本经》。《心镜》云︰上证，用花同豉汁五味，煮羹食之）。消酒毒，明目，下水气，治小儿丹毒热肿，散气满不能食，煮一顿食之（《药性》）。治热中积热，痔下血（时珍。《宣明》葛花丸中用之）。","fufang":[{"text":"小豆花、叶，阴干百日为末，水服方寸匕。或加葛花等分。","src":"千金"},{"text":"疔疮恶肿︰小豆花末，敷之。","src":"普济方"}],"vol":"谷部"},"绿豆":{"qi":"甘，寒，无毒。藏器曰︰用之宜连皮，去皮则令人小壅气，盖皮寒而肉平也。反榧子壳，害人。合鲤鱼","zhi":"煮食，消肿下气，压热解毒。生研绞汁服，治丹毒烦热风疹，药石发动，热气奔豚（《开宝》）。治寒热热中，止泄痢卒，利小便胀满（思邈）。浓肠胃。作枕，明目，治头风头痛。除吐逆（《日华》）。补益元气，和调五脏，安精神，行十二经脉，去浮风，润皮肤，宜常食之。煮汁，止消渴（孟诜）。解一切药草、牛马、金石诸毒（宁原）。治痘毒，利肿","fufang":[{"text":"新十一。扁鹊三豆饮，治天行痘疮。预服此饮，疏解热毒，纵出亦少︰用绿豆、赤小豆、黑大豆各一升，甘草节二两，以水八升，煮极熟。任意食豆饮汁，七日乃止。一方︰加黄大豆、白大痘后痈毒初起，以三豆膏治之，神效︰绿豆、赤小豆、黑大豆等分，为末。醋调时时扫涂，即消。","src":"医学正传"},{"text":"防痘入眼︰用绿豆七粒，令儿自投井中，频视七遍，乃还。小儿丹肿︰绿豆五钱，大黄二钱。为末。用生薄荷汁入蜜调涂。","src":"全幼心鉴"},{"text":"赤痢不止︰以大麻子，水研滤汁，煮绿豆食之，极效。粥食亦可。","src":"必效方"},{"text":"老人淋痛︰青豆二升，橘皮二两，煮豆粥，下麻子汁一升。空心渐食之，并饮其汁，甚验。","src":"养老书"},{"text":"消渴饮水︰绿豆煮汁，并作粥食。","src":"普济方"},{"text":"心气疼痛︰绿豆廿一粒，胡椒十四粒。同研，白汤调服即止。多食易饥绿豆、黄麦、糯米各一升，炒熟磨粉。每以白汤服一杯，三、五日见效。十种水气︰用绿豆二合半，大附子一只。","src":"去皮脐，切作两片"},{"text":"水三碗，煮熟，空心卧时食豆。次日将附子两片作四片，再以绿豆二合半，如前煮食。第三日别以绿豆、附子如前煮食。第四日如第二日法煮食。水从小便下，肿自消。未消再服。忌生冷、毒物、盐、酒六十日，无不效者。","src":"朱氏集验方"},{"text":"痘疮湿烂不结痂者，干扑之良。","src":"宁原"}],"vol":"谷部"},"白豆":{"qi":"甘，平，无毒。原曰︰咸，平。","zhi":"补五脏，调中，助十二经脉（孟诜）。暖肠胃（《日华》）。杀鬼气。肾之谷，肾病宜食之（思邈）。叶【主治】煮食，利五脏，下气（《日华》）。","fufang":[],"vol":"谷部"},"穞豆":{"qi":"甘，温，无毒。","zhi":"去贼风风痺，妇人产后冷血，炒令焦黑，及热投酒中，渐渐饮之（藏器）。","fufang":[],"vol":"谷部"},"豌豆":{"qi":"甘，平，无毒。思邈曰︰甘、咸，温、平，涩。瑞曰︰多食发气病。","zhi":"消渴，淡煮食之，良（藏器）。治寒热热中，除吐逆，止泄痢下，利小便、腹胀满（思邈）。调营卫，益中平气。煮食，下乳汁。可作酱用（瑞）。煮饮，杀鬼毒心病，解乳石毒发。研末，涂痈肿痘疮。作澡豆，去，令人面光泽（时珍）。","fufang":[{"text":"治小儿痘中有疔，或紫黑而大，或黑坏而臭，或中有黑线，此症十死八九，惟牛都御史得秘传此方点之最妙。用豌豆四十九粒。","src":"烧存性"},{"text":"头发灰三分，真珠十四粒炒研服石毒发︰胡豆半升捣研，以水八合绞汁饮之，即愈。","src":"外台"},{"text":"霍乱吐利︰豌豆三合，香三两，为末，水三盏，煎一盏，分二服。","src":"圣惠"}],"vol":"谷部"},"蚕豆":{"qi":"甘、微辛，平，无毒。","zhi":"快胃，和脏腑（汪颖）。","fufang":[],"vol":"谷部"},"豇豆":{"qi":"甘、咸，平，无毒。","zhi":"理中益气，补肾健胃，和五脏，调营卫，生精髓，止消渴、吐逆泄痢，小便数，解鼠莽毒（时珍）。","fufang":[],"vol":"谷部"},"藊豆":{"qi":"甘，微温，无毒。诜曰︰微寒，患冷人勿食。弘景曰︰患寒热者不可食。","zhi":"和中，下气（《别录》）。补五脏，主呕逆。久服头不白（孟诜）。疗霍乱吐利不止，研末和醋服之（同上）。行风气，治女子带下，解酒毒、河豚鱼毒（苏颂）。解一切草木毒，生嚼及煮汁饮，取效（甄权）。止泄痢，消暑，暖脾胃，除湿热，止消渴（时珍）。","fufang":[{"text":"扁豆、香薷各一升，水六升，煮二升，分服。","src":"千金"},{"text":"霍乱转筋︰白扁豆为末，醋和服。","src":"普济方"},{"text":"消渴饮水︰金豆丸︰用白扁豆浸去皮，为末，以天花粉汁同蜜和丸梧子大，金箔为衣。每赤白带下︰白扁豆炒为末，用米饮，每服二钱。毒药堕胎︰女人服草药堕胎腹痛者。生白扁豆去皮，为末，米饮服方寸匕，浓煎汁饮，亦可丸服。若胎气已伤未堕者，或口噤手强，自汗头低，似乎中风，九死一生。医多不识，作中砒霜毒︰白扁豆生研，水绞汁饮。","src":"并《永类方"},{"text":"六畜肉毒︰白扁豆烧存性研，冷水服之，良。","src":"事林广记"},{"text":"诸鸟肉毒︰生扁豆末，冷水服之。","src":"同上"},{"text":"恶疮痂痒作痛︰以扁豆捣封，痂落即愈。","src":"肘后"},{"text":"焙研服，治崩带。作馄饨食，治泄痢。擂水饮，解中一切药毒垂死。功同扁豆。","src":"时珍"},{"text":"一切泄痢︰白扁豆花正开者，择净勿洗，以滚汤瀹过，和小猪脊KT肉一条，葱一根，胡椒七粒，酱汁拌匀，就以瀹豆花汁和面，包作小馄饨，炙熟食之。","src":"必用食治方"}],"vol":"谷部"},"刀豆":{"qi":"甘，平，无毒。","zhi":"温中下气，利肠胃，止呃逆，益肾补元（时珍）。","fufang":[],"vol":"谷部"},"黎豆":{"qi":"甘、微苦，温，有小毒。多食令人闷。","zhi":"温中，益气（时珍）。此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/谷之三&amp;oldid=2245697”分类：PD-old此页面最后编辑于2022年12月19日(星期一)19:58。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。（请参阅使用条款）在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权（含署名权）永久有效（详情）。Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501(c)(3)免税、非营利、慈善机构。隐私政策关于维基文库免责声明法律与安全事项联系方式行为准则开发者统计Cookie声明移动版视图搜索搜索开关目录本草纲目/谷之三添加语言添加话题","fufang":[],"vol":"谷部"},"大豆豉":{"qi":"苦，寒，无毒。思邈曰︰苦、甘，寒，涩。得醯良。杲曰︰阴中之阴也。","zhi":"伤寒头痛寒热，瘴气恶毒，烦躁满闷，虚劳喘吸，两脚疼冷。杀六畜胎子诸毒（《别录》）。治时疾热病发汗。熬末，能止盗汗，除烦躁。生捣为丸服，治寒热风，胸中生疮。煮服，治血痢腹痛。研涂阴茎生疮（《药性》）。治疟疾骨蒸，中毒药蛊气，犬咬（大明）。下气调中，治伤寒温毒发呕逆（时珍。《千金》治温毒黑膏用之）。蒲州豉【气味】咸，寒，无毒。【主治】解烦热，热毒，寒热虚劳，调中发汗，通关节，杀腥气，伤寒鼻塞。陕州豉汁亦除烦热（藏器）。","fufang":[{"text":"旧三十一，新一十九。伤寒发汗︰颂曰︰葛洪《肘后方》云︰伤寒有数种，庸人卒不能分别者，今取一药兼疗之。凡初觉头痛身热，脉洪，一、二日，便以葱豉汤治之。用葱白一虎口，豉一升，绵裹，水三升，煮一升，顿服。不汗更作，加葛根三两；再不汗，加麻黄三两。《肘后》又法︰用葱汤煮米粥，入盐豉食之，取汗。又法︰用豉一升，小男溺三升，煎一升，分服取汗。伤寒不解，伤寒汗出不解，已三、四日，胸中闷恶者︰用豉一升，盐一合，水四升，煮一升半，分服取吐，此秘法也。","src":"梅师方"},{"text":"辟除温疫︰豉和白术浸酒，常服之。","src":"梅师"},{"text":"伤寒懊，吐下后心中懊，大下后身热不去，心中痛者，并用栀子豉汤吐之︰肥栀子十伤寒余毒，伤寒后毒气攻手足，及身体虚肿︰用豉五合微炒，以酒一升半，同煎五七沸，任性饮之。","src":"简要济众"},{"text":"伤寒目翳︰烧豉二、七枚，研末吹之。","src":"肘后"},{"text":"伤寒暴痢︰《药性论》曰︰以豉一升，薤白一握，水三升，煮薤熟，纳豉更煮，色黑去豉血痢不止︰用豉、大蒜等分。杵丸梧子大。每服三十丸，盐汤下。","src":"王氏《博济"},{"text":"血痢如刺︰《药性论》曰︰以豉一升，水渍相淹，煎两沸，绞汁顿服。不瘥再作。赤白重下︰葛氏︰用豆豉熬小焦，捣服一合，日三。或炒焦，以水浸汁服，亦验。《外台》︰用豉心。","src":"炒为末"},{"text":"一升，分四服，酒下，入口即断也。脏毒下血︰乌犀散︰用淡豉十文，大蒜二枚。","src":""},{"text":"同捣丸梧子大。煎香菜汤服二十丸，日二服，安乃止，永绝根本，无所忌。庐州彭大祥云︰此药甚妙，但大蒜九蒸乃佳，仍以冷齑小便血条︰淡豆豉一撮。煎汤空腹饮。或入酒服。","src":"危氏《得效方"}],"vol":"谷部"},"豆黄":{"qi":"甘，温，无毒。诜曰︰忌猪肉。","zhi":"湿痺膝痛，五脏不足气，胃气结积，壮气力，润肌肤，益颜色，填骨髓，补虚损，能食，肥健人。以炼猪脂和丸，每服百丸，神验秘方也。肥人勿服（诜。出《延年秘录》方）。生嚼涂阴痒汗出（时珍）。","fufang":[{"text":"大豆黄二升，大麻子三升。熬香，为末。每服一合，饮下，日四、五服，任意。","src":"千金方"},{"text":"打击青肿︰大豆黄为末，水和涂之。","src":"外台秘要"}],"vol":"谷部"},"豆腐":{"qi":"甘、咸，寒，有小毒。原曰︰性平。颂曰︰寒而动气。瑞曰︰发肾气、疮疥、头风，杏仁可解。时珍曰︰按︰《延寿书》云︰有人好食豆腐中毒，医不能治。作腐家言︰莱菔入汤中则腐不成。遂以莱菔汤下药而愈。大抵暑月恐有人汗，尤宜慎之。","zhi":"宽中益气，和脾胃，消胀满，下大肠浊气（宁原）。清热散血（时珍）。","fufang":[{"text":"白豆腐醋煎，食之即愈。","src":"普济方"},{"text":"赤眼肿痛：有数种，皆肝热血凝也︰用消风热药服之。夜用盐收豆腐片贴之，酸浆者勿用。","src":"证治要诀"},{"text":"杖疮青肿︰豆腐切片贴之，频易。一法︰以烧酒煮贴之，色红即易，不红乃已。","src":"拔萃方"}],"vol":"谷部"},"陈廪米":{"qi":"咸、酸，温，无毒。藏器曰︰廪米热食即热，冷食即冷，假以火气也，体自温平。同马肉飧，发痼疾。时珍曰︰廪米年久，其性多凉，但炒食则温尔，岂有热食即热者乎？","zhi":"下气，除烦渴，调胃止泄（《别录》）。补五脏，涩肠胃（《日华》）。暖脾，去惫气，宜作汤食（士良）。炊饭食，止痢，补中益气，坚筋骨，通血脉，起阳道。以饭和酢捣封毒肿恶疮，立瘥。北人以饭置瓮中，水浸令酸，食之，暖五脏六腑之气。研取汁服，去卒心痛（孟诜）。宽中消食。多食易饥（宁原）。调肠胃，利小便，止渴除热（时珍）。","fufang":[{"text":"能杀人，以黄仓米三升，水一斗，煮汁澄清饮，良。","src":"永类钤方"},{"text":"反胃膈气︰不下食者，太仓散用仓米或白米，日西时以水微拌湿，自想日气如在米中。次日晒干，袋盛挂风处。每以一撮，水煎，和汁饮之，即时便下。又方︰陈仓米炊饭焙研，每五两入沉香末半两，和匀。每米饮服二、三钱。","src":"普济方"},{"text":"诸般积聚︰太仓丸治脾胃饥饱不时生病，及诸般积聚，百物所伤。陈仓米四两，以巴豆梧子大。每姜汤服五丸，日二服。","src":"百一选方"},{"text":"暑月吐泻︰陈仓米二升，麦芽四两，黄连四两。","src":"切"}],"vol":"谷部"},"饭":{"qi":"","zhi":"人尿床，以热饭一盏，倾尿床处，拌与食之，勿令病者知。又乘热敷肿毒，良（时珍）。寒食饭馈饭也。【主治】灭瘢痕及杂疮，研末敷之（藏器）。烧灰酒服，治食本米饮成积，黄瘦腹痛者，甚效（孙思邈）。伤寒食，复用此饭烧研，米饮服二、三钱，效（时珍）。祀灶饭【主治】卒噎，取一粒食之，即下。烧研，搽鼻中疮（时珍）。盆边零饭【主治】鼻中生疮，烧研敷之（时珍）。齿中残饭【主治】蝎咬毒痛，敷之即止（时珍）。飧饭飧音孙，即水饭也。【主治】热食，解渴除烦（时珍）。荷叶烧饭【主治】浓脾胃，通三焦，资助生发之气（时珍）。","fufang":[],"vol":"谷部"},"青精干石𩛓饭":{"qi":"甘，平，无毒。","zhi":"日进一合，不饥，益颜色，坚筋骨，能行（藏器）。益肠胃，补髓，灭三虫，久服变白，却老。（苏颂《出太极》）","fufang":[],"vol":"谷部"},"粥":{"qi":"甘，温，无毒。【主治】益气，治脾胃虚寒，泄痢吐逆，小儿痘疮白色（时珍）。粳米、籼米、粟米、粱米粥【气味】甘，温、平，无毒。【主治】利小便，止烦渴，养脾胃（时珍）。","zhi":"止消渴烦热（时珍）。寒食粥（用杏仁和诸花作之）【主治】咳嗽下血，气调中（藏器）糯米、秫米、黍米粥","fufang":[],"vol":"谷部"},"𪎊":{"qi":"甘、苦，微寒，无毒。藏器曰︰酸，寒。","zhi":"寒中，除热渴，消石气（苏恭）。和水服，解烦热，止泄，实大肠（藏器）。炒米汤止烦渴（时珍）","fufang":[],"vol":"谷部"},"糕":{"qi":"甘，温，无毒。时珍曰︰粳米糕易消导。粢糕最难克化，损脾成积，小儿尤宜禁之。","zhi":"粳糕︰养脾胃，浓肠，益气和中。粢糕︰益气暖中，缩小便，坚大便，效（时珍）。","fufang":[{"text":"干糕一两，姜汤泡化，代饭。","src":"简便方"}],"vol":"谷部"},"粽":{"qi":"甘，温，无毒。","zhi":"五月五日取粽尖，和截疟药，良（时珍）。","fufang":[],"vol":"谷部"},"寒具":{"qi":"甘、咸，温，无毒。","zhi":"利大小便，润肠，温中益气（时珍）。","fufang":[{"text":"新二。钱氏捻头散，治小儿小便不通︰用延胡索、苦楝子等分，为末。每服半钱或一钱，以捻头汤食前调下。如无捻头，滴油数点代之。","src":"钱氏小儿方"}],"vol":"谷部"},"蒸饼":{"qi":"甘，平，无毒。","zhi":"消食，养脾胃，温中化滞，益气和血，止汗，利三焦，通水道（时珍）。","fufang":[{"text":"寒食蒸饼、乌龙尾各一两，皂角七挺。","src":"去皮酥炙"},{"text":"为末，蜜丸。米饮每服二十丸。","src":"圣惠方"},{"text":"下痢赤白，治营卫气虚，风邪袭入肠胃之间，便痢赤白，脐腹痛，里急后重，烦渴胀满，不进饮食︰用干蒸饼。","src":"蜜拌，炒"},{"text":"四两，为末，炼蜜丸芡子大。每服一丸，水一盏，煎化热服。","src":"传信适用妙方"},{"text":"崩中下血︰陈年蒸饼，烧存性，米饮服二钱。盗汗自汗︰每夜卧时，带饥吃蒸饼一枚，不过数日即止。","src":"医林集要"},{"text":"一切折伤︰寒食蒸饼为末。每服二钱，酒下，甚验。","src":"肘后方"},{"text":"汤火伤灼︰馒头饼烧存性，研末，油调涂敷之。","src":"肘后方"}],"vol":"谷部"},"女曲":{"qi":"甘，温，无毒。","zhi":"消食下气，止泄痢，下胎，破冷血（苏恭）。","fufang":[],"vol":"谷部"},"黄蒸":{"qi":"","zhi":"并同女曲（苏恭）。温补，能消诸生物（藏器）。温中下气，消食除烦（《日华》）。治食黄、黄汗（时珍）。","fufang":[{"text":"新一。黄胆疾，或黄汗染衣，涕唾皆黄︰用好黄蒸二升，每夜以水二升，浸微暖，于铜器中，平旦绞汁半升饮之，极效。","src":"必效方"}],"vol":"谷部"},"曲":{"qi":"甘，温，无毒。震亨曰︰麸皮曲︰凉，入大肠经。","zhi":"消谷止痢（《别录》）。平胃气，消食痔，治小儿食痫（苏恭）。调中下气，开胃，疗脏腑中风寒（藏器）。主霍乱、心膈气、痰逆，除烦，破症结（孟诜）。补虚，去冷气，除肠胃中塞，不下食，令人有颜色（吴瑞）。落胎，并ㄊ下鬼胎（《日华》）。止河鱼之腹疾（梁简文帝《劝医文》）。大麦曲【气味】同前。【主治】消食和中，下生胎，破血。取五升，以水一斗煮三沸，分五服，其子如糜，令母肥盛（时珍）。面曲、米曲【气味】同前。【主治】消食积、酒积、糯米积，研末酒服立愈。余功同小麦曲（时珍。出《千金》）。","fufang":[{"text":"炒曲末，白汤调服二钱，日三服。三焦滞气︰陈曲。","src":""},{"text":"等分。每用三钱，水煎，入麝香小腹坚大如盘，胸满，食不能消化︰用曲末，汤服方寸匕，日三。","src":"千金"},{"text":"水痢百起︰六月六日曲。","src":"炒黄"},{"text":"、马蔺子等分，为末，米饮服方寸匕。无马蔺子，用牛骨灰代之。","src":"普济方"},{"text":"赤白痢下，水谷不消︰以曲熬粟米粥，服方寸匕，日四、五服。","src":"肘后方"},{"text":"酒毒便血︰曲一块，湿纸包煨，为末。空心米饮服二钱，神效。伤寒食复︰曲一饼，煮汁饮之，良。","src":"类要方"},{"text":"胎动不安，或上抢心，下血者︰生曲饼研末，水和绞汁，服三升。","src":"肘后"},{"text":"狐刺尿疮︰曲末和独头蒜，杵如麦粒，纳疮孔中，虫出愈。","src":""}],"vol":"谷部"},"神曲":{"qi":"甘、辛，温，无毒。元素曰︰阳中之阳也，入足阳明经。凡用须火炒黄，以助土气。陈久者良。","zhi":"化水谷宿食，症结积滞，健脾暖胃（《药性》）。养胃气，治赤白痢（元素）。消食下气，除痰逆霍乱，泄痢胀满诸疾，其功与曲同。闪挫腰痛者，过淬酒温服有效。妇人产后欲回乳者，炒研，酒服二钱，日二即止，甚验（时珍）。","fufang":[{"text":"神曲半斤，麦芽五升，杏仁一升，各炒为末，炼蜜丸弹子大。每食后嚼化一丸。","src":"普济方"},{"text":"壮脾进食，疗痞满暑泄︰曲术丸︰用神曲。","src":""},{"text":"等分为末，糊丸梧子大。每米饮服五十丸。冷者加干姜或吴茱萸。（《肘后百一健胃思食︰消食丸︰治脾胃俱虚，不能消化水谷，胸膈痞闷，腹胁膨胀，连年累月，食减嗜卧，口苦无味。神曲六两，麦。","src":""},{"text":"四两，为末，蜜丸梧子大。每米饮服五十丸，日三服。","src":"和剂局方"},{"text":"虚寒反胃︰方同上。暴泄不止︰神曲。","src":""},{"text":"半两，为末，醋糊丸梧子大。每服五十丸，米饮下。","src":"百一选方"},{"text":"为末，水服方寸匕。","src":"千金方"},{"text":"食积心痛︰陈神曲一块烧红，淬酒二大碗服之。","src":"摘玄方"}],"vol":"谷部"},"红曲":{"qi":"甘，温，无毒。瑞曰︰酿酒则辛热，有小毒，发肠风痔、脚气、哮喘痰嗽诸疾。","zhi":"消食活血，健脾燥胃，治赤白痢下水谷（震亨）。酿酒，破血行药势，杀山岚瘴气，治打扑伤损（吴瑞）。治女人血气痛，及产后恶血不尽，擂酒饮之，良（时珍）。","fufang":[{"text":"丹溪青六丸︰用六一散，加炒红曲五钱，为末，蒸饼和丸梧子大。每服五、七十丸，白汤下，日三服。","src":"丹溪心法"},{"text":"小儿吐逆频并，不进乳食，手足心热︰用红曲。","src":"年久者"},{"text":"一钱，为末。每服半钱，煎枣子、米汤下。","src":"经济"},{"text":"小儿头疮︰因伤湿入水成毒，浓汁不止︰用红曲嚼罨之，甚效。","src":"百一选方"},{"text":"心腹作痛赤曲、香附、乳香等分为末，酒服。","src":"摘玄方"}],"vol":"谷部"},"蘖米（粟芽、谷芽、麦芽）":{"qi":"苦，温，无毒。宗奭曰：今谷神散中用之，性温于麦蘖。","zhi":"寒中，下气，除热（《别录》）。除烦，消宿食，开胃（《日华》）。为末和脂敷面，令皮肤悦泽（陶弘景）。稻蘖（一名谷芽）【气味】甘，温，无毒。【主治】快脾开胃，下气和中，消食化积（时珍）。","fufang":[{"text":"谷神丸：用谷蘖四两为末，入姜汁、盐少许，和作饼，焙干，入炙甘草、砂仁、白术。","src":"麸炒"},{"text":"各一两，为末。白汤点服之，或丸服。","src":"澹寮方"},{"text":"破冷气，去心腹胀满。","src":"药性"},{"text":"开胃，止霍乱，除烦闷，消痰饮，破症结，能催生落胎。","src":"日华"},{"text":"补脾胃虚，宽肠下气，腹鸣者用之。","src":"元素"},{"text":"消化一切米、面、诸果食积。","src":"时珍"}],"vol":"谷部"},"饴糖":{"qi":"甘，大温，无毒。入太阴经。宗奭曰︰多食动脾风。震亨曰︰饴糖属土而成于火，大发湿中之热。寇氏谓其动脾风，言末而遗本矣。时珍曰︰凡中满吐逆、秘结牙、赤目疳病者，切宜忌之，生痰动火最甚。甘属土，肾病毋多食甘，甘伤肾，骨痛而齿落，皆指此类也。","zhi":"补虚乏，止渴去血（《别录》）。补虚冷，益气力，止肠鸣咽痛，治唾血，消痰润肺止嗽（思邈）。健脾胃，补中，治吐血。打损瘀血者，熬焦酒服，能下恶血。又伤寒大毒嗽，于蔓菁、薤汁中煮一沸，顿服之，良（孟诜）。脾弱不思食人少用，能和胃气。亦用和药","fufang":[{"text":"寒食大麦一升，水七升，煎五升，入赤饧二合，渴即饮之。","src":"奉亲书"},{"text":"蛟龙症病，凡人正二月食芹菜，误食蛟龙精面色青黄︰每服寒食饧五合，日三服。吐出蛟龙，有两头可验。吐蛔者勿用。","src":"金匮要略"},{"text":"鱼脐疔疮︰寒食饧涂之，良。干者烧灰。","src":"千金方"},{"text":"瘭疽毒疮︰腊月饴糖，昼夜涂之，数日则愈。","src":"千金方"},{"text":"误吞稻芒︰白饧频食。","src":"简便方"},{"text":"鱼骨咽，不能出︰用饴糖丸鸡子黄大吞之。不下再吞。（《肘误吞钱钗及竹木︰取饴糖一斤，渐渐食尽，便出。","src":"外台"},{"text":"箭镞不出︰见发明。服药过剂，闷乱者︰饴糖食之。","src":"千金"},{"text":"草乌头毒及天雄、附子毒︰并食饴糖即解。","src":"总录"}],"vol":"谷部"},"酱":{"qi":"咸，冷利，无毒。时珍曰︰面酱︰咸。豆酱、甜酱、豆油、大麦酱、麸酱︰皆咸、甘。诜曰︰多食发小儿无辜，生痰动气。妊娠合雀肉食之，令儿面黑。颂曰︰麦酱和鲤鱼食，生口疮。","zhi":"除热，止烦满，杀百药及热汤火毒（《别录》）。杀一切鱼、肉、菜蔬、蕈毒，并治蛇、虫、蜂、虿等毒（《日华》）。酱汁灌入下部，治大便不通。灌耳中，治飞蛾、虫、蚁入耳。涂犬咬及汤、火伤灼未成疮者，有效","fufang":[{"text":"酱清和蜜，温热浸之，愈乃止。","src":"千金"},{"text":"疡风驳︰酱清和石硫黄细末，日日揩之。","src":"外台秘要"},{"text":"妊娠下血︰豆酱二升，去汁取豆，炒研。酒服方寸匕，日三。","src":"妊娠尿血︰豆酱一大盏（熬干"},{"text":"生地黄二两，为末。每服一钱，米浸淫疮癣︰酱瓣和人尿，涂之。","src":"千金翼"}],"vol":"谷部"},"榆仁酱":{"qi":"辛美，温，无毒。","zhi":"利大小便、心腹恶气，杀诸虫。不宜多食（孟诜）。","fufang":[],"vol":"谷部"},"芜荑酱":{"qi":"辛美微臭，温，无毒。多食落发。","zhi":"杀三虫，功力强于榆仁酱（孟诜）。","fufang":[],"vol":"谷部"},"醋":{"qi":"酸、苦，温，无毒。诜曰︰大麦醋︰微寒。余醋并同。弘景曰︰多食损人肌脏。藏器曰︰多食损筋骨，亦损胃。不益男子，损人颜色。醋发诸药，不可同食。时珍曰︰酸属木，脾病毋多食酸。酸伤脾，肉服茯苓、丹参人，不可食醋。《镜源》曰︰米醋煮制四黄、丹砂、胆矾、常山诸药也。","zhi":"消痈肿，散水气，杀邪毒（《别录》）。理诸药，消毒（扁鹊）。治产后血运，除症块坚并产后及伤损金疮出血昏运，杀一切鱼、肉、菜毒（《日华》）。醋磨青木香，止卒心痛、血气痛。浸黄柏含之，治口疮。调大黄末，涂肿毒。煎生大黄服，治癖甚良（孟诜）。散瘀血，治黄胆、黄汗（好古曰︰张仲景治黄汗，有黄芍药桂枝苦酒汤；治黄胆，有麻黄醇酒汤，用苦酒清酒。方见《金匮","fufang":[{"text":"旧二十一，新十二。身体卒肿︰醋和蚯蚓屎敷之。","src":"千金"},{"text":"白虎风毒︰以三年酽醋五升，煎五沸，切葱白三升，煎一沸漉出，以布染乘热裹之，痛止乃已。","src":"外台秘要"},{"text":"霍乱吐利︰盐、醋，煎服甚良。","src":"如宜方"},{"text":"霍乱烦胀，未得吐下︰以好苦酒三升饮之。","src":"千金方"},{"text":"足上转筋︰以故绵浸醋中，甑蒸热裹之，冷即易，勿停，取瘥止。出汗不滴，瘦却腰脚，并耳聋者︰米醋浸荆三棱，夏四日，冬六日，为末。醋汤调下二钱，即瘥。","src":"经验后方"},{"text":"腋下胡臭︰三年酽酢，和锻石敷之。","src":"外台"},{"text":"疡风病︰酢和硫黄末敷之。","src":"外台秘要"},{"text":"痈疽不溃︰苦酒和雀屎如小豆大，敷疮头上，即穿也。（《肘后方舌肿不消︰以酢和釜底墨，浓敷舌之上下，脱则更敷，须臾即消。","src":"千金方"}],"vol":"谷部"},"酒":{"qi":"苦、甘、辛，大热，有毒。诜曰︰久饮伤神损寿，软筋骨，动气痢。醉卧当风，则成癜风。醉浴冷水成痛痺。服丹砂人饮之，头痛吐热。士良曰︰凡服丹砂、北庭、石亭脂、钟乳、诸石、生姜，并不可长用酒下，能引石药气藏器曰︰凡酒，忌诸甜物。酒浆照人无影，不可饮。祭酒自耗，不可饮。酒合乳饮，令人气结。同牛肉食，令人生虫。酒后卧黍穰，食猪肉，患大风。时珍曰︰酒后食芥及辣物，缓人筋骨。酒后饮茶，伤肾脏，腰脚重坠，膀胱冷痛，兼患痰饮水肿、消渴挛痛之疾。一切毒药，因酒得者难治。又酒得咸而解者，水制火也，酒性上而咸润下也。又畏枳、葛花、赤豆花、绿豆粉者","zhi":"行药势，杀百邪恶毒气（《别录》）。通血脉，浓肠胃，润皮肤，散湿气，消忧发怒，宣言畅意（藏器）。养脾气，扶肝，除风下气（孟诜）。解马肉、桐油毒，丹石发动诸病，热饮之糟底酒（三年腊糟下取之）开胃下食，暖水脏，温肠胃，消宿食，御风寒，杀一切蔬菜毒（《日华》）。止呕哕，摩风瘙、老酒（腊月酿造者，可经数十年不坏）和血养气，春酒（清明酿造者亦可经久）常服令人肥白（孟诜）。蠷尿疮，饮之至醉，须臾虫出如米也（李绛《兵部手集》）社坛余胙酒（《拾遗》）治小儿语迟，纳口中佳。又以喷屋四角，辟蚊子（藏器）。饮之治聋。时珍曰︰按︰《海录碎事》云︰俗传社酒治聋，故李涛有「社翁今日没心情，为寄治聋酒一瓶」之句。糟笋节中酒【气味】咸，平，无毒。【主治】饮之，主哕气呕逆，或加小儿乳及牛乳同服。又摩疡风（藏器）。东阳酒【气味】甘、辛，无毒。【主治】用制诸药良。","fufang":[{"text":"温酒灌之即醒。鬼击诸病，卒然著人，如刀刺状，胸胁腹内切痛，不可抑按，或吐血、鼻血、下血，一名鬼排︰以醇酒吹两鼻内，良。","src":"肘后"},{"text":"马气入疮或马汗、马毛入疮，皆致肿痛烦热，入腹则杀人。多饮醇酒，至醉即愈，妙。（《虎伤人疮︰但饮酒，常令大醉，当吐毛出。","src":"梅师"},{"text":"蛇咬成疮︰暖酒淋洗疮上，日三次。","src":"广利方"},{"text":"蜘蛛疮毒︰同上方。毒蜂螫人︰方同上。咽伤声破︰酒一合，酥一匕，干姜末二匕，和服，日二次。（《十三十年耳聋︰酒三升，渍牡荆子一升，七日去滓，任性饮之。（《天行余毒，手足肿痛欲断︰作坑深三尺，烧热灌酒，著屐踞坑上，以衣壅之，勿令泄气。","src":"类要方"},{"text":"下部痔疮︰掘地作小坑，烧赤，以酒沃之，纳吴茱萸在内坐之。不产后血闷︰清酒一升，和生地黄汁煎服。","src":"梅师"},{"text":"身面疣目，盗酸酒浮，洗而咒之曰︰疣疣，不知羞。酸酒浮，洗你头。急急如律令。咒七遍，自愈。","src":"外台"},{"text":"断酒不饮︰酒七升，朱砂半两，瓶浸紧封，安猪圈内，任猪摇动，七日取出，顿饮。又方︰正月一日酒五升，淋碓头杵下，取饮之。千止。","src":"千金方"},{"text":"丈夫脚冷不随，不能行者︰用淳酒三斗，水三斗，入瓮中，灰火温之，渍脚至膝。常著灰火，勿令冷，三日止。","src":"千金方"}],"vol":"谷部"},"烧酒":{"qi":"辛、甘，大热，有大毒。时珍曰︰过饮败胃伤胆，丧心损寿，甚则黑肠腐胃而死。与姜、蒜同食，令冷水、绿豆粉解其毒。","zhi":"消冷积寒气，燥湿痰，开郁结，止水泄，治霍乱疟疾噎膈，心腹死，杀虫辟瘴，利小便，坚大便，洗赤目肿痛，有效（时珍）。","fufang":[{"text":"烧酒入飞盐饮，即止。阴毒腹痛︰烧酒温饮，汗出即止。呕逆不止︰真火酒一杯，新汲井水一杯，和服甚妙。","src":"濒湖"}],"vol":"谷部"},"葡萄酒":{"qi":"甘、辛，热，微毒。时珍曰︰有热疾、齿疾、疮疹人，不可饮之。","zhi":"暖腰肾，驻颜色，耐寒（时珍）。烧酒【气味】辛、甘，大热，有大毒。时珍曰︰大热大毒，甚于烧酒。北人习而不觉，南人切不可轻生饮之。【主治】益气调中，耐饥强志（《正要》）。消痰破","fufang":[],"vol":"谷部"},"糟":{"qi":"甘、辛，无毒。","zhi":"温中消食，除冷气，杀腥，去草、菜毒，润皮肤，调脏腑（藏器）。扑损瘀血，浸水洗冻疮，捣敷蛇咬、蜂叮毒（《日华》）","fufang":[{"text":"红糟、腊猪脂、姜汁、盐等分，研烂，炒热擦之，裂内甚痛，少顷即合，再擦数次即安。","src":"袖珍方"},{"text":"鹤膝风病︰酒醅糟四两，肥皂一个。","src":"去子"},{"text":"芒硝一两，五味子一两，砂糖一两，姜汁半瓯。研匀，日日涂之。加入烧酒尤妙也。暴发红肿，痛不可忍者︰腊糟糟之。","src":"谈野翁《试验方"},{"text":"杖疮青肿︰用湿绵纸铺伤处，以烧过酒糟捣烂，浓铺纸上。良久，升即散。","src":"简便方"},{"text":"末一斤，入干糖糟。","src":""},{"text":"二斤半，生姜一斤半，红枣三百个。","src":"煮取肉焙干"},{"text":"通为末。逐日点汤服。","src":"摘玄"}],"vol":"谷部"},"米秕":{"qi":"甘，平，无毒。","zhi":"通肠开胃，下气，磨积块。作糗食不饥，充滑肤体，可以颐养（汪颖","fufang":[],"vol":"谷部"},"舂杵头细糠":{"qi":"辛、甘，热。震亨曰︰谷壳属金，糠之性则热也。","zhi":"卒噎，刮取含之（《别录》。亦可煎汤呷之）。烧研，水服方寸匕，令妇人易产（时珍。出《子母秘录》）。","fufang":[{"text":"旧一，新一。膈气噎塞，饮食不下︰用碓觜上细糠，蜜丸弹子大，时时含咽津液咽喉妨碍，如有物吞吐不利︰杵头糠、人参各一钱，石莲肉。","src":""},{"text":"一钱，水煎服，日三次。《圣济总录》）此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/谷之四&amp;oldid=2347216”分类：PD-old此页面最后编辑于2023年12月22日。","src":"星期五"},{"text":"14:17。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。","src":"请参阅使用条款"},{"text":"在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权。","src":"含署名权"},{"text":"Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501。","src":"c"}],"vol":"谷部"},"韭":{"qi":"辛、微酸，温，涩，无毒。时珍曰：生：辛、涩；熟：甘、酸。大明曰：热。宗奭曰：春食则香，夏食则臭，多食则能昏神暗目，酒后尤忌。诜曰：热病后十日食之，即发困。五月多食，乏气力。冬月多食，动宿饮，吐水。不可与蜜及牛肉同食。","zhi":"归心，安五脏，除胃中热，利病患，可久食（《别录》。时珍曰：案：《千金方》作可久食，不利病患。）叶：煮鲫鱼酢食，断卒下痢。根：入生发膏用（弘景）。根、叶：煮食，温中下气，补虚益阳，调和脏腑，令人能食，止泄血脓，腹中冷痛。生捣汁服，主胸痺骨痛不可触者，又解药毒，疗狂狗咬人数发者，亦涂诸蛇虺、蝎虿、恶虫毒（藏器）。煮食，充肺气，除心腹痼冷癖。捣汁服，治肥白人中风失音（《日华》）。煮食，归肾壮阳，止泄精，暖腰膝（宁原）。炸熟，以盐、醋空心吃十顿，治胸膈噎气。捣汁服，治胸痺刺痛如锥，即吐出胸中恶血甚验。又灌初生小儿，吐去恶水、恶血，永无诸病（诜）。主吐血唾血，衄血尿血，妇人经脉逆行，打扑伤损及膈噎病。捣汁澄清，和童尿饮之，能消散胃脘瘀血，甚效（震亨）。饮生汁，主上气喘息欲绝，解肉脯毒。煮汁饮，止消渴盗汗。熏产妇血运，洗肠痔脱肛（时珍）。","fufang":[{"text":"诜曰：胸痺痛如锥刺，不得俯仰，自汗出，或痛彻背上，不治或至死。可取生韭或根五斤，洗捣汁，服之。","src":"食疗本草"},{"text":"阴阳易病，男子阴肿，小腹绞痛，头重眼花，宜鼠屎汤煮之：用鼠屎十四枚，韭根一大把，水二盏，煮七分，去滓再煎二沸，温服，得汗愈。未汗再服。","src":"南阳活人书"},{"text":"伤寒劳复：方同上。卒然中恶：捣韭汁，灌鼻中，便苏。","src":"食医心镜"},{"text":"卧忽不寤，勿以火照之，但痛啮拇指甲际而唾其面则活：取韭捣汁吹入鼻中。冬月则用韭根。","src":"肘后方"},{"text":"风忤邪恶：韭根一把，乌梅十四个，吴茱萸。","src":""},{"text":"半升，水一斗煮之。仍以病患栉内入，煮三沸。栉浮者生，沉者死。煮至三升，分三服。","src":"金匮要略"},{"text":"喘息欲绝：韭汁饮一升，效。","src":"肘后"},{"text":"夜出盗汗：韭根四十九根。水二升，煮一升，顿服。","src":"千金方"}],"vol":"菜部"},"山韭":{"qi":"咸，寒，涩，无毒。","zhi":"宜肾，主大小便数，去烦热，治毛发（《千金》）。","fufang":[],"vol":"菜部"},"葱茎白":{"qi":"辛，平。叶：温。根须：平。并无毒。弘景曰：葱有寒热，白冷青热，伤寒汤中不得用青也。宗奭曰：葱主发散，多食昏人神。诜曰：葱宜冬月食。不可过多，损须发，发人虚气上冲，五脏闭绝，为其开骨节出汗之故也。思邈曰：正月食生葱，令人面上起游风。生葱同蜜食，作下利。烧葱同蜜食，壅气杀人。张仲景曰：生葱合枣食，令人病；合犬、雉肉食，多令人病血。时珍曰：服地黄、常山人，忌食葱。","zhi":"作汤，治伤寒寒热，中风面目浮肿，能出汗（《本经》）。伤寒骨肉碎痛，喉痺不通，安胎，归目益目睛，除肝中邪气，安中利五脏，杀百药毒。根：治伤寒头痛（《别录》）。主天行时疾，头痛热狂，霍乱转筋，及奔豚气、脚气，心腹痛，目眩，止心迷闷（大明）。通关节，止衄血，利大小便（孟诜）。治阳明下痢、下血（李杲）。达表和里，止血（宁原）。除风湿，身痛麻痺，虫积心痛，止大人阳脱，阴毒腹痛，小儿盘肠内钓，妇人妊娠溺血，通乳汁，散乳痈，利耳鸣，涂犬伤，制蚯蚓毒（时珍）。杀一切鱼、肉毒（士良）。","fufang":[{"text":"旧十二，新三十六。感冒风寒初起：即用葱白一握，淡豆豉半合，泡汤服之，取汗。","src":"濒湖集简方"},{"text":"伤寒头痛如破者：连须葱白半斤，生姜二两，水煮温服。","src":"活人书"},{"text":"时疾头痛，发热者：以连根葱白二十根，和米煮粥，入醋少许，热食取汗即解。","src":"济生秘览"},{"text":"数种伤寒，初起一、二日，不能分别者：用上法取汗。伤寒劳复，因交接者，腹痛卵肿：用葱白捣烂，苦酒一盏，和服之。","src":"千金方"},{"text":"风湿身痛：生葱擂烂，入香油数点，水煎，调川芎、郁金末一钱服，取吐。","src":"丹溪心法"},{"text":"妊娠伤寒，赤斑变为黑斑，尿血者：以葱白一把，水三升，煮热服汁，食葱令尽，取汗。","src":"伤寒类要"},{"text":"六月孕动，困笃难救者：葱白一大握，水三升，煎一升，去滓顿服。","src":"杨氏《产乳"},{"text":"胎动下血，腰痛抢心：杨氏产乳方：用葱白煮浓汁饮之。未死即安，已死即出。未效再服。一方：加川芎。一方：用银器同米煮粥及羹食。","src":"梅师方"}],"vol":"菜部"},"葱":{"qi":"辛，微温，无毒。时珍曰：佛家以葱为五荤之一（见蒜下）。","zhi":"除瘴气恶毒。久食，强志益胆气（思邈）。主诸恶、狐尿刺毒，山溪中沙虱、射工等毒。煮汁浸，或捣敷，大效。亦兼小蒜、茱萸辈，不独用也（苏恭）。子【气味】同葱。【主治】泄精（思邈）。","fufang":[],"vol":"菜部"},"胡葱":{"qi":"辛，温，无毒。时珍曰：生则辛平，熟则甘温。诜曰：亦是薰物。久食，伤神损性，令人多忘，损目明，绝血脉，发痼疾。患胡臭、齿人，食之转甚。思邈曰：四月勿食胡葱，令人气喘多惊。","zhi":"温中下气，消谷能食，杀虫，利五脏不足气（孟诜）。疗肿毒（保升）。","fufang":[{"text":"新一。身面浮肿，小便不利，喘急：用胡葱十茎，赤小豆三合，硝石一两，以水五升，煮葱、豆至熟，候水干，入硝石，同擂成膏。每空心温酒服半匙。","src":"圣惠方"}],"vol":"菜部"},"薤":{"qi":"辛、苦，温，滑，无毒。好古曰：入手阳明经。颂曰：薤宜去青留白，白冷而青热也。诜曰：发热病，不宜多食。三、四月勿食生者。大明曰：生食引涕唾。不可与牛肉同食，令人作症瘕。","zhi":"金疮、疮败。轻身，不饥，耐老（《本经》）。归骨，除寒热，去水气，温中，散结气。作羹食，利病人。诸疮、中风寒、水气肿痛，捣涂之（《别录》）。煮食，耐寒，调中补不足，止久痢冷泻，肥健人（《日华》）。治泄痢下重，能泄下焦阳明气滞（李杲。好古曰：下重者，气滞也。四逆散加此以泄气滞）。治少阴病厥逆泄痢，及胸痹刺痛，下气散血，安胎（时珍）。心病宜食之。利产妇（思邈）。治女人带下赤白，作羹食之。骨哽在咽不去者，食之即下（孟诜）。补虚解毒（苏颂）。白者补益，赤者疗金疮及风，生肌肉（苏恭）。与蜜同捣，涂汤火伤，效甚速（宗奭）。温补，助阳道（时珍）。","fufang":[{"text":"张仲景栝蒌薤白汤：治胸痺，痛彻心背，喘息咳唾短气，喉中燥痒，寸脉沉迟，关脉弦数，不治杀人。用栝蒌实一枚，薤白半升，白酒七升，煮二升，分二服。《千金》治胸痺，半夏薤白汤：用薤白四两，半夏一合，枳实半两，生姜一两，栝蒌实半枚，咀，以白浆三升，煮一升，温服，日三。《肘后》治胸痺，瘥而复发。薤根五升，捣汁饮之，立瘥。音在，酢浆也。卒中恶死卒死，或先病，或平居寝卧奄忽而死，皆是中恶。以薤汁灌入鼻中，便省。","src":"肘后"},{"text":"霍乱干呕不止者：以薤一虎口，以水三升，煮取一半，顿服。不过三作即已。","src":"韦宙《独行方"},{"text":"奔豚气痛：薤白捣汁饮之。","src":"肘后方"},{"text":"赤痢不止：薤同黄柏煮汁服之。","src":"陈藏器"},{"text":"赤白痢下：薤白一握，同米煮粥，日食之。","src":"食医心镜"},{"text":"小儿疳痢：薤白生捣如泥，以粳米粉和蜜作饼，炙熟与食。不过三两服。","src":"杨氏《产乳"},{"text":"产后诸痢：多煮薤白食，仍以羊肾脂同炒食之。","src":"范汪方"},{"text":"妊娠胎动，腹内冷痛：薤白一升，当归四两。水五升，煮二升，分三服。","src":"古今录验"}],"vol":"菜部"},"蒜":{"qi":"辛，温，有小毒。弘景曰：味辛性热。损人，不可长食。思邈曰：无毒。三月勿久食，伤人志性。黄帝书云：同生鱼食，令人夺气，阴核疼。瑞曰：脚气风病患，及时病后，忌食之。","zhi":"归脾肾，主霍乱，腹中不安，消谷，理胃温中，除邪痺毒气（《别录》）。主溪毒（弘景）。下气，治蛊毒，敷蛇、虫、沙虱疮（《日华》。恭曰：此蒜与胡葱相得。主恶毒、山溪中沙虱、水毒，大效。山人、俚獠时用之）。涂疔肿甚良（孟诜）。叶【主治】心烦痛，解诸毒，小儿丹疹（思邈）。","fufang":[{"text":"旧七，新七。时气温病，初得头痛，壮热脉大：即以小蒜一升，杵汁三合，顿服。不过再作便愈。","src":"肘后方"},{"text":"霍乱胀满，不得吐下，名干霍乱：小蒜一升，水三升，煮一升，顿服。","src":"肘后方"},{"text":"霍乱转筋，入腹杀人：以小蒜、盐各一两，捣敷脐中，灸七壮，立止。","src":"圣济录"},{"text":"积年心痛不可忍，不拘十年、五年者，随手见效：浓醋煮小蒜食饱，勿著盐。曾用之有效，再不发也。","src":"兵部手集"},{"text":"水毒中人：一名中溪，一名中湿，一名水病，似射工而无物。初得恶寒，头目微疼，旦醒暮剧，手足逆冷。三日则生虫，食人下部，肛中有疮，不痒不痛。过六、七日虫食五脏，注下不禁：以小蒜三升，煮微热。","src":"大热即无力"},{"text":"以浴身。若身发赤斑纹者，毋以他病治之也。","src":"肘后方"},{"text":"射工中人成疮者：取蒜切片，贴疮上，灸七壮。","src":"千金"},{"text":"止截疟疾：小蒜不拘多少，研泥，入黄丹少许，丸如芡子大。每服一丸，面东新汲水下，至妙。","src":"唐慎微"}],"vol":"菜部"},"山蒜":{"qi":"辛，温，无毒。","zhi":"山蒜：治积块，及妇人血瘕，用苦醋磨服多效（苏颂）。泽蒜、石蒜：并温补下气，滑水源（藏器）。","fufang":[],"vol":"菜部"},"葫":{"qi":"辛，温，有毒。久食损人目。弘景曰：性最熏臭，不可食。俗人作齑以啖肉，损性伐命，莫此之甚。惟可生食，不中煮也。恭曰：此物煮羹为馔中之俊，而陶云不中煮，当是未经试耳。藏器曰：初食不利目，多食却明。久食令人血清，使毛发白。时珍曰：久食伤肝损眼。故嵇康《养生论》云：荤辛害目，此为甚耳。今北人嗜蒜宿炕，故盲瞽最多。陈氏乃云多食明目，与《别录》相左，何耶？震亨曰：大蒜属火，性热喜散，快膈，善化肉，暑月人多食之。伤气之祸，积久自见，养生者忌之。化肉之功，不足论也。瑞曰：多食伤肺、伤脾、伤肝胆，生痰助火昏神。思邈曰：四月、八月食葫，伤神，令人喘悸，胁肋气急，口味多爽。多食生葫行房，伤肝气，令人面无色。生葫合青鱼食，令人腹内生疮，肠中肿，又成疝瘕，发黄疾。合蜜食，杀人。凡服一切补药，不可食之。","zhi":"归五脏，散痈肿疮，除风邪，杀毒气（《别录》）。下气，消谷，化肉（苏恭）。去水恶瘴气，除风湿，破冷气，烂癖，伏邪恶，宣通温补，疗疮癣，杀鬼去痛（藏器）。健脾胃，治肾气，止霍乱转筋腹痛，除邪祟，解温疫，去盅毒，疗劳疟冷风，敷风损冷痛，恶疮、蛇虫、溪毒、沙虱，并捣贴之。熟醋浸，经年者良（《日华》）。温水捣烂服，治中暑不醒。捣贴足心，止鼻衄不止。和豆豉丸服，治暴下血，通水道（宗）。捣汁饮，治吐血心痛。煮汁饮，治角弓反张。同鲫鱼丸，治膈气。同蛤粉丸，治水肿。同黄丹丸，治痢疟、孕痢。同乳香丸，治腹痛。捣膏敷脐，能达下焦，消水，利大小便。贴足心，能引热下行，治泄泻暴痢及干湿霍乱，止衄血。纳肛中，能通幽门，治关格不通（时珍）。","fufang":[{"text":"旧十五，新三十二。背疮灸法：凡觉背上肿硬疼痛，用湿纸贴寻疮头。用大蒜十颗，淡豉半合，乳香一钱，细研。随疮头大小，用竹片作圈围定，填药于内，二分浓，著艾灸之。痛灸至痒，痒灸至痛，以百壮为率。与蒜钱灸法同功。","src":"外科精要"},{"text":"疔肿恶毒：用门臼灰一撮罗细，以独蒜或新蒜苔染灰擦疮口，候疮自然出少汁，再擦，少顷即消散也。虽发背痈肿，亦可擦之。五色丹毒无常色，及发足踝者：捣蒜浓敷，干即易之。","src":"肘后方"},{"text":"关格胀满，大小便不通：独头蒜烧熟去皮，绵裹纳下部，气立通也。","src":"外台秘要"},{"text":"干湿霍乱转筋：用大蒜捣涂足心，立愈。","src":"永类钤方"},{"text":"水气肿满：大蒜、田螺、车前子等分。熬膏。摊贴脐中，水从便漩而下，数日即愈。象山民人患水肿，一卜者传此，用之有效。","src":"仇远《稗史"},{"text":"山岚瘴气：生、熟大蒜各七片，共食之。少顷腹鸣，或吐血，或大便泄，即愈。","src":"摄生众妙方"},{"text":"疟疾寒热《肘后》：用独头蒜炭上烧之，酒服方寸匕。《简便》：用桃仁半片，放内关穴上，将独蒜捣烂罨之，缚住。","src":"男左女右"},{"text":"即止。邻妪用此治人屡效。《普济方》：端午日，取独头蒜煨熟，入矾红等分，捣丸芡子大，每白汤嚼下一丸。寒疟冷痢：端午日，以独头蒜十个，黄丹二钱，捣丸梧子大。每服九丸，长流水下，甚妙。","src":"普济方"}],"vol":"菜部"},"五辛菜":{"qi":"辛，温，无毒。藏器曰：热病后食，多损目。","zhi":"岁朝食之，助发五脏气。常食，温中去恶气，消食下气（藏器）。","fufang":[],"vol":"菜部"},"芸苔":{"qi":"辛，温，无毒。大明曰：凉。《别录》曰：春月食之，能发膝痼疾。诜曰：先患腰脚者，不可多食，食之加剧。又损阳气，发疮及口齿病。胡臭人不可食。又能生腹中诸虫。道家特忌，以为五荤之一。","zhi":"风游丹肿，乳痈（《唐本草》）。破症瘕结血（《开宝》）。治产后血风及瘀血（《日华》）。煮食，治腰脚痺。捣叶，敷女人吹奶（藏器）。治瘭疽、豌豆疮，散血消肿。伏蓬砂（时珍）。","fufang":[{"text":"方见上。天火热疮，初起似痱，渐如水泡，似火烧疮，赤色，急速能杀人：芸苔叶捣汁，调大黄、芒硝、生铁衣等分，涂之。","src":"近效方"},{"text":"风热肿毒：芸苔苗叶根、蔓荆根各三两，为末，以鸡子清和贴之，即消。无蔓荆，即以商陆根代之，甚效也。","src":"近效方"},{"text":"手足瘭疽，此疽喜著手足肩背，累累如赤豆，剥之汁出：用芸苔叶煮汁服一升，并食干熟菜数顿，少与盐、酱。冬月用子研水服。","src":"千金方"},{"text":"异疽似痈，而小有异，脓如小豆汁，今日去，明日满：用芸苔捣熟，湿布袋盛，于热灰中煨熟，更互熨之，不过三、二度。无叶用干者。","src":"千金"},{"text":"豌豆斑疮：芸苔叶煎汤洗之。","src":"外台秘要"},{"text":"血痢腹痛，日夜不止：以芸苔叶捣汁二合，入蜜一合，温服。","src":"圣惠方"},{"text":"取油敷头，令发长黑。","src":"藏器"},{"text":"行滞血，破冷气，消肿散结，治产难、产后心腹诸疾，赤丹热肿，金疮血痔。","src":"时珍"}],"vol":"菜部"},"菘":{"qi":"甘，温，无毒。大明曰：凉，微毒。多食发皮肤风瘙痒。诜曰：发风冷内虚人不可食，有热人食亦不发病，性冷可知。《本草》言性温，未解其意。弘景曰：性和利人，多食似小冷。张仲景言药中有甘草，食菘即令病不除也。颂曰：有小毒不可食多，多则以生姜解之。瑞曰：夏至前食，发气动疾。有足疾者忌之。时珍曰：气虚胃冷人多食，恶心吐沫，气壮人则相宜。","zhi":"通利肠胃，除胸中烦，解酒渴（《别录》）。消食下气，治瘴气，止热气嗽。冬汁尤佳（萧炳）。和中，利大小便（宁原）。","fufang":[{"text":"旧一，新二。小儿赤游，行于上下，至心即死：菘菜捣敷之，即止。","src":"张杰《子母秘录"},{"text":"漆毒生疮：白菘菜捣烂涂之。飞丝入目：白菜揉烂帕包，滴汁三、二点入目，即出。","src":"普济方"}],"vol":"菜部"},"芥":{"qi":"辛，温，无毒。诜曰：煮食动气与风，生食发丹石，不可多食。大叶者良，细叶有毛者害人。宁原曰：有疮疡、痔疾、便血者忌之。思邈曰：同兔肉食，成恶邪病。同鲫鱼食，发水肿。","zhi":"归鼻，除肾经邪气，利九窃，明耳目，安中。久食温中（《别录》）。止咳嗽上气，除冷气（《日华》）。主咳逆下气，去头面风（孟诜）。通肺豁痰，利膈开胃（时珍）。","fufang":[{"text":"芥菜秆烧存性，研末，频敷之，即愈。飞丝入目：青菜汁点之如神。","src":"摘玄方"},{"text":"漆疮搔痒：芥菜煎汤，洗之。","src":"千金方"},{"text":"痔疮肿痛：芥叶捣饼，频坐之。","src":"谈野翁《经效方"},{"text":"疰气发无常处，及射工毒，丸服之，或捣末醋和涂之，随手有验。","src":"苏恭"},{"text":"治风毒肿及麻痺，醋研敷之。扑损瘀血，腰痛肾冷，和生姜研涂贴之。又治心痛，酒调服之。","src":"日华"},{"text":"研末作酱食，香美，通利五脏。","src":"孟诜"},{"text":"研末水调，涂顶囟，止衄血。","src":"吴瑞"},{"text":"温中散寒，豁痰利窍，治胃寒吐食，肺寒咳嗽，风冷气痛，口噤唇紧，消散痈肿瘀血。","src":"时珍"}],"vol":"菜部"},"白芥":{"qi":"辛，温，无毒。时珍曰：《肘后方》言热病患不可食胡芥，为其性暖也。","zhi":"冷气（藏器）。安五脏，功与芥同（《日华》）。子【气味】辛，温，无毒。【主治】发汗，主胸膈痰冷，上气，面目黄赤。又醋研，敷射工毒（《别录》）。御恶气遁尸飞尸，及暴风毒肿流四肢疼痛（弘景）。烧烟及服，辟邪魅（《日华》。藏器曰：入镇宅方用。咳嗽，胸胁支满，上气多唾者，每用温酒吞下七粒（思邈）。利气豁痰，除寒暖中，散肿止痛，治喘嗽反胃，痺木脚气，筋骨腰节诸痛（时珍）。","fufang":[{"text":"白芥子末，酒服一、二钱。","src":"普济方"},{"text":"热痰烦运：白芥子、黑芥子、大戟、甘遂、芒硝、朱砂等分为末，糊丸梧子大。每服二十丸，姜汤下。名白芥丸。","src":"普济"},{"text":"冷痰痞满：黑芥子、白芥子、大戟、甘遂、胡椒、桂心等分，为末，糊丸梧子大。每服十丸，姜汤下。名黑芥丸。","src":"普济方"},{"text":"腹冷气起：白芥子一升。微炒研末，汤浸蒸饼丸小豆大。每姜汤吞十丸，甚妙。","src":"续传信方"},{"text":"脚气作痛：方见白芷。小儿乳癖：白芥子研末，水调摊膏贴之，以平为期。","src":"本草权度"},{"text":"防痘入目：白芥子末，水调涂足心，引毒归下，令疮疹不入目。","src":"全幼心鉴"},{"text":"肿毒初起：白芥子末，醋调涂之。","src":"濒湖集简方"},{"text":"胸胁痰饮：白芥子五钱，白术一两。为末，枣肉和捣，丸梧子大，每白汤服五十丸。","src":"摘玄方"}],"vol":"菜部"},"芜菁":{"qi":"苦，温，无毒。时珍曰：辛、甘、苦。宗奭曰：多食动气。","zhi":"利五脏，轻身益气，可长食之（《别录》）。常食通中，令人肥健（苏颂）。消食，下气治嗽，止消渴，去心腹冷痛，及热毒风肿，乳痈妒乳寒热（孟诜）。","fufang":[{"text":"立春后遇庚子日，温蔓荆汁，合家大小并服之，不限多少，一年可免时疾。","src":"神仙教子法"},{"text":"鼻中衄血：诸葛菜，生捣汁饮。","src":"十便良方"},{"text":"大醉不堪，连日病困者：蔓荆菜，入少米煮熟，去滓，冷冻饮料之良。","src":"肘后方"},{"text":"饮酒辟气：干蔓荆根二七枚，蒸三遍，碾末。酒后水服二钱，即无酒气也。","src":"千金"},{"text":"一切肿毒：孙真人食忌：生蔓荆根一握，入盐花少许，同捣封之，日三易之。《肘后方》：用蔓荆叶不中水者，烧灰和腊猪脂封之。疔肿有根：用大针刺作孔，削蔓荆根如针大，染铁生衣刺入孔中。再以蔓荆根、铁生衣等分，捣涂于上。有脓出即易，须臾根出立瘥。忌油腻、生冷、五辛、粘滑、陈臭。","src":"肘后"},{"text":"乳痈寒热：蔓荆根并叶，去土，不用水洗，以盐和捣涂之。热即换，不过三、五次即瘥。冬月只用根。此方已救十数人。须避风。","src":"李绛《兵部手集"},{"text":"女子妒乳：生蔓荆根捣，和盐、醋、浆水煮汁洗之，五、六度良。又捣：和鸡子白封之亦妙。","src":"食疗"},{"text":"阴肿如斗：生蔓荆根捣封之，治人所不能治者。","src":"集疗方"}],"vol":"菜部"},"莱菔":{"qi":"根辛、甘，叶辛、苦，温，无毒。诜曰：性冷。思邈曰：平。不可与地黄同食，令人发白，为其涩营卫也。时珍曰：多食莱菔动气，惟生姜能制其毒。又伏砂。","zhi":"散服及炮煮服食，大下气，消谷和中，去痰癖，肥健人；生捣汁服，止消渴，试大有验（《唐本》）。利关节，理颜色，练五脏恶气，制面毒，行风气，去邪热气（萧炳）。利五脏，轻身，令人白净肌细（孟诜）。消痰止咳，治肺痿吐血，温中补不足。同羊肉、银鱼煮食，治劳瘦咳嗽（《日华》）。同猪肉食，益人。生捣服，治禁口痢（汪颖）。捣汁服，治吐血衄血（吴瑞）。宽胸膈，利大小便。生食，止渴宽中；煮食，化痰消导（宁原）。杀鱼腥气，治豆腐积（汪机）。主吞酸，化积滞，解酒毒，散瘀血，甚效。末服，治五淋。丸服，治白浊。煎汤，洗脚气。饮汁，治下痢及失音，并烟熏欲死。生捣，涂打扑、汤火伤（时珍）。","fufang":[{"text":"萝卜，生嚼数片，或生菜嚼之亦佳，绝妙。干者、熟者、盐腌者，及人胃冷者，皆不效。","src":"濒湖集简方"},{"text":"反胃噎疾：萝卜，蜜煎浸，细细嚼咽良。","src":"普济方"},{"text":"消渴饮水：独胜散：用出了子萝卜三枚，净洗切片，晒干为末。每服二钱，煎猪肉汤澄清调下，日三服，渐增至三钱。生者捣汁亦可，或以汁煮粥食之。","src":"图经本草"},{"text":"肺痿咳血：萝卜，和羊肉或鲫鱼，煮熟频食。","src":"普济方"},{"text":"鼻衄不止：萝卜，捣汁半盏，入酒少许热服，并以汁注鼻中皆良。或以酒煎沸，入萝卜再煎，饮之。","src":"卫生易简方"},{"text":"一小盏，蜜一盏。水一盏，同煎。早一服，午一服。日晡米饮吞阿胶丸百粒。如无萝卜，以子擂汁亦可。一方：加枯矾七分，同煎。一方：只用萝卜菜煎汤，日日饮之。《普济方》：用萝卜片，不拘新旧，染蜜噙之，咽汁。味淡再换。觉思食，以肉煮粥与食，不可过多。痢后肠痛：方同上。大肠便血：大萝卜皮。","src":"烧存性"},{"text":"等分为末。每服一钱，米饮下。","src":"普济"},{"text":"肠风下血：蜜炙萝卜，任意食之。昔一妇人服此有效。","src":"百一选方"}],"vol":"菜部"},"生姜":{"qi":"辛，微温，无毒。藏器曰：生姜温，要热则去皮，要冷则留皮。元素曰：辛而甘温，气味俱浓，浮而升，阳也。之才曰：秦椒为之使。杀半夏、莨菪毒。恶黄芩、黄连、天鼠粪。弘景曰：久服少志少智，伤心气。今人啖辛辣物，惟此最常。故《论语》云：每食不撤姜。言可常食，但不可多尔。有病者是所宜矣。恭曰：《本经》言姜久服通神明，主痰气，即可常啖。陶氏谬为此说，检无所据。思邈曰：八、九月多食姜，至春多患眼，损寿减筋力。孕妇食之，令儿盈指。杲曰：古人言：秋不食姜，令人泻气。盖夏月火旺，宜汗散之，故食姜不禁。辛走气泻肺，故秋月则禁之。《晦庵语录》亦有秋姜夭人天年之语。时珍曰：食姜久，积热患目，珍屡试有准。凡病痔人多食兼酒，立发甚速。痈疮人多食，则生恶肉。此皆昔人所未言者也。《相感志》云：糟姜瓶内入蝉蜕，虽老姜无筋，亦物性有所伏耶？","zhi":"久服去臭气，通神明（《本经》）。归五脏，除风邪寒热，伤寒头痛鼻塞，咳逆上气，止呕吐，去痰下气（《别录》）。去水气满，疗咳嗽时疾。和半夏，主心下急痛。又汁和杏仁作煎，下一切结气实，心胸拥隔冷热气，神效。捣汁和蜜服，治中热呕逆不能下食（甄权）。散烦闷，开胃气。汁作煎服，下一切结实，冲胸膈恶气，神验（孟诜）。破血调中，去冷气。汁，解药毒（藏器）。除壮热，治痰喘胀满，冷痢腹痛，转筋心满，去胸中臭气、狐臭，杀腹内长虫（张鼎）。益脾胃，散风寒（元素）。解菌蕈诸物毒（吴瑞）。生用发散，熟用和中。解食野禽中毒成喉痺。浸汁，点赤眼。捣汁和黄明胶熬，贴风湿痛甚妙（时珍）。干生姜【主治】治嗽温中，治胀满，霍乱不止，腹痛，冷痢，血闭。病患虚而冷，宜加之（甄权）。姜屑，和酒服，治偏风（孟诜）。肺经气分之药，能益肺（好古）。","fufang":[{"text":"一两，水五升，煮取二升，分再服。忌猪肉、冷水。","src":"千金"},{"text":"胃虚风热不能食：用姜汁半杯，生地黄汁少许，蜜一匙，水二合，和服之。","src":"食疗本草"},{"text":"疟疾寒热，脾胃聚痰，发为寒热：生姜四两，捣自然汁一酒杯，露一夜。于发日五更面北立，饮即止。未止再服。","src":"易简"},{"text":"寒热痰嗽初起者：烧姜一块，含咽之。","src":"本草衍义"},{"text":"咳嗽不止：生姜五两，饧半升。微火煎熟，食尽愈。段侍御用之有效。","src":"孟诜《必效方"},{"text":"久患咳噫：生姜汁半合，蜜一匙，煎熟，温呷三服愈。","src":"外台秘要方"},{"text":"小儿咳嗽：生姜四两，煎汤浴之。","src":"千金方"},{"text":"暴逆气上：嚼姜两、三片，屡效。","src":"寇氏《衍义"}],"vol":"菜部"},"干姜":{"qi":"辛，温，无毒。褚曰：苦、辛。好古曰：大热。恭曰：久服令人目暗。余同生姜。时珍曰：《太清外术》言：孕妇不可食干姜，令胎内消。盖其性热而辛散故也。","zhi":"胸满，咳逆，上气，温中，止血，出汗，逐风、湿、痺，肠澼，下痢，生者尤良（《本经》）。寒冷，腹痛，中恶，霍乱，胀满，风邪，诸毒，皮肤间结气，止唾血（《别录》）。治腰肾中疼冷、冷气，破血，去风，通四肢关节，开五脏六腑，宣诸络脉，去风毒，冷痺，夜多小便（甄权）。消痰下气，治转筋吐泻，腹脏冷，反胃干呕，瘀血扑损，止鼻洪，解冷热毒，开胃，消宿食（大明）。主心下寒痞，目睛久赤（好古）。","fufang":[{"text":"旧十三，新十五。脾胃虚冷，不下食，积久羸弱成瘵者：用温州白干姜，浆水煮透，取出焙干捣末，陈廪米煮粥饮丸梧子大。每服三、五十丸，白汤下。其效如神。","src":"苏颂《图经"},{"text":"脾胃虚弱，饮食减少，易伤难化，无力肌瘦：用干姜频研四两，以白饧切块，水浴过，入铁铫溶化，和丸梧子大。每空心米饮下三十丸。","src":"十便方"},{"text":"头晕吐逆，胃冷生痰也：用川干姜。","src":""},{"text":"一钱二分。水一钟半，煎减半服。累用有效。","src":"传信适用方"},{"text":"心脾冷痛，暖胃消痰：二姜丸：用干姜、高良姜等分。炮研末，糊丸梧子大。每食后，猪皮汤下三十丸。","src":"和剂局方"},{"text":"心气卒痛：干姜末，米饮服一钱。","src":"外台秘要"},{"text":"阴阳易病伤寒后，妇人得病虽瘥，未满百日，不可与男合。为病拘急，手足拳，腹痛欲死，丈夫名阴易，妇人名阳易，速宜汗之即愈。满四日，不可治也：用干姜四两，为末。每用半两，白汤调服。覆衣被出汗后，手足伸即愈。","src":"伤寒类要》方"},{"text":"中寒水泻：干姜炮研末，粥饮服二钱，即效。","src":"千金方"}],"vol":"菜部"},"茼蒿":{"qi":"甘、辛，平，无毒。禹锡曰：多食动风气，熏人心，令人气满。","zhi":"安心气，养脾胃，消痰饮。利肠胃（思邈）。","fufang":[],"vol":"菜部"},"邪蒿":{"qi":"辛，温、平，无毒。诜曰：生食微动风，作羹食良。不与胡荽同食，令人汗臭气。","zhi":"胸膈中臭烂恶邪气，利肠胃，通血脉，续不足气（孟诜）。煮熟，和酱、醋食，治五脏恶邪气厌谷者，治脾胃肠，大渴热中，暴疾恶疮（《食医心镜》）。","fufang":[],"vol":"菜部"},"胡荽":{"qi":"辛，温，微毒。诜曰：平、微寒，无毒。可和生菜食。此是荤菜，损人精神。华佗云；胡臭、口臭、齿及脚气、金疮人，皆不可食，病更加甚。藏器曰：久食令人多忘。根，发痼疾。不可同邪蒿食，令人汗臭难瘥。时珍曰：凡服一切补药及药中有白术、牡丹者，不可食此。伏石钟乳。","zhi":"消谷，治五脏，补不足，利大小肠，通小腹气，拔四肢热，止头痛，疗沙疹、豌豆疮不出，作酒喷之，立出。通心窍（《嘉》）。补筋脉，令人能食。治肠风，用热饼裹食，甚良（孟诜）。合诸菜食，气香，令人口爽，辟飞尸、鬼疰、蛊毒（吴瑞）。辟鱼、肉毒（宁原）。","fufang":[{"text":"以酒二大盏煎沸沃之，以物盖定，勿令泄气。候冷去滓，微微含喷，从项背至足令遍。勿头面。","src":"经验后方"},{"text":"热气结滞，经年数发者：胡荽半斤，五月五日采，阴干，水七升，煮取一升半，去滓分服。未瘥更服。春夏叶、秋冬根茎并可用。","src":"必效方"},{"text":"孩子赤丹：胡荽汁涂之。","src":"谭氏方"},{"text":"面上黑子：荽煎汤，日日洗之。","src":"小说"},{"text":"产后无乳：干胡荽，煎汤饮之效。","src":"经验方"},{"text":"小便不通：胡荽二两，葵根一握。水二升，煎一升，入滑石末一两，分三、四服。","src":"圣济总录"},{"text":"肛门脱出：胡荽切一升，烧烟熏之，即入。","src":"子母秘录"},{"text":"解中蛊毒：胡荽根捣汁半升，和酒服，立下神验。","src":"必效方"}],"vol":"菜部"},"胡萝卜":{"qi":"甘、辛，微温，无毒。","zhi":"下气补中，利胸膈肠胃，安五脏，令人健食，有益无损（时珍）。子【主治】久痢（时珍）。","fufang":[],"vol":"菜部"},"水斳":{"qi":"甘，平，无毒。思邈曰：苦、酸，冷，涩，无毒。诜曰：和醋食，损齿。鳖瘕不可食。李鹏飞曰：赤芹害人，不可食。","zhi":"女子赤沃，止血养精，保血脉，益气，令人肥健嗜食（《本经》）。去伏热，杀石药毒，捣汁服（孟诜）。饮汁，去小儿暴热，大人酒后热，鼻塞身热，去头中风热，利口齿，利大小肠（藏器）。治烦渴，崩中带下，五种黄病（大明）。","fufang":[{"text":"芹菜切细，煮汁饮之，不拘多少。","src":"子母秘录"},{"text":"小便淋痛：水芹菜白根者，去叶捣汁，井水和服。","src":"圣惠方"},{"text":"小便出血：水芹捣汁，日服六、七合。","src":"圣惠方"}],"vol":"菜部"},"堇":{"qi":"甘，寒，无毒。","zhi":"捣汁，洗马毒疮，并服之。又涂蛇蝎毒及痈肿（《唐本》）。久食，除心下烦热，主寒热鼠，瘰&#30311;生疮，结核聚气，下瘀血，止霍乱。又生捣汁半升服，能杀鬼毒，即吐出（孟诜）。","fufang":[{"text":"堇菜，晒干为末，油煎成膏。摩之，日三、五度，便瘥。","src":"孟诜《食疗"},{"text":"湿热气：旱芹菜晒干为末，糊丸梧子大。每服四十丸，空心温酒下。大杀百虫毒。","src":"寿域神方"},{"text":"蛇咬疮：生杵堇汁涂之。","src":"万毕术"}],"vol":"菜部"},"紫堇":{"qi":"酸，平，微毒。花【气味】酸，微温，无毒。","zhi":"大人、小儿脱肛（苏颂）。","fufang":[{"text":"旧一。脱肛，凡大人、小儿脱肛，每天冷及吃冷食，即暴痢不止，肛则下脱，久疗不瘥者：春间收紫堇花二斤，曝干为散，加磁毛末七两，相和研细。涂肛上纳入，即使人冷水于面上，即吸入肠中。每日一涂药面，不过六、七度即瘥矣。又以热酒半升，和散一方寸匕，空腹服之，日再服。渐加至二方寸匕，以瘥为度。若五岁以下小儿，即以半杏子许，和酒服之。忌生冷、陈仓米等物。","src":"天宝单方"}],"vol":"菜部"},"马蕲":{"qi":"甘、辛，温，无毒。","zhi":"益脾胃，利胸膈，去冷气，作茹食（时珍）。子【气味】甘、辛，温，无毒。【主治】心腹胀满，开胃下气消食，调味用之（《唐本》）。炒研醋服，治卒心痛，令人得睡（孟诜）。温中暖脾，治反胃（时珍）。","fufang":[{"text":"马芹子、丁香、白僵蚕等分，为末。每服一钱，炙橘皮煎汤下。名醒脾散。","src":"普济方"}],"vol":"菜部"},"茴香":{"qi":"辛，平，无毒。思邈曰：苦、辛，微寒，涩。权曰：苦、辛。得酒良。炒黄用。好古曰：阳也，浮也。入手、足少阴、太阳经。","zhi":"诸、霍乱及蛇伤（《唐本》）。膀胱胃间冷气及育肠气，调中，止痛、呕吐（马志）。治干湿脚气，肾劳疝阴疼，开胃下食（大明）。补命门不足（李杲）。暖丹田（吴绶）。","fufang":[{"text":"茴香二两，生姜四两，同捣匀，入净器内，湿纸盖一宿。次以银石器中，文武火炒黄焦为末，酒糊丸梧子大。每服十丸至二十五丸，温酒下。","src":"经验后方"},{"text":"瘴疟发热，连背项者：茴香子，捣汁服之。","src":"孙真人方"},{"text":"大小便闭，鼓胀气促：八角茴香七个，大麻仁半两。为末。生葱白三七根，同研煎汤，调五苓散末服之，日一服。","src":"普济"},{"text":"小便频数：茴香不以多少，淘净，入盐少许，炒研为末，炙糯米糕蘸食之。伤寒脱阳，小便不通：用茴香末，以生姜自然汁调敷腹上。外用茴香末，入益元散服之。","src":"摘玄方"},{"text":"肾消饮水，小便如膏油：用茴香。","src":""},{"text":"等分为末。每食前酒服二钱。","src":"保命集"},{"text":"肾邪冷气，力弱者：用大茴香六两，分作三分；用生附子一个去皮，分作三分。第一度：用附子一分，茴香一分，同炒黄，出火毒一夜，去附子，研茴香为末，空心盐酒下一钱。第二度：用二味各一分，同炒存性，出火毒，以附子去一半，留一半，同茴香为末，如前服。第三度：各一分，同炒存性，出火毒，全研为末，如前服之。","src":"朱氏集验方"},{"text":"肾虚腰痛：茴香炒研，以猪腰子批开，掺末入内，湿纸裹煨熟。空心食之，盐酒送下。","src":"戴原礼《要诀"}],"vol":"菜部"},"莳萝":{"qi":"辛，温，无毒。","zhi":"下气利膈（时珍）。子【气味】辛，温，无毒。【主治】小儿气胀，霍乱呕逆，腹冷不下食，两肋痞满（藏器）。健脾，开胃气，温肠，杀鱼、肉毒，补水脏，治肾气，壮筋骨（《日华》）。主膈气，消食，滋食味（李）。","fufang":[{"text":"莳萝作末，酒服二钱匕。","src":"永类钤方"},{"text":"牙齿疼痛：舶上莳萝、芸苔子、白芥子等分。研末。口中含水，随左右鼻，神效。","src":"圣惠方"},{"text":"藏器曰：子：味辛，平，无毒。主冷气心腹胀满，补肾，除妇人血气，下痢，杀牙齿虫。生安南，似香子，可和食。数低。","src":"拾遗"},{"text":"藏器曰：子：味甘，温，无毒。主冷风冷气，下宿食不消胀满。生西番、北土，兼似香，胡人以作羹食之。池德勒。","src":"拾遗"}],"vol":"菜部"},"罗勒":{"qi":"辛，温，微毒。禹锡曰：不可多食，壅关节，涩营卫，令人血脉不行，又动风，发脚气。","zhi":"调中消食，去恶气，消水气，宜生食。疗齿根烂疮，为灰用之甚良。患呕者，取汁服半合，冬月用干者煮汁。其根烧灰，敷小儿黄烂疮（禹锡）。主辟飞尸、鬼疰、蛊毒（吴瑞）。","fufang":[{"text":"二钱，铜青五分，轻粉二字，为末，日敷三次。","src":"钱乙《小儿方"},{"text":"反胃咳噫：生姜四两。","src":"捣烂"},{"text":"入兰香叶一两，椒末一钱，盐和面四两，裹作烧饼，煨熟，空心吃，不过两三度效。反胃，入甘蔗汁和之。","src":"普济方"},{"text":"走马牙疳：小儿食肥甘，肾受虚热，口作臭息，次第齿黑，名曰崩砂；渐至龈烂，名曰溃槽；又或血出，名曰宣露；重则齿落，名曰腐根。用兰香子末、轻粉各一钱，密陀僧。","src":"醋淬，研末"},{"text":"半两，和匀。每以少许敷齿及龈上，立效。内服甘露饮。","src":"活幼口议"}],"vol":"菜部"},"白花菜":{"qi":"苦，辛，微毒。颖曰：多食，动风气，滞脏腑，令人胃中闷满，伤脾。","zhi":"下气（汪颖）。煎水洗痔，捣烂敷风湿痺痛，擂酒饮止疟（时珍）。","fufang":[],"vol":"菜部"},"菜":{"qi":"辛，温，无毒。李鹏飞曰：菜细切，以生蜜洗伴或略食之，爽口消食。多食，发痼疾，生热。","zhi":"去冷气，腹内久寒，饮食不消，令人能食（藏器）。利胸膈，豁冷痰，心腹痛（时珍）。","fufang":[],"vol":"菜部"},"草豉":{"qi":"辛，平，无毒。","zhi":"恶气，调中，益五脏，开胃，令人能食（藏器）。此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/菜之一&amp;oldid=2636043”分类：PD-old蔬菜此页面最后编辑于2025年12月23日(星期二)16:22。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。（请参阅使用条款）在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权（含署名权）永久有效（详情）。Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501(c)(3)免税、非营利、慈善机构。隐私政策关于维基文库免责声明法律与安全事项联系方式行为准则开发者统计Cookie声明移动版视图搜索搜索开关目录本草纲目/菜之一1种语言添加话题","fufang":[],"vol":"菜部"},"菠薐":{"qi":"甘，冷，滑，无毒。士良曰︰微毒。多食令人脚弱，发腰痛，动冷气。先患腹冷者，必破腹。不与䱉鱼同食，发霍乱。取汁炼霜，制砒、汞，伏雌黄、硫黄。","zhi":"利五脏，通肠胃热，解酒毒。服丹石人食之佳（孟诜）。通血脉，开胸膈，下气调中，止渴润燥。根尤良（时珍）。","fufang":[{"text":"消渴引饮，日至一石者︰菠薐根、鸡内金等分，为末。米饮服一钱，日三。","src":"经验方"}],"vol":"菜部"},"蕹菜":{"qi":"甘，平，无毒。","zhi":"解胡蔓草毒（即野葛毒），煮食之。亦生捣服（藏器）。捣汁和酒服，治产难（时珍。出唐瑶方）。","fufang":[],"vol":"菜部"},"菾菜":{"qi":"甘、苦，大寒，滑，无毒。禹锡曰︰平，微毒。冷气人不可多食，动气。先患腹冷人食之，必破腹。","zhi":"时行壮热，解风热毒，捣汁饮之便瘥（《别录》）。夏月以菜作粥食，解热，止热毒痢。捣烂，敷灸疮，止痛易瘥（苏恭）。捣汁服，主冷热痢。又止血生肌，及诸禽兽伤，敷之立愈（藏器）。煎汤饮，开胃，通心膈，宜妇人（大明）。补中下气，理脾气，去头风，利五脏（《嘉》）。根【气味】甘，平，无毒。【主治】通经脉，下气，开胸膈（《正要》）。子【主治】煮半生，捣汁服，治小儿热（孟诜）。醋浸揩面，去粉滓，润泽有光（藏器）。","fufang":[],"vol":"菜部"},"东风菜":{"qi":"甘，寒，无毒。","zhi":"风毒壅热，头痛目眩，肝热眼赤，堪入羹食（《开宝》）。","fufang":[],"vol":"菜部"},"荠":{"qi":"甘，温，无毒。","zhi":"利肝和中（《别录》）。利五脏。根︰治目痛（大明）。明目益胃（时珍）。根、叶︰烧灰，治赤白痢极效（甄权）。","fufang":[{"text":"旧一，新二。暴赤眼，痛胀碜涩︰荠菜根杵汁滴之。","src":"圣惠"},{"text":"眼生翳膜︰荠菜和根、茎、叶洗净，焙干为细末。每夜卧时先洗眼，挑末米许，安两大头。涩痛忍之，久久膜自落也。","src":"圣济总录"},{"text":"肿满腹大，四肢枯瘦，尿涩︰用甜葶苈。","src":""},{"text":"、荠菜根等分，为末，炼蜜丸弹子大。每服一丸，陈皮汤下。只二、三丸，小便清；十余丸，腹如故。","src":"三因"},{"text":"青盲不见物，补五脏不足。","src":"甄权"},{"text":"去风毒邪气，治壅去翳，解热毒。久服，视物鲜明。","src":"士良"},{"text":"阴干研末，枣汤日服二钱，治久痢。","src":"大明"}],"vol":"菜部"},"菥蓂":{"qi":"甘，平，无毒。","zhi":"和中益气，利肝明目（时珍）。菥子【气味】辛，微温，无毒。恭曰︰甘而不辛。普曰︰神农、雷公︰辛；李当之︰小温。之才曰︰得蔓荆实、细辛良。恶干姜、苦参。一云︰苦参为之使。【主治】明目目痛泪出，除痺，补五脏，益精光。久服轻身不老（《本经》）。疗心腹腰痛（《别录》）。治肝家积聚，眼目赤肿（甄权）。","fufang":[{"text":"旧一，新一。眼目热痛，泪出不止︰菥子，捣筛为末。卧时铜簪点少许入目，当有热泪及恶物出，甚佳。眼中肉︰方同上，夜夜点之。","src":"崔元亮《海上方"}],"vol":"菜部"},"蘩缕":{"qi":"酸，平，无毒。权曰︰苦。时珍曰︰甘，微咸。诜曰︰温。思邈曰︰黄帝云︰合鳝食，发消渴，令人多忘。","zhi":"积年恶疮、痔不愈（《别录》）。破血，下乳汁，产妇宜食之。产后腹有块痛，以酒炒绞汁温服。又曝干为末，醋糊和丸，空腹服五十丸，取下恶血（藏器）。","fufang":[{"text":"繁缕为齑，久久食之，能乌髭发。","src":"圣惠方"},{"text":"小便卒淋︰繁缕草满两手，水煮，常常饮之。","src":"范汪东阳方"},{"text":"产妇有块作痛︰繁缕方见上。丈夫阴疮，茎及头溃烂，痛不可忍，久不瘥者。以五月五日繁缕烧焦五分，入新出蚯蚓屎二分，入少水，和研作饼，贴之。干即易。禁酒、面、五辛及热食等物。甚效。","src":"扁鹊方"}],"vol":"菜部"},"鸡肠":{"qi":"微辛、苦，平，无毒。权曰︰苦。之才曰︰微寒。","zhi":"毒肿，止小便利（《别录》）。疗蠷溺疮（弘景）。主遗溺，洗手足伤水烂（甄权）。五月五日作灰和盐，疗一切疮及风丹遍身痒痛；亦可捣封，日五六易之。作菜食，益人，去脂膏毒气。又烧敷疳。取汁和蜜服，疗小儿赤白痢，甚良（孟诜）。研末或烧灰，揩齿，去宣露（苏颂）。","fufang":[{"text":"鸡肠草一斤，于豆豉汁中煮，和米作羹及粥，频食之。","src":"食医心镜"},{"text":"小儿下痢赤白︰鸡肠草捣汁一合，和蜜服，甚良。","src":"孟诜《食疗"},{"text":"气淋胀痛︰鸡肠草三两，石苇。","src":"去毛"},{"text":"一两。每用三钱，水一盏，煎服。","src":"圣济总录"},{"text":"风热牙痛，浮肿发歇，元脏气虚，小儿疳蚀︰鸡肠草、旱莲草、细辛等分，为末。每日擦三次。名祛痛散。","src":"普济方"},{"text":"发背欲死︰鸡肠草捣敷之。","src":"肘后方"},{"text":"反花恶疮︰鸡肠草研汁拂之。或为末，猪脂调搽，极效。","src":"医林正宗"},{"text":"一切头疮︰鸡肠草烧灰，和盐敷之。","src":"孟诜《食疗"}],"vol":"菜部"},"苜蓿":{"qi":"苦，平，涩，无毒。宗奭曰︰微甘、淡。诜曰︰凉。少食好。多食令冷气入筋中，即瘦人。李鹏飞曰︰同蜜食，令人下利。","zhi":"安中利人，可久食（《别录》）。利五脏，轻身健人，洗去脾胃间邪热气，通小肠诸恶热毒，煮和酱食，亦可作羹（孟诜）。利大小肠（宗）。干食益人（苏颂）。根【气味】寒，无毒。【主治】热病烦满，目黄赤，小便黄，酒疸，捣取汁服一升，令人吐利即愈（苏恭）。捣汁煎饮，治沙石淋痛（时珍）。","fufang":[],"vol":"菜部"},"苋":{"qi":"甘，冷利，无毒。恭曰︰赤苋︰辛，寒。鼎曰︰苋动气，令人烦闷，冷中损腹。不可与鳖同食，生鳖症。又取鳖肉如豆大，以苋菜封裹置土坑内，以土盖之，一宿尽变成小鳖也。机曰︰此说屡试不验。","zhi":"白苋︰补气除热，通九窍（孟诜）。赤苋︰主赤痢，射工、沙虱（苏恭）。紫苋︰杀虫毒，治气痢（藏器）。六苋︰并利大小肠，治初痢，滑胎（时珍）。","fufang":[{"text":"旧二，新五。产后下痢，赤白者︰用紫苋菜一握切煮汁，入粳米三合，煮粥，食之立瘥也。","src":"寿亲养老书"},{"text":"小儿紧唇︰赤苋，捣汁洗之，良。","src":"圣惠"},{"text":"漆疮搔痒︰苋菜，煎汤洗之。蜈蚣螫伤︰取灰苋叶擦之，即止。","src":"谈野翁方"},{"text":"蜂虿螫伤︰野苋擦之。诸蛇螫人︰紫苋，捣汁饮一升，以滓涂之。","src":"集验方"},{"text":"射工中人，状如伤寒，寒热，发疮偏在一处，有异于常者。取赤苋合茎、叶捣汁饮一升，日再服之。","src":"集验方"},{"text":"肝风客热，翳目黑花。","src":"时珍"}],"vol":"菜部"},"马齿苋":{"qi":"酸，寒，无毒。恭曰︰辛，温。宗奭曰︰人多食之，然性寒滑。","zhi":"诸肿疣目，捣揩之。破癖，止消渴（藏器）。能肥肠，令人不思食。治女人赤白下（苏颂）。饮汁，治反胃诸淋，金疮流血，破血癖症瘕，小儿尤良。用汁治紧唇面，解马汗、射工毒，涂之瘥（苏恭）。治自尸脚阴肿（保升）。作膏，涂湿癣、白秃、杖疮。又主三十六种风。煮粥，止痢及疳痢，治腹痛（孟诜）。服之长年不白。治痈疮，杀诸虫。生捣汁服，当利下恶物，去白虫。和梳垢，封疔肿。又烧灰和陈醋滓，先灸后封之，即根出（《开宝》）。散血消肿，利肠滑胎，解毒通淋，治产后虚汗（时珍）。","fufang":[{"text":"旧十六，新二十三。三十六风结疮︰马齿苋一石。水二石，煮取汁，入蜜蜡三两，重煎成膏。涂之。","src":"食疗"},{"text":"诸气不调︰马齿苋煮粥，食之。","src":"食医心镜"},{"text":"禳解疫气︰六月六日，采马齿苋晒干。元旦煮熟，同盐、醋食之，可解疫疠气。","src":"唐瑶《经验方"},{"text":"筋骨疼痛，不拘风湿气、杨梅疮及女人月家病，先用此药止疼，然后调理︰干马齿苋一斤。","src":"湿马齿苋二斤"},{"text":"五加皮半斤，苍术四两，舂碎，以水煎汤洗澡。急用葱、姜擂烂，冲热汤三碗，服之。暖处取汗，立时痛止也。","src":"海上名方"},{"text":"脚气浮肿︰心腹胀满，小便涩少。马齿草和少粳米，酱汁煮食之。","src":"食医心镜"},{"text":"男女疟疾︰马齿苋捣，扎手寸口，男左女右。产后虚汗︰马齿苋。","src":"研汁"},{"text":"三合，服。如无，以干者煮汁。","src":"妇人良方"}],"vol":"菜部"},"苦菜":{"qi":"苦，寒，无毒。张机曰︰野苣不可共蜜食，令人作内痔。时珍曰︰脾胃虚寒人，不可食。","zhi":"五脏邪气，厌（延叶反，伏也）谷胃痺。久服安心益气，聪察少卧，轻身耐老（《本经》）。肠渴热，中疾恶疮。久服耐饥寒，高气不老（《别录》）。调十二经脉，霍乱后胃气烦逆。久服强力，虽冷甚益人（《嘉》）。捣汁饮，除面目及舌下黄。其白汁，涂疔肿，拔根。滴痈上，立溃（藏器）。点瘊子，自落（《衍义》）。敷蛇咬（大明）。明目，主诸痢（汪机）。血淋痔（时珍）。","fufang":[{"text":"苦菜一把，酒、水各半，煎服。","src":"资生经"},{"text":"血脉不调︰苦菜晒干，为末。每服二钱，温酒下。","src":"卫生易简方"},{"text":"喉痺肿痛︰野苦捣汁半盏，灯心以汤浸，捻汁半盏，和匀服。","src":"普济方"},{"text":"对口恶疮︰野苦擂汁一钟，入姜汁一匙，和酒服，以渣敷，一、二次即愈。","src":"唐瑶《经验方"},{"text":"中沙虱毒，沙虱在水中，人澡浴则著人身，钻入皮里。初得皮上正赤，如小豆、黍、粟，摩之痛如刺，三日后寒热发疮毒，若入骨杀人，岭南多此︰即以茅叶刮去，以苦菜汁涂之，佳。","src":"肘后方"},{"text":"壶蜂叮螫︰苦汁涂之，良。","src":"摘玄方"},{"text":"黄胆疾，连花、子研细二钱，水煎服，日二次，良。","src":"汪颖"}],"vol":"菜部"},"白苣":{"qi":"苦，寒，无毒。炳曰︰平。患冷气人食之即腹冷，亦不至苦损人。产后不可食，令人寒中，小肠痛。思邈曰︰不可共酪食，生虫。","zhi":"补筋骨，利五脏，开胸膈壅气，通经脉，止脾气，令人齿白，聪明少睡，可煮食之（孟诜）。解热毒、酒毒，止消渴，利大小肠（宁原）。","fufang":[{"text":"旧一。鱼脐疮，其头白似肿，痛不可忍︰先以针刺破头及四畔，以白苣取汁滴孔中，良。","src":"外台秘要"}],"vol":"菜部"},"莴苣":{"qi":"苦，冷，微毒。李鹏飞曰︰久食昏人目。患冷人不宜食。时珍曰︰按︰彭乘云︰莴苣有毒，百虫不敢近。蛇虺触之，则目暝不见物。人中其毒，以姜汁解之。藏器曰︰紫莴苣有毒，入烧炼药用。《丹房镜源》曰︰莴苣用硫黄种，结砂子，制朱砂。又曰︰紫色莴苣和土作器，火如铜也。","zhi":"利五脏，通经脉，开胸膈，功同白苣（藏器）。利气，坚筋骨，去口气，白齿牙，明眼目（宁原）。通乳汁，利小便，杀虫、蛇毒（时珍）。","fufang":[{"text":"小便不通︰莴苣菜，捣敷脐上即通。","src":"卫生易简方"},{"text":"小便尿血︰同上方，甚效。","src":"杨氏方"},{"text":"沙虱水毒︰莴苣菜捣汁涂之，良。","src":"肘后方"},{"text":"蚰蜒入耳︰莴苣叶。","src":"干者"},{"text":"一分，雄黄一分，为末，糊丸枣核大。蘸生油塞耳中，引出。","src":"圣惠方"},{"text":"百虫入耳︰莴苣捣汁滴入，自出也。","src":"圣济总录"},{"text":"肾黄如金︰莴苣子一合。细研。水一盏，煎五分服。","src":"外台秘要"},{"text":"阴囊肿︰莴苣子一合捣末，水一盏，煎五沸，温服。闪损腰痛，趁痛丸︰用白莴苣子。","src":""}],"vol":"菜部"},"水苦荬":{"qi":"微苦、辛，寒，无毒。","zhi":"风热上壅，咽喉肿痛，及项上风，以酒磨服（苏颂）。","fufang":[],"vol":"菜部"},"翻白草":{"qi":"甘、微苦，平，无毒。","zhi":"吐血下血崩中，疟疾痈疮（时珍）。","fufang":[{"text":"用湖鸡腿根一两捣碎，酒二盏，煎一盏服。","src":"濒湖集简方"},{"text":"吐血不止︰翻白草，每用五七科咀，水二钟，煎一钟，空心服。疟疾寒热︰翻白草根五七个，煎酒服之。无名肿毒︰方同上。丁毒初起，不拘已成、未成︰用翻白草十科，酒煎服，出汗即愈。浑身疥癞︰端午日午时采翻白草，每用一握，煎水洗之。疮溃烂︰端午日午时采翻白草，洗收。每用一握，煎汤盆盛，围住熏洗，效。","src":"刘松石《保寿堂方"}],"vol":"菜部"},"仙人杖草":{"qi":"甘，小温，无毒。","zhi":"作茹食，去痰癖，除风冷（大明）。久服长生，坚筋骨，令人不老（藏器）。","fufang":[],"vol":"菜部"},"蒲公英":{"qi":"甘，平，无毒。","zhi":"妇人乳痈肿，水煮汁饮及封之，立消（恭）。解食毒，散滞气，化热毒，消恶肿、结核、疔肿（震亨）。掺牙，乌须发，壮筋骨（时珍）。白汁︰涂恶刺、狐尿刺疮，即愈（颂）。","fufang":[{"text":"新五。还少丹，昔日越王曾遇异人得此方，极能固齿牙，壮筋骨，生肾水。凡年未及八十者，服之须发返黑，齿落更生。年少服之，至老不衰。得遇此者，宿有仙缘，当珍重之，不可轻泄︰用蒲公英一斤（一名耩耨草，又名蒲公罂，生平泽中，三、四月甚有之，秋后亦有放花者，连根带叶取一斤洗净，勿令见天日），晾干，入斗子。解盐一两，香附子五钱，二味为细末，入蒲公草内淹一宿，分为二十团，用皮纸三、四层裹扎定，用六一泥。","src":"即蚯蚓粪"},{"text":"如法固济，入灶内焙干，乃以武火通红为度，冷定取出，去泥为末。早晚擦牙漱之，吐、咽任便，久久方效。","src":"瑞竹堂方"},{"text":"乳痈红肿︰蒲公英一两，忍冬藤二两。捣烂，水二钟，煎一钟，食前服。睡觉病即去矣。","src":"积德堂方"},{"text":"疳疮疔毒︰蒲公英捣烂覆之，即黄花地丁也。别更捣汁，和酒煎服，取汗。","src":"唐氏方"},{"text":"多年恶疮︰蒲公英捣烂贴。","src":"救急方"}],"vol":"菜部"},"黄瓜菜":{"qi":"甘、微苦，微寒，无毒。","zhi":"通结气，利肠胃（汪颖）。","fufang":[],"vol":"菜部"},"生瓜菜":{"qi":"甘，微寒，无毒。","zhi":"走注攻头面四肢，及阳毒伤寒，壮热头痛，心神烦躁，利胸膈，捣汁饮之。又生捣贴肿（苏颂）。","fufang":[],"vol":"菜部"},"落葵":{"qi":"酸，寒，滑，无毒。时珍曰︰甘、微酸，冷滑。脾冷人不可食。弘景曰︰曾为狗啮者，食之终身不瘥。","zhi":"滑中，散热（《别录》）。利大小肠（时珍）。子【主治】悦泽人面（《别录》）。可作面脂（苏颂）。诜曰︰取子蒸过，烈日中曝干，去皮，取仁细研，和白蜜涂面，鲜华立见）。","fufang":[],"vol":"菜部"},"蕺菜":{"qi":"辛，微温，有小毒。《别录》曰︰多食，令人气喘。弘景曰︰俗传食蕺不利人脚，恐由闭气故也。今小儿食之，便觉脚痛。诜曰︰小儿食之，三岁不行。久食，发虚弱，损阳气，消精髓。思邈曰︰素有脚气人食之，一世不愈。","zhi":"蠷尿疮（《别录》）。淡竹筒内煨熟，捣敷恶疮、白秃（大明）。散热毒痈肿，疮痔脱肛，断疾，解毒（时珍）。","fufang":[{"text":"蕺菜捣汁涂之，留孔以泄热毒，冷即易之。","src":"经验方"},{"text":"痔疮肿痛︰鱼腥草一握，煎汤熏洗，仍以草挹痔即愈。一方︰洗后以枯矾入片脑少许，敷之。","src":"救急方"},{"text":"疔疮作痛︰鱼腥草捣烂敷之。痛一、二时，不可去草，痛后一、二日即愈。徽人所传方也。","src":"陆氏《积德堂方"},{"text":"小儿脱肛︰鱼腥草擂如泥，先以朴硝水洗过，用芭蕉叶托住药坐之，自入也。","src":"永类方"},{"text":"虫牙作痛︰鱼腥草、花椒、菜子油等分，捣匀，入泥少许，和作小丸如豆大。随牙左右塞耳内，两边轮换，不可一齐用，恐闭耳气。塞一日夜，取看有细虫为效。","src":"简便方"},{"text":"断截疟疾︰紫蕺一握。捣烂绢包，周身摩擦，得睡有汗即愈。临发前一时作之。","src":"救急易方"},{"text":"恶蛇虫伤︰鱼腥草、皱面草、槐树叶、草决明，一处杵烂，敷之甚效。","src":"同上"}],"vol":"菜部"},"蕨":{"qi":"甘，寒，滑，无毒。诜曰︰久食，令人目暗、鼻塞、发落。又冷气人食之，多腹胀。小儿食之，脚弱不能行。思邈曰︰久食成瘕。","zhi":"去暴热，利水道，令人睡（藏器）。补五脏不足，气壅经络筋骨间，毒气（孟诜）。根烧灰油调，敷蛇、KT伤（时珍。KT音萧，虫名）。","fufang":[{"text":"蕨菜花焙，为末。每服二钱，米饮下。","src":"圣惠"}],"vol":"菜部"},"水蕨":{"qi":"甘、苦，寒，无毒。","zhi":"腹中痞积，淡煮食，一、二日即下恶物。忌杂食一月余乃佳（时珍。《卫生方》）。","fufang":[],"vol":"菜部"},"薇":{"qi":"甘，寒，无毒。","zhi":"久食不饥，调中，利大小肠（藏器）。利水道，下浮肿，润大肠（）。","fufang":[],"vol":"菜部"},"翘摇":{"qi":"辛，平，无毒。诜曰︰煮食佳，生食令人吐水。","zhi":"破血，止血生肌。捣汁服之，疗五种黄病，以瘥为度（藏器）。利五脏，明耳目，去热风，令人轻健，长食不厌，甚益人（孟诜）。止热疟，活血平胃（时珍）。","fufang":[{"text":"漂摇豆为末，甘草汤服二钱，日二钱。","src":"卫生易简方"},{"text":"热疟不止︰翘摇杵汁服之。","src":"广利方"}],"vol":"菜部"},"鹿藿":{"qi":"苦，平，无毒。","zhi":"蛊毒，女子腰腹痛不乐，肠痈瘰&#30311;，疡气（《本经》）。止头痛（梁简文《劝医文》）。","fufang":[],"vol":"菜部"},"灰藋":{"qi":"甘，平，无毒。","zhi":"恶疮，虫、蚕、蜘蛛等咬，捣烂和油敷之。亦可煮食。作汤，浴疥癣风瘙。烧灰纳齿孔中，杀虫。含漱，去甘疮。以灰淋汁，蚀息肉，除白癜风、黑子、面，著肉作疮（藏器）。","fufang":[{"text":"野灰菜叶烧灰，拨破疮皮，唾调少许点之，血出为度。","src":"普济"}],"vol":"菜部"},"藜":{"qi":"甘，平，微毒。时珍曰︰按︰《庚辛玉册》云︰鹤顶，阴草也。捣汁煮粉霜，烧灰淋汁煎粉霜，伏矾石，结草砂，制硫，伏汞及雌黄、砒石。","zhi":"杀虫（藏器）。煎汤，洗虫疮，漱齿。捣烂，涂诸虫伤，去癜风（时珍）。","fufang":[{"text":"红灰五斤，茄子根、茎三斤，苍耳根、茎五斤，并晒干烧灰，以水一斗煎汤淋汁熬成膏，别以好乳香半两，铅霜一分，腻粉一分，炼成牛脂二两，和匀，每日涂三次。","src":"圣惠"}],"vol":"菜部"},"秦荻藜":{"qi":"辛，温，无毒。","zhi":"心腹冷胀，下气消食，和酱、醋食之（《唐本》）。破气甚良。又末之和酒服，疗卒心痛，悒悒，塞满气（孟诜）。子【主治】肿毒，捣末和醋封之，日三易（孟诜）。","fufang":[],"vol":"菜部"},"醍醐菜":{"qi":"甘，温，无毒。","zhi":"月水不利，捣叶绞汁，和酒煎服一盏（《千金》）。","fufang":[{"text":"醍醐杵汁，拌酒煎沸，空心服一盏。","src":"千金方"}],"vol":"菜部"},"芋":{"qi":"辛，平，滑，有小毒。大明曰︰冷。弘景曰︰生则有毒，味不可食。性滑下石，服饵家所忌。恭曰︰多食动宿冷。宗奭曰︰多食难克化，滞气困脾。","zhi":"宽肠胃，充肌肤，滑中（《别录》）。冷啖，疗烦热，止渴（苏恭）。令人肥白，开胃通肠闭。产妇食之，破血；饮汁，止血渴（藏器）。破宿血，去死肌。和鱼煮食，甚下气，调中补虚（大明）。","fufang":[{"text":"生芋子一斤压破，酒五斤渍二七日。空腹每饮一升，神良。","src":"韦宙《独行方"},{"text":"身上浮风︰芋煮汁浴之。慎风半日。","src":"孟诜《食疗"},{"text":"疮冒风邪肿痛︰用白芋烧灰敷之。干即易。","src":"千金方"},{"text":"头上软疖︰用大芋捣敷之，即干。","src":"简便方"},{"text":"【附录】野芋弘景曰︰野芋形叶与芋相似，芋种三年不采成芋。","src":"音吕"}],"vol":"菜部"},"土芋":{"qi":"甘、辛，寒，有小毒。","zhi":"解诸药毒，生研水服，当吐出恶物便止。煮熟食之，甘美不饥，浓人肠胃，去热嗽（藏器）。","fufang":[],"vol":"菜部"},"薯蓣":{"qi":"甘，温、平，无毒。普曰︰神农︰甘，小温；桐君、雷公︰甘，凉，无毒。之才曰︰紫芝为之使。恶甘遂。","zhi":"伤中，补虚羸，除寒热、邪气，补中，益气力，长肌肉，强阴。久服耳目聪明，轻身不饥延年（《本经》）。主头面游风，头风，眼眩，下气，止腰痛，治虚劳、羸瘦，充五脏，除烦热（《别录》）。补五劳七伤，去冷风，镇心神，安魂魄，补心气不足，开达心孔，多记事（甄权）。强筋骨，主泄精、健忘（大明）。益肾气，健脾胃，止泄痢，化痰涎，润皮毛（时珍）。生捣贴肿硬毒，能消散（震亨）。","fufang":[{"text":"旧一，新十。补益虚损，益颜色，补下焦虚冷，小便频数，瘦损无力︰用薯蓣于沙盆中研细，入铫中，以酥一大匙熬令香，旋添酒一盏煎搅令匀，空心饮之。每旦一服。","src":"圣惠方"},{"text":"心腹虚胀，手足厥逆，或饮苦寒之剂多，未食先呕，不思饮食︰山药半生半炒，为末。米饮服二钱，一日二服，大有功效。忌铁器、生冷。","src":"普济方"},{"text":"、白茯苓等分，为末。每水饮服二钱。","src":"儒门事亲"},{"text":"下痢禁口︰山药半生半炒，为末。每服二钱，米饮下。","src":"卫生易简方"},{"text":"痰风喘急︰生山药捣烂半碗，入甘蔗汁半碗，和匀。顿热饮之，立止。","src":"简便单方"},{"text":"脾胃虚弱，不思饮食︰山芋、白术各一两，人参七钱半，为末，水糊丸小豆大，每米饮下四、五十丸。","src":"普济方"},{"text":"湿热虚泄︰山药、苍术等分。饭丸。米饮服。大人、小儿皆宜。","src":"濒湖经验方"},{"text":"肿毒初起︰带泥山药、蓖麻子、糯米等分，水浸研，敷之即散也。","src":"普济方"}],"vol":"菜部"},"零余子":{"qi":"甘，温，无毒。","zhi":"补虚损，强腰脚，益肾，食之不饥（藏器）。","fufang":[],"vol":"菜部"},"甘𫉄":{"qi":"甘，平，无毒。","zhi":"补虚乏，益气力，健脾胃，强肾阴，功同薯蓣（时珍）。","fufang":[],"vol":"菜部"},"百合":{"qi":"甘，平，无毒。权曰︰有小毒。","zhi":"邪气腹胀心痛，利大小便，补中益气（《本经》）。除浮肿胪胀，痞满寒热，通身疼痛，及乳难喉痺，止涕泪（《别录》）。百邪鬼魅，涕泣不止，除心下急满痛，治脚气热咳（甄权）。安心定胆益志，养五脏，治颠邪狂叫惊悸，产后血狂运，杀蛊毒气，胁痈乳痈发背诸疮肿（大明）。心急黄，宜蜜蒸食之（孟诜）。治百合病（宗）。温肺止嗽（元素）。","fufang":[{"text":"百合知母汤︰治伤寒后百合病，行住坐卧不定，如有鬼神状，已发汗者。用百合七枚，以泉水浸一宿，明旦更以泉水二升，煮取一升，却以知母三两，用泉水二升煮一升，同百合汁再煮取一升半，分服。百合鸡子汤︰治百合病已经吐后者。用百合七枚，泉水浸一宿，明旦更以泉水二升，煮取一升，入鸡子黄一个，分再服。百合代赭汤︰治百合病已经下后者。用百合七枚，泉水浸一宿，明旦更以泉水二升，煮取一升，却以代赭石一两，滑石三两，水二升，煮取一升，同百合汁再煮取一升半，分再服。百合地黄汤︰治百合病未经汗吐下者。用百合七枚，泉水浸一宿，明旦更以泉水二升，煮取一升，入生地黄汁一升，同煎取一升半，分再服。","src":"并仲景《金匮要略方"},{"text":"百合变渴︰病已经月，变成消渴者。百合一升，水一斗，渍一宿，取汁温浴病患。浴毕食白汤饼。","src":"陈延之《短剧方"},{"text":"百合变热者︰用百合一两，滑石三两。为末。饮服方寸匕。微利乃良。","src":"短剧方"},{"text":"百合腹满，作痛者︰用百合炒为末，每饮服方寸匕，日二。","src":"短剧"},{"text":"阴毒伤寒︰百合煮浓汁，服一升良。","src":"孙真人食忌"},{"text":"肺脏壅热，烦闷咳嗽者︰新百合四两，蜜和蒸软，时时含一片，吞津。","src":"圣惠方"},{"text":"肺病吐血︰新百合捣汁，和水饮之。亦可煮食。","src":"卫生易简"},{"text":"耳聋耳痛︰干百合为末，温水服二钱，日二服。","src":"胜金方"}],"vol":"菜部"},"山丹":{"qi":"甘，凉，无毒。《正要》云︰平。","zhi":"疮肿、惊邪（大明）。女人崩中（时珍）。花【气味】同根。【主治】活血。其蕊，敷疔疮恶肿（时珍）。","fufang":[],"vol":"菜部"},"草石蚕":{"qi":"甘，平，无毒。时珍曰︰不宜生食及多食，生寸白虫。与诸鱼同食，令人吐。","zhi":"浸酒，除风破血。煮食，治溪毒（藏器）。焙干，主走注风，散血止痛。其节，亦可捣末酒服（苏颂）。和五脏，下气清神（《正要》）。","fufang":[],"vol":"菜部"},"竹笋":{"qi":"甘，微寒，无毒。藏器曰︰诸笋皆发冷血及气。瑞曰︰笋同羊肝食，令人目盲。","zhi":"消渴，利水道，益气，可久食（《别录》）。利膈下气，化热消痰爽胃（宁原）。苦竹笋【气味】苦、甘，寒。【主治】不睡，去面目并舌上热黄，消渴，明目，解酒毒，除热气，健人（藏器）。理心烦闷，益气力，利水道，下气化痰，理风热脚气，并蒸煮食之（《心镜》）。治出汗中风失音（汪颖）。干者烧研入盐，擦牙疳（时珍）。","fufang":[],"vol":"菜部"},"酸笋":{"qi":"酸，凉，无毒。","zhi":"作汤食，止渴解酲，利膈（时珍）。此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse↑菜之菠棱者，本西国中，有僧自彼将其子来，如苜蓿、蒲陶，因张骞而至也。绚曰：「岂非颇棱国将来，而语讹为菠棱耶。」取自“https://zh.wikisource.org/w/index.php?title=本草纲目/菜之二&amp;oldid=2614413”分类：PD-old蔬菜此页面最后编辑于2025年11月9日(星期日)16:31。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。（请参阅使用条款）在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权（含署名权）永久有效（详情）。Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501(c)(3)免税、非营利、慈善机构。隐私政策关于维基文库免责声明法律与安全事项联系方式行为准则开发者统计Cookie声明移动版视图搜索搜索开关目录本草纲目/菜之二1种语言添加话题","fufang":[],"vol":"菜部"},"茄":{"qi":"甘，寒，无毒。志曰︰凡久冷人不可多食，损人动气，发疮及痼疾。李鹏飞曰︰秋后食，多损目。时珍曰︰按︰《生生编》云︰茄性寒利，多食必腹痛下利，女人能伤子宫也。","zhi":"寒热，五脏劳（孟诜）。治温疾传尸劳气。醋摩，敷肿毒（大明）。老裂者烧灰，治乳裂（震亨）。散血止痛，消肿宽肠（时珍）。","fufang":[{"text":"黄茄子竹刀切，阴干为末。每服二钱，温酒调下。","src":"摘玄方"},{"text":"肠风下血︰经霜茄连蒂，烧存性，为末。每日空心温酒服二钱匕。","src":"灵苑方"},{"text":"久患下血︰大茄种三枚，每用一枚，湿纸包煨熟，安瓶内，以无灰酒一升半沃之，蜡纸封闭三日，去茄暖饮。","src":"普济方"},{"text":"腹内鳖症︰陈酱茄儿烧存性，入麝香、轻粉少许，脂调贴之。","src":"寿域方"},{"text":"卵偏坠︰用双蒂茄子悬于房门上，出入用眼视之。茄蔫所患亦蔫，茄干亦干矣。又法︰用双茄悬门上，每日抱儿视之，二、三次钉针于上，十余日消矣。","src":"刘松石《保寿堂方"},{"text":"大风热痰︰用黄老茄子大者不计多少，以新瓶盛，埋土中，经一年尽化为水，取出入苦参末，同丸梧子大。食已及卧时酒下三十丸，甚效。此方出江南人传。","src":"苏颂《图经本草"},{"text":"腰脚拘挛，腰脚风血积冷，筋急拘挛疼痛者︰取茄子五十斤切洗，以水五斗煮取浓汁，滤去滓，更入小铛中，煎至一斗以来，即入生粟粉同煎，令稀稠得所，取出搜和，更入麝香、朱砂末，同丸如梧子大。每旦用秫米酒送下三十丸，近暮再服，一月乃瘥。男子、女人通用皆验。","src":"图经本草"},{"text":"磕扑青肿︰老黄茄极大者，切片如一指浓，新瓦焙研为末。欲卧时温酒调服二钱匕，一夜消尽，无痕迹也。","src":"胜金"}],"vol":"菜部"},"苦茄":{"qi":"","zhi":"醋摩，涂痈肿。根，亦可作汤浴。又主瘴气（藏器）。","fufang":[],"vol":"菜部"},"壶卢":{"qi":"甘，平，滑，无毒。恭曰︰甘冷。多食令人吐利。扁鹊曰︰患脚气虚胀冷气者食之，永不除也。","zhi":"消渴恶疮，鼻口中肉烂痛（思邈）。利水道（弘景）。消热，服丹石人宜之（孟诜）。除烦，治心热，利小肠，润心肺，治石淋（大明）。","fufang":[{"text":"用亚腰壶卢连子烧存性，每服一个，食前温酒下。不饮酒者，白汤下。十余日见效。","src":"简便方"}],"vol":"菜部"},"苦瓠":{"qi":"苦，寒，有毒。","zhi":"大水，面目四肢浮肿，下水，令人吐（《本经》）利石淋，吐呀嗽囊结，疰蛊痰饮。又煮汁渍阴，疗小便不通（苏恭）。煎汁滴鼻中，出黄水，去伤冷鼻塞，黄胆（藏器）。吐蛔虫（大明）。治痈疽恶疮，疥癣龋齿有虫者。又可制汞（时珍）。","fufang":[{"text":"苦瓠一枚，开孔，以水煮之，搅取汁，滴入鼻中。去黄水。","src":"陈藏器"},{"text":"黄胆肿满︰苦壶卢瓤如大枣许，以童子小便二合，浸之一时，取两酸枣大，纳两鼻中，深吸气，待黄水出良。又方︰用瓠瓤熬黄为末，每服半钱，日一服，十日愈。然有吐者当详之。","src":"伤寒类要"},{"text":"大水胀满，头面洪大︰用莹净好苦瓠白瓤，捻如豆粒，以面裹煮一沸，空心服七枚。至午当出水一斗。二日水自出不止，大瘦乃瘥。二年内忌咸物。","src":"外台"},{"text":"《圣惠》︰用苦壶卢瓤一两，微炒为末，每日粥饮服一钱。通身水肿︰苦瓠膜。","src":""},{"text":"二两，苦葶苈五分，捣合丸小豆大。每服五丸，日三，水下止。又用苦瓠膜五分，大枣七枚。捣丸。一服三丸，如人行十里许，又服三丸，水出更服一丸，即止。","src":"并《千金方"},{"text":"石水腹肿︰四肢皆瘦削。用苦瓠膜。","src":""},{"text":"为末，糊丸小豆大。每饮下十丸，日三，水下止。","src":"圣济总录"},{"text":"水蛊洪肿︰苦瓠瓤一枚，水二升，煮至一升，煎至可丸，如小豆大，每米饮下十丸。待小便利，作小豆羹食。勿饮水。小便不通，胀急者︰用苦瓠子三十枚。","src":""}],"vol":"菜部"},"败瓢":{"qi":"苦，平，无毒。","zhi":"消胀杀虫，治痔漏下血，崩中带下赤白（时珍）。","fufang":[{"text":"用三、五年陈壶卢瓢一个，以糯米一斗作酒，待熟，以瓢于炭火上炙热，入酒浸之，如此三、五次，将瓢烧存性，研末。每服三钱，酒下，神效。","src":"余居士《选奇方"},{"text":"、黄连等分。研末。每空心温酒服二钱。","src":"简便方"},{"text":"赤白崩中︰旧壶卢瓢。","src":"炒存性"},{"text":"等分。研末。每服二钱，热水调服。三服，有汗为度，即止。甚者五服止，最妙。忌房事、发物、生冷。","src":"海上方"},{"text":"脑漏流脓︰破瓢、白鸡冠花、白螺蛳壳。","src":"各烧存性"},{"text":"等分，血竭、麝香各五分，为末。以好酒洒湿熟艾，连药揉成饼，贴在顶门上，以熨斗熨之，以愈为度。","src":"孙氏《集效方"},{"text":"腋下瘤瘿︰用长柄茶壶卢烧存性，研末搽之，以消为度。一府校老妪右腋生一瘤，渐长至尺许，其状如长瓠子，久而溃烂。一方士教以此法用之，遂出水，消尽而愈。","src":"濒湖集简方"},{"text":"汤火伤灼︰旧壶卢瓢，烧灰敷之。","src":"同上"}],"vol":"菜部"},"冬瓜":{"qi":"甘，微寒，无毒。弘景曰︰冷利。","zhi":"小腹水胀，利小便，止渴（《别录》）。捣汁服，止消渴烦闷，解毒（弘景）。益气耐老，除心胸满，去头面热（孟诜）。消热毒痈肿。切片摩痱子，甚良（大明）。利大小肠，压丹石毒（苏颂）。","fufang":[{"text":"白瓜去皮，每食后吃三、二两，五七度良。","src":"孟诜《食疗"},{"text":"消渴不止︰冬瓜一枚削皮，埋湿地中，一月取出，破开取清水日饮之。或烧熟绞汁饮之。","src":"圣济总录"},{"text":"消渴骨蒸︰大冬瓜一枚去瓤，入黄连末填满，安瓮内，待瓜消尽，同研，丸梧子大。每服三、四十丸，煎冬瓜汤下。","src":"经验"},{"text":"产后痢渴︰久病津液枯竭，四肢浮肿，口舌干燥。用冬瓜一枚，黄土泥浓五寸，煨熟绞汁饮。亦治伤寒痢渴。","src":"古今录验"},{"text":"小儿渴利︰冬瓜汁饮之。","src":"千金"},{"text":"小儿病，寒热如疳︰用冬瓜、蓄各四两，水二升，煎汤浴之。","src":"千金方"},{"text":"婴孩寒热︰冬瓜炮熟，绞汁饮。","src":"子母秘录"},{"text":"水病危急︰冬瓜不拘多少，任意吃之，神效无比。","src":"兵部手集"}],"vol":"菜部"},"南瓜":{"qi":"甘，温，无毒。时珍曰︰多食发脚气、黄胆。不可同羊肉食，令人气壅。","zhi":"补中益气（时珍）。","fufang":[],"vol":"菜部"},"越瓜":{"qi":"甘，寒，无毒。诜曰︰生食多冷中动气，令人心痛，脐下症结，发诸疮。又令人虚弱不能行，不益小儿。天行病后不可食。又不得与牛乳酪及同食。时珍曰︰按︰萧子真云︰菜瓜能暗人耳目。观驴马食之即眼烂，可知矣。","zhi":"利肠胃，止烦渴（《开宝》）。利小便，去烦热，解酒毒，宣泄热气。烧灰，敷口吻疮及阴茎热疮（藏器）。和饭作，久食益肠胃（《心镜》）。","fufang":[],"vol":"菜部"},"胡瓜":{"qi":"甘，寒，有小毒。诜曰︰不可多食，动寒热，多疟病，积瘀热，发疰气，令人虚热上逆少气，损阴血，发疮疥脚气，虚肿百病。天行病后，不可食之。小儿切忌，滑中生疳虫。不可多用醋。","zhi":"清热解渴，利水道（宁原）。","fufang":[{"text":"嫩黄瓜同蜜食十余枚，良。","src":"海上名方"},{"text":"水病肚胀，四肢浮肿︰用胡瓜一个破开，连子以醋煮一半，水煮一半至烂，空心俱食之，须臾下水也。","src":"千金髓"},{"text":"小儿出汗︰香瓜丸︰用黄连、胡黄连、黄柏、川大黄。","src":"煨熟"},{"text":"、柴胡、芦荟、青皮等分为末。用大黄瓜黄色者一个，割下头，填药至满，盖定签住，慢火煨熟，同捣烂，入面糊丸绿豆大。每服二、三丸，大者五、七丸至十丸，食后新水下。","src":"钱乙《小儿方"},{"text":"咽喉肿痛︰老黄瓜一枚去子，入消填满，阴干为末。每以少许吹之。","src":"医林集要"},{"text":"杖疮肿︰六月六日，取黄瓜入瓷瓶中，水浸之。每以水扫于疮上，立效。","src":"医林集要"},{"text":"火眼赤痛︰五月取老黄瓜一条，上开小孔，去瓤，入芒硝令满，悬阴处，待消透出刮下，留点眼甚效。","src":"寿域神方"},{"text":"汤火伤灼︰五月五日，掐黄瓜入瓶内封，挂檐下，取水刷之，良。","src":"医方摘要"}],"vol":"菜部"},"丝瓜":{"qi":"甘，平，无毒。入药用老者。","zhi":"痘疮不快，枯者烧存性，入朱砂研末，蜜水调服，甚妙（震亨）。煮食，除热利肠。老者烧存性服，去风化痰，凉血解毒，杀虫，通经络，行血脉，下乳汁，治大小便下血，痔漏崩中，黄积，疝痛卵肿，血气作痛，痈疽疮肿，齿，痘疹胎毒（时珍）。暖胃补阳，固气和胎（《生生编》）。","fufang":[{"text":"新二十八。痘疮不快，初出或未出，多者令少，少者令稀︰老丝瓜。","src":"近蒂三寸"},{"text":"连皮烧存性，研末，砂糖水服。","src":"直指"},{"text":"痈疽不敛，疮口太深︰用丝瓜捣汁频抹之。","src":"直指方"},{"text":"风热腮肿︰丝瓜烧存性，研末，水调搽之。","src":"严月轩方"},{"text":"肺热面疮︰苦丝瓜、牙皂荚并烧灰，等分，油调搽。","src":"摘玄方"},{"text":"玉茎疮溃︰丝瓜连子捣汁，和五倍子末，频搽之。","src":"丹溪方"},{"text":"坐板疮疥︰丝瓜皮焙干为末，烧酒调搽之。","src":"摄生众妙方"},{"text":"天泡湿疮︰丝瓜汁调辰粉，频搽之。手足冻疮︰老丝瓜烧存性，和腊猪脂涂之。","src":"海上方"}],"vol":"菜部"},"苦瓜":{"qi":"苦，寒，无毒。","zhi":"除邪热，解劳乏，清心明目（时珍《生生编》）。子【气味】苦、甘，无毒。【主治】益气壮阳（时珍）。","fufang":[],"vol":"菜部"},"紫菜":{"qi":"甘，寒，无毒。藏器曰︰多食令人腹痛发气，吐白沫。饮热醋少许，即消。","zhi":"热气烦塞咽喉，煮汁饮之（孟诜）。病瘿瘤脚气者，宜食之（时珍）。","fufang":[],"vol":"菜部"},"石蒪":{"qi":"甘，平，无毒。","zhi":"下水，利小便（藏器）。主风秘不通，五膈气，并脐下结气，煮汁饮之。胡人用治疳疾（李珣）。","fufang":[],"vol":"菜部"},"石花菜":{"qi":"甘、咸，大寒，滑，无毒。","zhi":"去上焦浮热，发下部虚寒（宁原）。","fufang":[],"vol":"菜部"},"鹿角菜":{"qi":"甘，大寒，滑，无毒。诜曰︰微毒。丈夫不可久食，发痼疾，损腰肾、经络、血气，令人脚冷痺，少颜色。","zhi":"下热风气，疗小儿骨蒸热劳。服丹石人食之，能下石力（士良）。解面热（大明）。","fufang":[],"vol":"菜部"},"龙须菜":{"qi":"甘，寒，无毒。","zhi":"瘿结热气，利小便（时珍）。","fufang":[],"vol":"菜部"},"睡菜":{"qi":"甘、微苦，寒，无毒。","zhi":"心膈邪热不得眠（时珍）。","fufang":[],"vol":"菜部"},"芝":{"qi":"酸，平，无毒。时珍曰︰五色之芝，配以五行之味，盖亦据理而已，未必其味便随五色也。即如五畜以羊属火，五果以杏配心，皆云味苦之义。之才曰︰青、赤、黄、白、黑、紫六芝，并以薯蓣为之使，得发良，得麻子仁、白瓜子、牡桂甚益人，恶常山，畏扁青、茵陈蒿。","zhi":"明目，补肝气，安精魂，仁恕。久食，轻身不老，延年神仙。（《本经》）。不忘强志（《唐本》）。赤芝一名丹芝[编辑]（《本经》）【气味】苦，平，无毒。【主治】胸中结，益心气，补中，增智慧，不忘。久食，轻身不老，延年神仙（《本经》）。黄芝一名金芝[编辑]（《本经》）【气味】甘，平，无毒。【主治】心腹五邪，益脾气，安神，忠信和乐。久食，轻身不老，延年神仙（《本经》）。白芝一名玉芝、素芝[编辑]（《本经》）【气味】辛，平，无毒。【主治】咳逆上气，益肺气，通利口鼻，强志意，勇悍，安魄。久食，轻身不老，延年神仙（《本经》）。黑芝一名玄芝[编辑]（《本经》）【气味】咸，平，无毒。【主治】癃，利水道，益肾气，通九窍，聪察。久服，轻身不老，延年神仙（《本经》）。紫芝一名木芝[编辑]（《本经》）【气味】甘，温，无毒。甄权曰︰平。【主治】耳聋，利关节，保神，益精气，坚筋骨，好颜色。久服，轻身不老延年（《本经》）。疗虚劳，治痔（时珍）。","fufang":[{"text":"治虚劳短气，胸胁苦伤，手足逆冷，或时烦躁口干，目视，腹内时痛，不思饮食，此药安神保精也︰紫芝一两半，山芋。","src":""},{"text":"各三钱五分，生地黄。","src":""},{"text":"、牡丹皮、人参各七钱五分，远志。","src":""},{"text":"、蓼实各二钱五分，瓜子仁。","src":""},{"text":"、泽泻各五钱，为末，炼蜜丸梧子大。每服十五丸，渐至三十丸，温酒下，日三服。","src":"圣济总录"}],"vol":"菜部"},"木耳":{"qi":"甘，平，有小毒。权曰︰蕈耳，古槐、桑树上者良，柘木者次之。其余树上，多动风气，发痼疾，令人肋下急，损经络背膊，闷人。藏器曰︰木耳，恶蛇、虫从下过者，有毒。枫木上生者，令人笑不止。采归色变者有毒，夜视有光者、欲烂不生虫者并有毒，并生捣冬瓜蔓汁解之。时珍曰︰按︰张仲景云︰木耳赤色及仰生者，并不可食。","zhi":"益气不饥，轻身强志（《本经》）。断谷治痔（时珍）。","fufang":[{"text":"木贼一两，为末。每服二钱，以清米泔煎服。","src":"惠济方"},{"text":"血注脚疮︰桑耳、楮耳、牛屎菰各五钱，胎发灰。","src":"男用女，女用男"},{"text":"三钱，研末，油和涂之，或干涂之。","src":"奇效良方"},{"text":"崩中漏下︰木耳半斤，炒见烟，为末，每服二钱一分，头发灰三分，共二钱四分，以应二十四气。好酒调服，出汗。","src":"孙氏《集效方"},{"text":"新久泄痢︰干木耳一两。","src":""},{"text":"为末。每服三钱，温酒调下，日二。","src":"御药院方"},{"text":"五钱，酒服即可。亦用井花水服。或以水煮盐、醋食之，以汁送下。","src":"普济方"},{"text":"一切牙痛︰木耳、荆芥等分，煎汤频漱。","src":"普济方"}],"vol":"菜部"},"杉菌":{"qi":"甘、辛，微温，无毒。","zhi":"心脾气疼，及暴心痛（苏颂）。","fufang":[],"vol":"菜部"},"皂角蕈":{"qi":"辛，有毒。","zhi":"积垢作痛，泡汤饮之，微泄效。未已再服。又治肿毒初起，磨醋涂之，良（时珍）。","fufang":[{"text":"皂角树上蕈，瓦焙为末。每服一钱，温酒下。","src":"许学士《本事方"}],"vol":"菜部"},"香蕈":{"qi":"甘，平，无毒。","zhi":"益气不饥，治风破血（吴瑞）。松蕈︰治溲浊不禁，食之有效（《菌谱》）。","fufang":[],"vol":"菜部"},"葛花菜":{"qi":"苦、甘，无毒。","zhi":"醒神，治酒积（时珍。《太和山志》）。","fufang":[],"vol":"菜部"},"天花蕈":{"qi":"甘，平，无毒。时珍曰︰按︰《正要》云︰有毒。","zhi":"益气，杀虫（吴瑞）。","fufang":[],"vol":"菜部"},"蘑菰蕈":{"qi":"甘，寒，无毒。《正要》曰︰有毒。动气发病，不可多食。","zhi":"益肠胃，化痰理气（时珍。出《生生编》）。","fufang":[],"vol":"菜部"},"鸡㙡":{"qi":"甘，平，无毒。","zhi":"益胃清神，治痔（时珍）。","fufang":[],"vol":"菜部"},"舵菜":{"qi":"咸、甘，寒，无毒。","zhi":"瘿结气，痰饮（时珍）。","fufang":[],"vol":"菜部"},"土菌":{"qi":"甘，寒，有毒。诜曰︰菌子有数般，槐树上者良。野田中者有毒杀人，又多发冷气，令人腹中微微痛，发五脏风，拥经脉，动痔病，令人昏昏多睡，背膊四肢无力。藏器曰︰菌，冬春无毒，夏秋有毒，有蛇、虫从下过也。夜中有光者，欲烂无虫者，煮之不熟者，煮讫照人无影者，上有毛下无纹者，仰卷赤色者，并有毒杀人。中其毒者，地浆及粪汁解之。颖曰︰凡煮菌，投以姜屑、饭粒，若色黑者杀人，否则无毒。时珍曰︰按︰《菌谱》云︰杜蕈生土中，与山中鹅膏蕈相乱。俗言毒之气所成，食之杀人。甚美有恶，食肉不食马肝，未为不知味也。凡中其毒者，必笑不止。解之以苦茗、白矾，酌新水并咽之，无不立愈。又按︰杨士瀛《直指方》云︰广南人杀毒蛇，覆之以草，以水洒之，数日菌生。采干为末，入酒毒人。遇再饮酒，毒发立死。又陈氏《拾遗》云︰南夷以胡蔓草毒人至死，悬尸于树，汁滴地上，生菌子收之，名菌药，毒人至烈。此皆不可不知，故并记之。马勃亦菌类，见草部。","zhi":"烧灰，敷疮疥（藏器）。","fufang":[{"text":"黑牯牛撒粪石上，待生菌子，焙干，草等分为末。以竹筒去两头，紧缚，合住疔上。用水和末一钱，入筒内。少顷沸起，则根拔出。未出，再作二、三次。","src":"医学正传"},{"text":"【附录】鬼盖《别录》有名未用曰︰味甘，平，无毒。主小儿寒热痫。丛生垣墙下，赤色，旦生暮死。一名地盖。弘景曰︰一名朝生，即今鬼伞也。藏器曰︰一名鬼屋。生阴湿处，如菌，其盖黑而茎赤。和醋，敷肿毒、恶疮、马脊肿。杜正伦曰︰鬼伞有小毒。夏日得雨，聚生粪堆，见日即消黑。时珍曰︰此亦土菌之类，朝生夕死者。烧灰治疔肿，以针刺破四边，纳灰入内，经宿出根。地芩[编辑]《别录》曰︰味苦，无毒。主小儿痫，除邪养胎，风痺洗洗寒热，目中青翳，女子带下。生腐木积草处。天雨生盖，如朝生，黄白色。四月采之。时珍曰︰此即鬼盖之色黄白者，其功亦相近。鬼笔[编辑]。","src":"拾遗"}],"vol":"菜部"},"竹蓐":{"qi":"甘、咸，寒，无毒。藏器曰︰苦竹肉︰有大毒。","zhi":"一切赤白痢，和姜、酱食之（孟诜）。苦竹肉︰灰汁炼过食，杀三虫毒邪气，破老血（藏器）。","fufang":[],"vol":"菜部"},"雚菌":{"qi":"咸，平，有小毒。《别录》曰︰甘，微温。权曰︰苦。得酒良，畏鸡子。","zhi":"心痛，温中，去长虫白癣蛲虫，蛇螫毒，症瘕诸虫（《本经》）。疽蜗，去蛔虫、寸白，恶疮（《别录》）。除腹内冷痛，治白秃（甄权）。","fufang":[{"text":"旧一。蛔虫攻心如刺，吐清汁者︰萑菌一两杵末，羊肉和食之，日一顿，大效。","src":"外台秘要"}],"vol":"菜部"},"地耳":{"qi":"甘，寒，无毒。","zhi":"明目益气，令人有子（《别录》）。","fufang":[],"vol":"菜部"},"石耳":{"qi":"甘，平，无毒。颖曰︰冷。段成式曰︰热。","zhi":"久食益色，至老不改，令人不饥，大小便少（吴瑞）。明目益精（时珍）。","fufang":[{"text":"白枯矾一两，密陀僧半两，为末，蒸饼丸梧子大，每米饮下二十丸。","src":"普济方"},{"text":"互考诸菜香薷紫苏紫菀錾菜牛膝苗防风苗薄荷荏苏马兰蒌蒿泽兰根地黄苗诸葵菜酸模菖蒲牛蒡苗青葙苗龙葵决明甘蓝萝红花苗车前苗萱草芦笋茭笋苹海苔菜独帚苗羊蹄蒲笋菜齐头蒿昆布苗昆布地菘蓼芽海藻王瓜百部藕丝荷头芡茎菱茎豆藿豆芽豆荚豆腐罂粟苗椿芽槐芽芜荑枸杞皂荚苗榆芽槿芽棕笋五加此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/菜之三&amp;oldid=2144303”分类：PD-old蔬菜此页面最后编辑于2022年6月4日。","src":"星期六"},{"text":"05:51。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。","src":"请参阅使用条款"},{"text":"在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权。","src":"含署名权"},{"text":"Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501。","src":"c"}],"vol":"菜部"},"李":{"qi":"苦、酸，微温，无毒。时珍曰︰李味甘酸，其苦涩者不可食。不沉水者有毒，不可食。大明曰︰多食令人胪胀，发虚热。诜曰︰临水食之，令发痰疟。不可合雀肉食。合蜜食，损五脏。宗奭曰︰不可合浆水食，发霍乱，涩气而然。服术人忌之。","zhi":"暴食，去痼热，调中（《别录》）。去骨节间劳热（孟诜）。肝病宜食之（思邈）。核仁【气味】苦，平，无毒。【主治】僵仆折，瘀血骨痛（《别录》）。令人好颜色（吴普）。治女子少腹肿满。利小肠，下水气，除浮肿（甄权）。治面黑子（苏颂）。","fufang":[{"text":"用李核仁去皮细研，以鸡子白和如稀饧涂之。至旦以浆水洗去，后涂胡粉。不过五、六日效。忌见风。","src":"崔元亮《海上方"},{"text":"蝎虿螫痛︰苦李仁嚼涂之，良。","src":"古今录验"}],"vol":"果部"},"杏":{"qi":"酸，热，有小毒。（《别录》）颂曰︰杏之类梅者味酢，类桃者味甘。宗奭曰︰凡杏性皆热。小儿多食，致疮痈膈热。扁鹊曰︰多食动宿疾，令人目盲、须眉落。源曰︰多食，生痰热，昏精神。产妇尤忌之。","zhi":"生食多，伤筋骨（《别录》）。曝脯食，止渴，去冷热毒。心之果，心病宜食之（思邈）。核仁","fufang":[{"text":"旧三十七，新二十二。杏金丹《左慈秘诀》云︰亦名草金丹。方出浑皇子，服之长年不死。夏姬服之，寿年七百，乃仙去也。世人不信，皆由不肯精心修治故也。其法︰须人罕到处。寅月杏树地下，通阳气。二月除树下草。三月离树五步作畦垄，以通水。亢旱则引泉灌溉。有霜雪则烧火树下，以救花苞。至五月杏熟自落，收仁六斗，以汤浸去皮及双仁者，用南流水三石和研，取汁两石八斗，去滓。以新铁釜用酥三斤，以糠火及炭然釜，少少磨酥至尽，乃内汁入釜。釜上安盆，盆上钻孔，用弦悬车辖至釜底，以纸塞孔，勿令泄气。初著糠火，一日三动车辖，以衮其汁。五日有露液生，十日白霜起，又二日白霜尽，即金花出，丹乃成也。开盆炙干，以翎扫下，枣肉和，丸梧子大。每服三丸，空心暖酒下。至七日宿疾皆除，喑盲挛跛、疝痔瘿痫疮肿，万病皆愈。久服通灵不死云云。衍文不录。颂曰︰古方用杏仁修治如法，自朝蒸至午，便以慢火微烘，至七日乃收之。每旦空腹啖之，久久不止，驻颜延年，云是夏姬之法。然杏仁能使人血溢，少误必出血不已，或至委顿，故近人少有服者。或云服至二、三年，往往或泻，或脐中出物，皆不可治也。杏酥法︰颂曰︰去风虚，除百病。捣烂杏仁一石，以好酒二石，研滤取汁一石五斗，入白蜜一斗五升搅匀，封于新瓮中，勿泄气。三十日看酒上酥出，即掠取纳瓷器中贮之。取其酒滓团如梨大，置空屋中，作格安之。候成饴脯状，旦服一枚，以前酒下。藏器曰︰杏酪服之，润五脏，去痰嗽。生、熟吃俱可，若半生半熟服之杀人。又法宗奭曰︰治肺燥喘热，大肠秘，润五脏。用杏仁去皮研细，每一升，入水一升半，捣稠汁。入生蜜四两，甘草一寸，银、石器中慢火熬成稀膏，入酥二两同收。每夜沸汤，点服一匙。","src":"衍义"},{"text":"万病丸︰治男妇五劳七伤，一切诸疾。杏仁一斗二升，童子小便煮七次，以蜜四两拌匀，再以童便五升于碗内重蒸，取出日晒夜露数日。任意嚼食，即愈。补肺丸，治咳嗽。用杏仁二大升。","src":"山中者不用，去双仁者"},{"text":"以童子小便二斗浸之，春夏七日，秋冬二七日，连皮尖于砂盆中研滤取汁，煮令鱼眼沸，候软如面糊即成。以粗布摊曝之，可丸即丸服之。食前后总须服三、五十丸，茶、酒任下。忌白水粥。","src":"刘禹锡《传信方"},{"text":"咳嗽寒热，旦夕加重，少喜多嗔，面色不润，忽进忽退，积渐少食，脉弦紧者︰杏仁半斤去皮尖，童子小便二斗浸七日，漉出温水淘洗，砂盆内研如泥，以小便三升煎如膏。每服一钱，熟水下。妇人室女服之，尤妙。","src":"千金方"},{"text":"久患肺气，喘急至咳。甚者不过二剂，永瘥︰杏仁去皮尖二两，童子小便浸，一日一换，夏月三、四换，满半月取出，焙干研细。每服一枣大，薄荷一叶，蜜一鸡头大，水一钟，煎七分，食后温服。忌腥物。","src":"胜金方"},{"text":"咳逆上气，不拘大人小儿︰以杏仁三升去皮尖，炒黄研膏，入蜜一升，杵熟。每食前含之，咽汁。","src":"千金"},{"text":"上气喘急︰杏仁、桃仁各半两，去皮尖炒研，用水调生面和，丸梧子大。每服十丸，姜、蜜汤下，微利为度。","src":"圣济总录"},{"text":"喘促浮肿，小便淋沥︰用杏仁一两，去皮尖熬研，和米煮粥，空心吃二合妙。","src":"心镜"}],"vol":"果部"},"巴旦杏":{"qi":"甘，平，温，无毒。","zhi":"止咳下气，消心腹逆闷（时珍。出《饮膳正要》）。","fufang":[],"vol":"果部"},"梅":{"qi":"酸，平，无毒。大明曰︰多食损齿伤筋，蚀脾胃，令人发膈上痰热。服黄精人忌食之。食梅齿者，嚼胡桃肉解之。《物类相感志》云︰梅子同韶粉食，则不酸，不软牙。","zhi":"下气，除热烦满，安心，止肢体痛，偏枯不仁，死肌，去青黑痣，蚀恶肉（《本经》）。去痺，利筋脉，止下痢，好唾口干（《别录》）。水渍汁饮，治伤寒烦热（弘景）。止渴调中，去痰治疟瘴，止吐逆霍乱，除冷热痢（藏器）。治虚劳骨蒸，消酒毒，令人得睡。和建茶、干姜为丸服，止休息痢，大验（大明）。敛肺涩肠，止久嗽泻痢，反胃噎膈，蛔厥吐利，消肿涌痰，杀虫，解鱼毒、马汗毒、硫黄毒（时珍）。白梅【释名】盐梅、霜梅。【修治】取大青梅以盐汁渍之，日晒夜渍，十日成矣。久乃上霜。【气味】酸、咸，平，无毒。【主治】和药点痣，蚀恶肉（弘景）。刺在肉中者，嚼敷之即出（孟诜）。治刀箭伤，止血，研烂敷之（大明）。乳痈肿毒，杵烂贴之，佳（汪颖）。除痰。（苏颂）。治中风惊痫，喉痺痰厥僵仆，牙关紧闭者，取梅肉揩擦牙龈，涎出即开。又治泻痢烦渴，霍乱吐下，下血血崩，功同乌梅（时珍）。【发明】弘景曰︰生梅、乌梅、白梅，功应相似。好古曰︰乌梅，脾、肺二经血分药也。能收肺气，治燥嗽。肺欲收，急食酸以收之。时珍曰︰乌梅、白梅所主诸病，皆取其酸收之义。惟张仲景治蛔厥乌梅丸及虫方中用者，取虫得酸即止之义，稍有不同耳。《医说》载︰曾鲁公痢血百余日，国医不能疗。陈应之用盐水梅肉一枚研烂，合腊茶，入醋服之，一啜而安。大丞梁庄肃公亦痢血，应之用乌梅、胡黄连、灶下土等分为末，茶调服，亦效。盖血得酸则敛，得寒则止，得苦则涩故也。其蚀恶疮肉，虽是酸收，却有物理之妙。说出《本经》。其法载于《刘涓子鬼遗方》︰用乌梅肉烧存性研，敷恶肉上，一夜立尽。《圣惠》用乌梅和蜜作饼贴者，其力缓。按︰杨起《简便方》云︰起臂生一疽，脓溃百日方愈，中有恶肉突起，如蚕豆大，月余不消，医治不效。因阅本草得此方，试之，一日夜去其大半，再上一日而平。乃知世有奇方如此，遂留心搜刻诸方，始基于此方也。","fufang":[{"text":"方见上。痈疽疮肿，已溃未溃皆可用︰盐白梅烧存性为末，入轻粉少许，香油调，涂四围。","src":"王氏《易简方"},{"text":"喉痺乳蛾︰冰梅丸︰用青梅二十枚。","src":"盐十二两，腌五日，取梅汁"},{"text":"入明矾三两，桔梗、白芷、防风各二两，猪牙皂角三十条，俱为细末，拌汁和梅入瓶收之。每用一枚，噙咽津液。凡中风痰厥，牙关不开，用此擦之尤佳。《总录》︰用白梅包生矾末作丸含咽，或纳吞之。消渴烦闷︰乌梅肉二两，微炒为末。每服二钱，水二盏，煎一盏，去滓，入豉二百粒，煎至半盏，温服。","src":"简要济众方"},{"text":"泄痢口渴︰乌梅煎汤，日饮代茶。","src":"扶寿精方"},{"text":"产后痢渴︰乌梅肉二十个，麦门冬十二分，以水一升，煮七合，细呷之。","src":"必效方"},{"text":"赤痢腹痛《直指》︰用陈白梅同真茶、蜜水各半，煎饮之。《圣惠》︰用乌梅肉。","src":""},{"text":"、黄连各四两，为末，炼蜜丸梧子大。每米饮服二十丸，日三服。便痢脓血︰乌梅一两去核，烧过为末。每服二钱，米饮下，立止。","src":"圣济总录"},{"text":"久痢不止，肠垢已出︰《肘后》︰用乌梅肉二十个，水一盏，煎六分，食前分二服。《袖珍》︰用乌梅肉、白梅肉各七个捣烂，入乳香末少许，杵丸梧桐子大。每服二、三十丸，茶汤下，日三。大便下血，及酒痢、久痢不止︰用乌梅三两，烧存性为末，醋煮米糊和，丸梧子大。每空心米饮服二十丸，日三。","src":"济生方"}],"vol":"果部"},"榔梅":{"qi":"甘、酸，平，无毒。","zhi":"生津止渴，清神下气，消酒（时珍）。","fufang":[],"vol":"果部"},"桃":{"qi":"辛、酸、甘，热，微毒。多食令人有热。诜曰︰能发丹石毒，生者尤损人。思邈曰︰《黄帝书》云︰食桃饱，入水浴，令人成淋及寒热病。时珍曰︰生桃多食，令人膨胀及生痈疖，有损无益。五果列桃为下以此。瑞曰︰桃与鳖同食，患心痛。服术人忌食之。","zhi":"作脯食，益颜色（大明）。肺之果，肺病宜食之（思邈）。冬桃，食之解劳热（时珍。出《尔雅注》）。核仁","fufang":[{"text":"旧十九，新十一。延年去风，令人光润︰用桃仁五合去皮，用粳米饭浆同研，绞汁令尽，温温洗面极妙。","src":"千金翼"},{"text":"偏风不遂，及癖疾︰用桃仁二千七百枚，去皮、尖、双仁，以好酒一斗三升，浸二十一日，取出晒干杵细，作丸如梧子大。每服二十丸，以原酒吞之。","src":"外台秘要"},{"text":"风劳毒肿挛痛，或牵引小腹及腰痛︰桃仁一升去皮尖，熬令黑烟出，热研如脂膏，以酒三升搅和服，暖卧取汗。不过三度瘥。","src":"食医心镜"},{"text":"疟疾寒热︰桃仁一百枚去皮尖，乳钵内研成膏，不得犯生水，入黄丹三钱，丸梧子大。每服三丸，当发日面北温酒吞下。五月五日午时合之，忌鸡、犬、妇人。","src":"见唐慎微《本草"},{"text":"骨蒸作热︰桃仁一百二十枚，留尖去皮及双仁，杵为丸，平旦井花水顿服之。令尽量饮酒至醉，仍须任意吃水。隔日一剂。百日不得食肉。","src":"外台秘要"},{"text":"上气喘急︰方见杏仁。上气咳嗽，胸满气喘︰桃仁三两去皮尖，以水一大升研汁，和粳米二合煮粥食之。","src":"心镜"},{"text":"卒得咳嗽︰桃仁三升去皮杵，著器中密封，蒸熟晒干，绢袋盛，浸二斗酒中，七日可饮，日饮四、五合。尸疰鬼疰，乃五尸之一，又挟鬼邪为祟。其病变动，有三十六种至九十九种。大略使人寒热淋沥，沉沉默默，不知所苦而无处不恶。累年积月，以至于死，死后复传旁人︰急以桃仁五十枚研泥，水煮取四升，服之取吐。吐不尽，三、四日再吐。","src":"肘后方"},{"text":"传尸鬼气，咳嗽癖注气，血气不通，日渐消瘦︰桃仁一两去皮尖杵碎，水一升半煮汁，入米作粥，空心食之。","src":"心镜"}],"vol":"果部"},"栗":{"qi":"咸，温，无毒。诜曰︰吴栗虽大味短，不如北栗。凡栗日中曝干食，即下气补益；不尔犹有木气，不补益也。火煨去汗，亦杀水气。生食则发气，蒸炒熟食则壅气。凡患风水人不宜食，味咸生水也。恭曰︰栗作粉食，胜于菱、芡；但以饲孩儿，令齿不生。宗奭曰︰小儿不可多食。生则难化，熟则滞气，膈食生虫，往往致病。","zhi":"益气，浓肠胃，补肾气，令人耐饥（《别录》）。生食，治腰脚不遂（思邈）。疗筋骨断碎，肿痛瘀血，生嚼涂之，有效（苏恭）。栗楔（音屑）时珍曰︰一球三颗，其中扁者栗楔也。【主治】筋骨风痛（士良）。活血尤效（颂曰︰今衡山合活血丹用之）。每日生食七枚，破冷癖。又生嚼，恶刺，出箭头，敷瘰&#30311;肿毒痛（大明）。","fufang":[{"text":"苇刺入肉︰方同上。马汗入肉成疮者。方同上。","src":"胜金方"},{"text":"马咬成疮︰独颗栗子烧研敷之。","src":"医说"},{"text":"熊虎爪伤︰嚼栗敷之。","src":"肘后"},{"text":"小儿口疮︰大栗煮熟，日日与食之，甚效。","src":"普济"},{"text":"衄血不止︰宣州大栗七枚刺破，连皮烧存性，出火毒，入麝香少许研匀。每服二钱，温水下。","src":"圣济总录"},{"text":"金刃斧伤︰用独壳大栗研傅，或仓卒嚼敷亦可。","src":"集简方"},{"text":"鱼肝一个，乳香二钱半，同捣，丸梧子大。看鲠远近，以线系绵裹一丸，水润吞之，提线钓出也。栗壳。","src":"栗之黑壳也"},{"text":"治丹毒五色无常。剥皮有刺者，煎水洗之。","src":"孟诜。出《肘后方"}],"vol":"果部"},"天师栗":{"qi":"甘，温，无毒。","zhi":"久食，已风挛（时珍。出《益州记》）。","fufang":[],"vol":"果部"},"枣":{"qi":"甘、辛，热，无毒。多食令人寒热。凡羸瘦者不可食。思邈曰︰多食令人热渴膨胀，动脏腑，损脾元，助湿热。大枣[编辑]【释名】干枣（《别录》）、美枣（《别录》）、良枣。《别录》曰︰八月采，曝干。瑞曰︰此即晒干大枣也。味最良美，故宜入药。今人亦有用胶枣之肥大者。【气味】甘，平，无毒。思邈曰︰甘、辛，热，滑，无毒。杲曰︰温。大明曰︰有齿病、疳病、虫䘌人不宜啖枣，小儿尤不宜食。又忌与葱同食，令人五脏不和；与鱼同食，令人腰腹痛。时珍曰︰今人蒸枣多用糖、蜜拌过，久食最损脾、助湿热也。啖枣多，令人齿黄生。故嵇康《养生论》云︰齿处晋而黄，虱处头而黑。","zhi":"心腹邪气，安中，养脾气，平胃气，通九窍，助十二经，补少气、少津液、身中不足，大惊，四肢重，和百药。久服轻身、延年（《本经》。宗奭曰：煮取肉，和脾胃药甚佳）。补中，益气，坚志，强力，除烦闷，疗心下悬，除肠澼。久服不饥、神仙（《别录》）。润心肺，止嗽，补五脏，治虚损，除肠胃癖气。和光粉烧，治疳痢（大明）。小儿患秋痢与蛀，枣食之良（孟诜）。杀乌头、附子、天雄毒（之才）。和阴阳，调营卫，生津液（李杲）。","fufang":[{"text":"以干枣去核，缓火逼燥为末。量多少入少生姜末，白汤点服。调和胃气甚良。","src":"衍义"},{"text":"反胃吐食︰大枣一枚去核，用斑蝥一枚去头翅，入在内，煨熟去蝥，空心食之，白汤下良。小肠气痛︰大枣一枚去核，用斑蝥一枚去头、足、翅，入枣内，纸包煨熟，去蝥食枣，以桂心、荜澄茄汤下。","src":"直指"},{"text":"伤寒热病后，口干咽痛，喜唾︰大枣二十枚，乌梅十枚，捣入蜜丸。含如杏核大，咽汁甚效。","src":"千金方"},{"text":"妇人脏燥，悲伤欲哭，象若神灵，数欠者，大枣汤主之︰大枣十枚，小麦一升，甘草二两，每服一两，水煎服之。亦补脾气。","src":"金匮"},{"text":"妊娠腹痛︰大红枣十四枚，烧焦为末，以小便服之。","src":"梅师"},{"text":"大便燥塞︰大枣一枚去核，入轻粉半钱缚定，煨熟食之，仍以枣汤送下。","src":"直指"},{"text":"咒枣治疟︰执枣一枚，咒曰︰吾有枣一枚，一心归大道。优他或优降，或劈火烧之。念七遍，吹枣上，与病患食之，即愈。","src":"嵝神书"},{"text":"烦闷不眠︰大枣十四枚，葱白七茎，水三升，煮一升，顿服。","src":"千金"}],"vol":"果部"},"仲思枣":{"qi":"甘，温，无毒。","zhi":"补虚益气，润五脏，去痰嗽冷气。久服令人肥健，好颜色，神仙不饥（《开宝》）。","fufang":[],"vol":"果部"},"苦枣":{"qi":"苦，大寒，无毒。","zhi":"伤寒热伏在脏腑，狂荡烦满，大小便闭涩。取肉煮研，和蜜丸服（士良）。此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/果之一&amp;oldid=2710129”分类：PD-old果树此页面最后编辑于2026年4月25日(星期六)11:32。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。（请参阅使用条款）在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权（含署名权）永久有效（详情）。Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501(c)(3)免税、非营利、慈善机构。隐私政策关于维基文库免责声明法律与安全事项联系方式行为准则开发者统计Cookie声明移动版视图搜索搜索开关目录本草纲目/果之一添加语言添加话题","fufang":[],"vol":"果部"},"梨":{"qi":"甘、微酸，寒，无毒。多食令人寒中萎困。金疮、乳妇、血虚者，尤不可志曰︰《别本》云︰梨，甘寒，多食成冷痢。桑梨︰生食冷中，不益人。","zhi":"热嗽，止渴。切片贴烫火伤，止痛不烂（苏恭）。治客热，中风不语，治伤寒热发，解丹石热气、惊邪，利大小便（《开宝》）。除贼风，止心烦气喘热狂。作浆，吐风痰（大明）。猝喑风不语者，生捣汁频服。胸中痞塞热结者，宜多食之（孟诜）。润肺凉心，消痰降火，解疮毒、酒毒（时珍）。","fufang":[{"text":"用香水梨、或鹅梨、或江南雪梨皆可，取汁以蜜汤熬成瓶收。无时以热水或冷水调服，愈乃止。","src":"普济方"},{"text":"猝得咳嗽︰颂曰︰崔元亮《海上方》︰用好梨去核，捣汁一碗，入椒四十粒，煎一沸去滓，纳黑饧一大两，消讫，细细含咽立定。诜曰︰用梨一颗，刺五十孔，每孔纳椒一粒，面裹灰火煨熟，停冷去椒食之。又方︰去核纳酥、蜜，面裹烧熟，冷食。又方︰切片，酥煎食之。又方︰捣汁一升，入酥、蜜各一两，地黄汁一升，煎成含咽。凡治嗽，须喘急定时冷食之。若热食反伤肺，令嗽更剧，不可救也。若反，可作羊肉汤饼饱食之，便卧少时，即佳。痰喘气急︰梨剜空，纳小黑豆令满，留盖合住系定，糠火煨熟，捣作饼。每日食之，至效。","src":"摘玄"},{"text":"喑风失音︰生梨，捣汁一盏饮之，日再服。","src":"食疗本草"},{"text":"小儿风热，昏懵躁闷，不能食︰用消梨三枚切破，以水二升，煮取汁一升，入粳米一合，煮粥食之。","src":"圣惠方"},{"text":"赤目弩肉，日夜痛者︰取好梨一颗捣绞汁，以绵裹黄连片一钱浸汁。仰卧点之。（赤眼肿痛︰鹅梨一枚捣汁，黄连末半两，腻粉一字，和匀绵裹浸梨汁中，日日点之。","src":"圣惠方"},{"text":"捣汁服，解中菌毒。","src":"吴瑞"},{"text":"中水毒病初起，头痛恶寒，拘急心烦︰用梨叶一把捣烂，以酒一盏搅饮。","src":"箧中方"},{"text":"蠷尿疮出黄水︰用梨叶汁涂之，干即易。","src":"箧中方"}],"vol":"果部"},"鹿梨":{"qi":"酸，涩，寒，无毒。","zhi":"煨食治痢（苏颂）。根皮【气味】同实。【主治】疮疥，煎汁洗之（苏颂）。","fufang":[{"text":"鹿梨散︰用鹿梨根、蛇床子各半斤，真剪草四两，硫黄三钱，轻粉一钱。为末。麻油调敷之。小儿涂于绢衣上著之，七日不解，自愈。","src":"仁存方"},{"text":"一切癣︰鹿梨根，刮皮捣烂，醋和麻布包擦之。干者为末，以水和捣。","src":"唐瑶《经验方"}],"vol":"果部"},"棠梨":{"qi":"酸、甘，涩，寒，无毒。","zhi":"烧食，止滑痢（时珍）。枝叶【气味】同实。【主治】霍乱吐泻不止，转筋腹痛，取一握，同木瓜二两煎汁，细呷之（时珍。《圣惠方》）。","fufang":[{"text":"棠梨叶，油炒，去刺，为末。每旦酒服一钱。","src":"山居四要"}],"vol":"果部"},"海红":{"qi":"酸、甘，平，无毒。","zhi":"泄痢（时珍。出《正要》）。","fufang":[],"vol":"果部"},"木瓜":{"qi":"酸，温，无毒。思邈曰︰酸、咸，温，涩。诜曰︰不可多食，损齿及骨。","zhi":"湿痺邪气，霍乱大吐下，转筋不止（《别录》）。治脚气冲心，取嫩者一颗，去子，煎服，佳。强筋骨，下冷气，止呕逆，心膈痰唾，消食，止水利后渴不止，作饮服之（《藏器》）。止吐泻奔豚，及水肿冷热痢，心腹痛（大明）。调营卫，助谷气（雷）。去湿和胃，滋脾益肺，治腹胀善噫，心下烦痞（好古）。","fufang":[{"text":"旧二，新十。项强筋急不可转侧，肝、肾二脏受风也︰用宣州木瓜二个。","src":"取盖去瓤"},{"text":"没药二两，乳香二钱半。二味入木瓜内缚定，饭上蒸三、四次，烂研成膏。每用三钱，入生地黄汁半盏，无灰酒二盏，暖化温服。许叔微云︰有人患此，自午后发，黄昏时定。予谓此必先从足起。足少阴之筋自足至项。筋者肝之合。今日中至黄昏，阳中之阴，肺也。自离至兑，阴旺阳弱之时。故《灵宝毕法》云︰离至干，肾气绝而肝气弱。肝、肾二脏受邪，故发于此时。予授此及都梁丸，服之而愈。","src":"本事方"},{"text":"脚气肿急︰用木瓜切片，囊盛踏之。广德顾安中，患脚气筋急腿肿。因附舟，以足阁一袋医录》）脚筋挛痛︰用木瓜数枚，以酒、水各半，煮烂捣膏，乘热贴于痛处，以帛裹之。冷即换，日三、五度。","src":"食疗本草"},{"text":"脐下绞痛︰木瓜三片，桑叶七片，大枣三枚。水三升，煮半升，顿服即愈。","src":"食疗"},{"text":"小儿洞痢，木瓜捣汁，服之。","src":"千金方"},{"text":"霍乱转筋︰木瓜一两，酒一升，煎服。不饮酒者，煎汤服。仍煎汤，浸青布裹其足。","src":"圣惠"},{"text":"霍乱腹痛︰木瓜五钱，桑叶三片，枣肉一枚。水煎服。","src":"圣惠方"},{"text":"四蒸木瓜丸治肝、肾、脾三经气虚，为风寒暑湿相搏，流注经络。凡遇六气更变，七情不和，必至发动，或肿满，或顽痺，憎寒壮热，呕吐自汗，霍乱吐利。用宣州大木瓜四个，切盖剜空听用︰一个入黄、续断末各半两于内；一个入苍术、橘皮末各半两于内；一个入乌药、黄松节末各半两于内。","src":"黄松节即茯神中心木也"}],"vol":"果部"},"楂子":{"qi":"酸，涩，平，无毒。诜曰︰多食伤气，损齿及筋。","zhi":"断痢（弘景）。去恶心咽酸，止酒痰黄水（藏器）。煮汁饮，治霍乱转筋，功与木瓜相近（孟诜）。","fufang":[],"vol":"果部"},"楂":{"qi":"酸，平，无毒。","zhi":"解酒去痰（弘景）。食之去恶心，止心中酸水（藏器）。煨食，止痢。浸油梳头，治发白、发赤（大明）。煮汁服，治霍乱转筋（吴瑞）。","fufang":[],"vol":"果部"},"??":{"qi":"酸、甘，微温，无毒。士良曰︰发毒热，秘大小肠，聚胸中痰，壅涩血脉，不宜多食。瑞曰︰同车螯食，发疝气。","zhi":"温中，下气消食，除心间酸水，去臭，辟衣鱼（《开宝》）。去胸膈积食，止渴除烦。将卧时，啖一、两枚，生、熟皆宜（苏颂。宗奭曰︰卧时啖此太多，亦痞塞胃脘也）。主水泻肠虚烦热，散酒气，并宜生食（李）。木皮【主治】捣末，敷疮（苏颂）。","fufang":[],"vol":"果部"},"山楂":{"qi":"酸，冷，无毒。时珍曰︰酸、甘，微温。生食多，令人嘈烦易饥，损齿，齿龋人尤不宜也。","zhi":"煮汁服，止水痢。沐头洗身，治疮痒（《唐本》）。煮汁洗漆疮，多瘥（弘景）。治腰痛有效（苏颂）。消食积，补脾，治小肠疝气，发小儿疮疹（吴瑞）。健胃，行结气。治妇人产后儿枕痛，恶露不尽，煎汁入沙糖服之，立效（震亨）。化饮食，消肉积症瘕，痰饮痞满吞酸，滞血痛胀（时珍）。化血块气块，活血（宁原）。","fufang":[{"text":"各一两，为末，糊丸梧桐子大。每服一百丸，空心白汤下。老人腰痛及腿痛︰用棠子、鹿茸。","src":""},{"text":"等分，为末，蜜丸梧桐子大。每服百丸，日二服。肠风下血，用寒药、热药及脾弱药俱不效者︰独用山里果。","src":"俗名酸枣，又名鼻涕团"},{"text":"干者，痘疹不快︰干山楂为末，汤点服之，立出红活。又法︰猴楂五个，酒煎入水，温服即出。痘疮干黑危困者︰用棠子为末，紫草煎酒，调服一钱。","src":"全幼心鉴"},{"text":"食肉不消︰山楂肉四两，水煮食之，并饮其汁。","src":"简便方"}],"vol":"果部"},"赤爪木":{"qi":"苦，寒，无毒。","zhi":"水痢，头风身痒（《唐本》）。根【主治】消积，治反胃（时珍）。茎、叶【主治】煮汁，洗漆疮（时珍。出《肘后》）。","fufang":[],"vol":"果部"},"庵罗果":{"qi":"甘，温，无毒。士良曰︰酸，微寒。志曰︰动风疾。凡天行病及食饱后，俱不可食。同大蒜、辛物食，令人患黄病。","zhi":"食之止渴（《开宝》）。主妇人经脉不通，丈夫营卫中血脉不行。久食，令人不饥（士良）。叶【主治】渴疾，煎汤饮（士良）。","fufang":[],"vol":"果部"},"柰":{"qi":"苦，寒，有小毒。多食令人肺壅、胪胀，有病患尤甚（《别录》）。思邈曰︰酸、苦，寒，涩，无毒。时珍曰︰案︰《正要》云︰频婆︰甘，无毒。","zhi":"补中焦诸不足气，和脾。治猝食饱气壅不通者，捣汁服（孟诜）。益心气，耐饥","fufang":[],"vol":"果部"},"林檎":{"qi":"酸、甘，温，无毒。思邈曰︰酸、苦，平，涩，无毒。多食令人百脉弱。志曰︰多食发热及冷痰涩气，令人好唾，或生疮疖，闭百脉。其子食之，令人烦心。","zhi":"下气消痰，治霍乱肚痛（大明）。消渴者，宜食之（苏颂）。疗水谷痢、泄精（孟诜）。小儿闪癖（时珍）。","fufang":[{"text":"十枚。水二升，煎一升，并林檎食之。","src":"食医心镜"},{"text":"小儿下痢︰林檎、构子同杵汁，任意服之。","src":"子母秘录"},{"text":"小儿闪癖，头发竖黄，瘰&#30311;瘦弱者︰干林檎脯研末，和醋敷之。","src":"同上"}],"vol":"果部"},"柿":{"qi":"甘，寒，涩，无毒。弘景曰︰生啖性冷，服石家宜之，不入药用。不可与蟹同食。","zhi":"压丹石药发热，利水，解酒毒，去胃中热。久食，令人寒中（《开宝》）。止烦渴，润心肺，除腹脏冷热（《日华》）。","fufang":[],"vol":"果部"},"君迁子":{"qi":"甘、涩，平，无毒。","zhi":"止消渴，去烦热，令人润泽（《藏器》）。镇心。久服，悦人颜色，令人轻健（）。","fufang":[],"vol":"果部"},"安石榴":{"qi":"甘、酸，温，涩，无毒。多食损人肺（《别录》）。诜曰︰多食损齿令黑。凡服食药物人忌食之。震亨曰︰榴者，留也。其汁酸性滞，粘膈成痰。","zhi":"咽喉燥渴（《别录》）。能理乳石毒（段成式）。制三尸虫（时珍）。酸石榴【气味】酸，温，涩，无毒。【主治】赤白痢腹痛，连子捣汁，顿服一枚（孟诜）。止泻痢崩中带下（时珍）。","fufang":[{"text":"黑神散︰用酸石榴一个。烟尽，出火毒一夜，研末。仍以酸榴一块，煎汤服久泻不止︰方同上。","src":"并《普济方"},{"text":"痢血五色或脓或水，冷热不调︰酸石榴五枚。","src":"连子"},{"text":"捣汁二升，每服五合，神妙。","src":"圣济"},{"text":"小便不禁︰酸石榴烧存性。","src":"无则用枝烧灰代之"},{"text":"每服二钱，用柏白皮。","src":"切，焙"},{"text":"四钱，煎汤捻须令黑︰酸石榴结成时，就东南枝上拣大者一个，顶上开一孔，内水银半两于中，原皮。","src":"普济"}],"vol":"果部"},"橘":{"qi":"甘、酸，温，无毒弘景曰︰食之多痰，恐非益也。原曰︰多食粘膈生痰，滞肺气。瑞曰︰同螃蟹食，令人患软痈。","zhi":"甘者润肺，酸者聚痰（藏器）。止消渴，开胃，除胸中膈气（大明）。","fufang":[{"text":"治湿痰，因火泛上，停滞胸膈，咳唾稠粘。陈橘皮半斤（入砂锅内，下盐五钱，化水淹过，煮干），粉甘草二两。","src":"去皮，蜜炙"},{"text":"各取净末，蒸饼和丸梧桐子大。每服百丸，白汤下。","src":"丹溪方"},{"text":"宽中丸︰治脾气不和，冷气客于中，壅遏不通，是为胀满。用橘皮四两，白术二两。为末橘皮汤︰治男女伤寒并一切杂病呕哕，手足逆冷者。用橘皮四两，生姜一两。水二升，煎嘈杂吐水︰真橘皮去白为末，五更安五分于掌心舐之，即睡，三日必效。皮不真则不验。","src":"怪证奇方"},{"text":"霍乱吐泻︰不拘男女，但有一点胃气存者，服之再生。广陈皮。","src":"去白"},{"text":"五钱，真藿香五钱。水二盏，煎一盏，时时温服。出《百一选方》。《圣惠》︰用陈橘皮末二钱，汤点服（不省反胃吐食︰真橘皮，以日照西壁土炒香，为末。每服二钱，生姜三片，枣肉一枚，水二钟猝然食噎︰橘皮一两。汤浸去瓤，焙为末。以水一大盏，煎半盏，热服。","src":"食医心镜"},{"text":"诸气呃噫︰橘皮二两。去瓤，水一升，煎五合，顿服。或加枳壳尤良。","src":"孙尚药方"},{"text":"痰膈气胀︰陈皮三钱。水煎热服。","src":"杨氏《简便方"},{"text":"猝然失声︰橘皮半两，水煎，徐呷。","src":"肘后方"}],"vol":"果部"},"柑":{"qi":"甘，大寒，无毒。颂曰︰冷。志曰︰多食令人肺冷生痰，脾冷发痼癖，大肠泻利，发阴汗。","zhi":"利肠胃中热毒，解丹石，止暴渴，利小便（《开宝》）。","fufang":[{"text":"柑橘瓤，阴干，烧存性，研末。温酒服二钱。","src":"集效"},{"text":"解酒毒及酒渴，去白，焙研末，点汤入盐饮之。","src":"大明"},{"text":"治产后肌浮，为末酒服。","src":"藏器"},{"text":"伤寒饮食劳复者，浓煎汁服。","src":"时珍"}],"vol":"果部"},"橙":{"qi":"酸，寒，无毒。士良曰︰暖。多食伤肝气，发虚热。与肉同食，发头旋恶心。时珍曰︰乃水獭之属也。诸家本草皆作槟榔，误矣。","zhi":"洗去酸汁，切和盐、蜜，煎成贮食，止恶心，能去胃中浮风恶气（《开宝》）。行风气，疗瘿气，发瘰&#30311;，杀鱼、蟹毒（士良）。皮【气味】苦、辛，温，无毒。【主治】作酱、醋香美，散肠胃恶气，消食下气，去胃中浮风气（《开宝》）。和盐贮食，止恶心，解酒病（孟诜）。糖作橙丁，甘美，消痰下气，利膈宽中，解酒（时珍）。","fufang":[{"text":"宽中快气，消酒。用橙皮二斤。","src":"切片"},{"text":"入炙甘草末一痔疮肿痛︰隔年风干橙子，桶内烧烟熏之，神效。","src":"医方摘要"}],"vol":"果部"},"柚":{"qi":"酸，寒，无毒。","zhi":"消食，解酒毒，治饮酒人口气，去肠胃中恶气，疗妊妇不思食、口淡（大明）。皮【气味】甘、辛，平，无毒。","fufang":[],"vol":"果部"},"枸橼":{"qi":"辛、酸，无毒。弘景曰︰性温。恭曰︰性冷。陶说误矣。藏器曰︰性温","zhi":"下气，除心头痰水（藏器）。煮酒饮，治痰气咳嗽。煎汤，治心下气痛（时珍）。根、叶【主治】同皮（《橘谱》）。","fufang":[],"vol":"果部"},"金橘":{"qi":"酸、甘，温，无毒。","zhi":"下气快膈，止渴解酲，辟臭。皮尤佳（时珍）。","fufang":[],"vol":"果部"},"枇杷":{"qi":"甘、酸，平，无毒。志曰︰寒。诜曰︰温。多食发痰热，伤脾。同炙肉及热面食，令人患热毒黄疾。","zhi":"止渴下气，利肺气，止吐逆，主上焦热，润五脏（大明）。叶","fufang":[{"text":"、茅根各半斤。水四升，煎二升，稍稍饮之反胃呕哕︰枇杷叶。","src":"去毛，炙"},{"text":"、丁香各一两，人参二两。为末，每服三钱，水一盏，姜三片衄血不止︰枇杷叶。","src":"去毛"},{"text":"焙研末。茶服一、二钱，日二。","src":"同上"},{"text":"酒赤鼻︰枇杷叶、栀子仁等分。为末。每服二钱，温酒调下。日三服。","src":"本事"},{"text":"面上风疮︰方同上。痔疮肿痛︰枇杷叶。","src":"蜜灸"},{"text":"为末。先以乌梅汤洗，贴之。","src":"集要"},{"text":"痘疮溃烂︰枇杷叶，煎汤洗之。","src":"摘玄"}],"vol":"果部"},"杨梅":{"qi":"酸、甘，温，无毒。诜曰︰热，微毒。久食令人发热，损齿及筋。忌生葱同食。瑞曰︰发疮致痰。","zhi":"盐藏食，去痰止呕哕，消食下酒。干作屑，临饮酒时服方寸匕，止吐酒（《开宝》）。止渴，和五脏，能涤肠胃，除烦愦恶气。烧灰服，断下痢，甚验。盐者常含一枚，咽汁，利五脏下气（诜）。","fufang":[{"text":"杨梅烧研，每米饮服二钱，日二服。","src":"普济"},{"text":"风虫牙痛︰《普济方》︰用杨梅根。","src":"皮浓者"}],"vol":"果部"},"樱桃":{"qi":"甘，热，涩，无毒。大明曰︰平，微毒。多食令人吐。诜曰︰食多无损，但发虚热耳。有暗风人不可食，食之立发。李鹏飞曰︰伤筋骨，败血气。有寒热病患不可食。","zhi":"调中，益脾气，令人好颜色，美志（《别录》）。止泄精、水谷痢（孟诜）。","fufang":[],"vol":"果部"},"山婴桃":{"qi":"辛，平，无毒。","zhi":"止泄、肠，除热，调中益脾气，令人好颜色，美志（《别录》）。止泄精（孟诜）。","fufang":[],"vol":"果部"},"银杏":{"qi":"甘、苦，平，涩，无毒。时珍曰︰熟食，小苦微甘，性温有小毒。多食令人胪胀。瑞曰︰多食壅气动风。小儿食多昏霍，发惊引疳。同鳗鲡鱼食，患软风。","zhi":"生食，引疳解酒，熟食益人（李鹏飞）。熟食，温肺益气，定喘嗽，缩小便，止白浊。生食，降痰，消毒杀虫。嚼浆，涂鼻面手足，去皴皱，及疥癣疳阴虱（时珍）。","fufang":[{"text":"白果七个。煨熟，以熟艾作七丸，每果入艾一丸，纸包再煨香，去艾吃。","src":"秘韫》方"},{"text":"哮喘痰嗽︰鸭掌散︰用银杏五个，麻黄二钱半，甘草。","src":""},{"text":"二钱。水一钟半，煎八分，卧十一个。","src":"炒黄"},{"text":"麻黄三钱，苏子二钱，款冬花、法制半夏、桑白皮。","src":"蜜炙"},{"text":"各二钱，杏仁（去皮（并《摄咳嗽失声︰白果仁四两，白茯苓、桑白皮二两，乌豆半升。","src":""},{"text":"蜜半斤。煮熟晒干为末，以乳汁半碗拌湿，九蒸九晒，丸如绿豆大。每服三、五十丸，白汤下，神效。","src":"余居士方"},{"text":"小便频数︰白果十四枚，七生七煨，食之，取效，止。小便白浊︰生白果仁十枚，擂水饮，日一服，取效，止。赤白带下，下元虚惫︰白果、莲肉、江米各五钱，胡椒一钱半。为末。用乌骨鸡一只，去肠风下血︰银杏煨熟，出火气，食之，米饮下。肠风脏毒︰银杏四十九枚，去壳生研，入百药煎末和丸弹子大。每服二、三丸，空心细嚼，米饮送下。","src":"戴原礼《证治要诀"},{"text":"牙齿虫︰生银杏，每食后嚼一、二个，良。","src":"永类钤方"}],"vol":"果部"},"胡桃":{"qi":"甘，平、温，无毒。颂曰︰性热，不可多食。思邈曰︰甘冷滑。多食动痰饮，令人恶心、吐水、吐食物。志曰︰多食动风，脱人眉。同酒食，多令人咯血。颖曰︰多食生痰、动肾火。","zhi":"食之令人肥健、润肌、黑须发。多食利小便、去五痔。捣和胡粉，拔白须发，内孔中，则生黑毛。烧存性，和松脂研，敷瘰&#30311;疮（《开宝》）。食之令人能食，通润血脉，骨肉细腻（诜，方见下）。治损伤、石淋。同破故纸蜜丸服，补下焦（颂）。补气养血，润燥化痰，益命门，利三焦，温肺润肠，治虚寒喘嗽，腰脚重痛，心腹疝痛，血痢肠风，散肿毒，发痘疮，制铜毒（时珍）。油胡桃【气味】辛，热，有毒。【主治】杀虫攻毒，治痈肿、疠风、疥癣、杨梅、白秃诸疮，润须发（时珍）。【发明】韩曰︰破故纸属火，能使心包与命门之火相通。胡桃属木，主润血养血。血属阴，阴恶燥，故油以润之。佐破故纸，有木火相生之妙。故古有云︰黄柏无知母，破故纸无胡桃，犹水母之无虾也。时珍曰︰三焦者，元气之别使。命门者，三焦之本原。盖一原一委也。命门指所居之腑而名，为藏精系胞之物。三焦指分治之部而名，为出纳腐熟之司。盖一以体名，一以用名。其体非脂非肉，白膜裹之，在七节之旁，两肾之间。二系著脊，下通二肾，上通心肺，贯属于脑。为生命之原，相火之主，精气之腑。人物皆有之，生人生物，皆由此出。《灵枢‧本脏论》已著其浓薄缓急直结之状。而扁鹊《难经》不知原委体用之分，以右肾为命门，谓三焦有名无状。而高阳生伪撰《脉诀》，承其谬说，以误后人。至朱肱《南阳活人书》、陈言因方论》、戴起宗《脉诀刊误》，始著说辟之，而知之者尚鲜。胡桃仁颇类其状，而外皮水汁皆青黑。故能入北方，通命门，利三焦，益气养血，与破故纸同为补下焦肾命之药。夫命门气与肾通，藏精血而恶燥。若肾、命不燥，精气内充，则饮食自健，肌肤光泽，肠腑润而血脉通。此胡桃佐补药，有令人肥健能食，润肌黑发固精，治燥调血之功也。命门既通则三焦利，故上通于肺而虚寒喘嗽者宜之，下通于肾而腰脚虚痛者宜之。内而心腹诸痛可止，外而疮肿之毒可散矣。洪氏《夷坚志》只言胡桃治痰嗽能敛肺，盖不知其为命门三焦之药也。油胡桃有毒，伤人咽肺，而疮科取之，用其毒也。胡桃制铜，此又物理之不可晓者。洪迈云︰迈有痰疾，因晚对，上遣使谕令以胡桃肉三颗，生姜三片，卧时嚼服，即饮汤两、三呷，又再嚼桃、姜如前数，即静卧，必愈。迈还玉堂，如旨服之，及旦而痰消嗽止。又溧阳洪辑幼子，病痰喘，凡五昼夜不乳食。医以危告。其妻夜梦观音授方，令服人参胡桃汤。辑急取新罗人参寸许，胡桃肉一枚，煎汤一蚬壳许，灌之，喘即定。明日以汤剥去胡桃皮用之，喘复作。仍连皮用，信宿而瘳。此方不载书册，盖人参定喘，胡桃连皮能敛肺故也。","fufang":[{"text":"诜曰︰凡服胡桃不得并食，须渐渐食之。初日服一颗，每五日加一颗，至二十青娥丸︰方见草部补骨脂。胡桃丸︰益血补髓，强筋壮骨，延年明目，悦心润肌，能除百病。用胡桃仁四两，捣膏，入破故纸、杜仲、萆末各四两。杵匀，丸梧桐子大。每空心温酒、盐汤任下五十丸。","src":"御药院方"},{"text":"消肾溢精︰胡桃丸︰治消肾病，因房欲无节及服丹石，或失志伤肾，遂致水弱火强，口舌附子一枚。","src":"去皮，切片"},{"text":"姜汁、蛤粉同焙为末，蜜丸梧桐子大。每服三十丸，米饮下。","src":"普济方"},{"text":"小便频数︰胡桃煨熟，卧时嚼之，温酒下。石淋痛楚，便中有石子者︰胡桃肉一升，细米煮浆粥一升，相和顿服，即瘥。（崔元亮《风寒无汗，发热头痛︰核桃肉、葱白、细茶、生姜等分。捣烂，水一钟，煎七分，热服。覆衣取汗。","src":"谈野翁方"},{"text":"痰喘咳嗽︰方见发明。老人喘嗽气促，睡卧不得，服此立定︰胡桃肉。","src":""},{"text":"、生姜各一两。研产后气喘︰胡桃肉、人参各二钱。水一盏，煎七分，顿服。久嗽不止︰核桃仁五十个。","src":"煮熟，去皮"},{"text":"人参五两，杏仁三百五十个。","src":"麸炒，汤浸，去皮"},{"text":"食物醋心︰胡桃烂嚼，以生姜汤下，立止。","src":"传信适用方"}],"vol":"果部"},"榛":{"qi":"甘，平，无毒。","zhi":"益气力，实肠胃，令人不饥、健行（《开宝》）。止饥，调中开胃，甚验（大明）","fufang":[],"vol":"果部"},"阿月浑子":{"qi":"辛，温，涩，无毒。","zhi":"诸痢，去冷气，令人肥健（藏器）。治腰冷，阴肾虚弱，房中术多用之，得木香、山茱萸良（李）。无名木皮（《海药》）【气味】辛，大温，无毒。【主治】阴肾萎弱，囊下湿痒，并煎汁小浴，极妙（）。","fufang":[],"vol":"果部"},"槠子":{"qi":"苦、涩，平，无毒。时珍曰︰案︰《正要》云︰酸、甘，微寒。不可多食。","zhi":"食之不饥，令人健行，止泄痢，破恶血，止渴（藏器）。皮、叶【主治】煮汁饮，止产妇血（藏器）。嫩叶︰贴疮，一日三换，良（吴瑞）。","fufang":[],"vol":"果部"},"钩栗":{"qi":"甘，平，无毒。","zhi":"食之不饥，浓肠胃，令人肥健（藏器）。","fufang":[],"vol":"果部"},"橡实":{"qi":"苦，微温，无毒。","zhi":"下痢，浓肠胃，肥健人（苏恭）。涩肠止泻。煮食，止饥，御歉岁（大明）。","fufang":[{"text":"新五。水谷下痢，日夜百余行者︰橡实二两，楮叶。","src":""},{"text":"一两。为末。每服一钱，食前乌梅汤调下血痢不止︰上方加缩砂仁半两。下痢脱肛︰橡斗子，烧存性。研末。猪脂和敷。","src":"直指方"},{"text":"痔疮出血︰橡子粉、糯米粉各一升。炒黄，滚水调作果子，饭上蒸熟食之，不过四、五次，效。","src":"李楼《奇方"},{"text":"肠风下血︰橡斗子壳，用白梅肉填满，两个合定，铁线札住，存性，研末。每服二钱，米饮下。一方︰用硫黄填满，研酒服。","src":"余居士《选奇方"},{"text":"走马牙疳︰橡斗壳，入盐填满，合定烧透，出火毒，研末，入麝香少许。先以米泔漱过，搽之。","src":"全幼心鉴"},{"text":"风虫牙痛︰橡斗五个。","src":"入盐在内"},{"text":"同过，研末。日擦三、五次，木皮、根皮。","src":"拾遗"},{"text":"止水痢，消瘰&#30311;。","src":"大明"}],"vol":"果部"},"槲实":{"qi":"苦，涩，平，无毒。","zhi":"蒸煮作粉，涩肠止痢，功同橡子（时珍）。槲若","fufang":[{"text":"槲叶为末。每服二钱，水一盏，煎七分，和滓服。","src":"简要济众"},{"text":"鼻衄不止︰槲叶。捣汁一小盏，顿服即止。","src":"圣惠方"},{"text":"肠风血痔热多者尤佳︰槲叶。","src":"微炙，研末"},{"text":"一钱。米饮调服。未止冷淋茎痛︰槲叶，研末。每服三钱，水一盏，葱白七寸，煎六分，去滓，食前温服，日二孩子淋疾︰槲叶三片。煎汤服一鸡子壳，小便即时下也。","src":"孙真人方"},{"text":"蝼蛄漏疾︰槲叶，烧存性，研。以米泔别浸槲叶，取汁洗疮后，乃纳灰少许于疮中。","src":"圣惠方"},{"text":"鼻上出脓血者︰以泔水煮槲叶，取汁洗之，拭干，纳槲叶灰少许于中，良。","src":"圣惠"},{"text":"腋下胡臭︰槲若三升。切，水煮浓汁，洗毕，即以甘苦瓠壳烟熏之。后用辛夷、细辛、杜木皮。","src":"俗名赤龙皮"},{"text":"煎汤，洗恶疮，良。","src":"权"}],"vol":"果部"},"荔枝":{"qi":"甘，平，无毒。曰︰甘、酸，热。多食令人发虚热。李鹏飞曰︰生荔枝多食，发热烦渴，口干衄血。颂曰︰多食不伤人。如稍过度，饮蜜浆一杯便解也。时珍曰︰荔枝气味纯阳，其性畏热。鲜者食多，即龈肿口痛，或衄血也。病齿及火病人尤忌之。《开宝本草》言其性平，苏氏谓多食无伤，皆谬说也。按︰《物类相感志》云︰食荔枝多则醉，以壳浸水饮之即解。此即食物不消，还以本物消之之意。","zhi":"止渴，益人颜色（《开宝》）。食之止烦渴，头重心躁，背膊劳闷（李）。通神，益智，健气（孟诜）。治瘰&#30311;瘤赘，赤肿疔肿，发小儿痘疮（时珍）。","fufang":[{"text":"荔枝肉，浸酒饮，并食之。忌生冷。","src":"闻人规《痘疹论"},{"text":"疔疮恶肿︰《普济方》︰用荔枝五个或三个，不用双数，以狗粪中米淘净为末，与糯米粥同研成膏，摊纸上贴之。留一孔出毒气。《济生秘览》︰用荔枝肉、白梅各三个。捣作饼子。贴于疮上，根即出也。风牙疼痛︰《普济》︰用荔枝连壳。","src":"烧存性"},{"text":"研末，擦牙即止。乃治诸药不效仙方也。孙氏呃逆不止︰荔枝七个，连皮核烧存性，为末。白汤调下，立止。","src":"杨拱《医方摘要"},{"text":"妇人血气刺痛︰用荔枝核。","src":"烧存性"},{"text":"一两，为末。每服二钱，盐汤、米饮任下。名蠲痛散。","src":"妇人良方"},{"text":"疝气肿︰孙氏︰用荔枝核。","src":"炒黑色"},{"text":"各等分。每以半两，水一盏半，煎七分，温服，日二服。","src":"普济方"}],"vol":"果部"},"龙眼":{"qi":"甘，平，无毒。恭曰︰甘、酸，温。李鹏飞曰︰生者沸汤瀹过食，不动脾","zhi":"五脏邪气，安志厌食。除蛊毒，去三虫。久服强魂聪明，轻身不老，通神明（《本经》）。开胃益脾，补虚长智（时珍）。","fufang":[{"text":"治思虑过度，劳伤心脾，健忘怔忡，虚烦不眠，自汗惊悸。用龙眼肉、酸枣仁。","src":""}],"vol":"果部"},"龙荔":{"qi":"","zhi":"甘，热，有小毒。生食令人发痫，或见鬼物（时珍出《桂海志》）。","fufang":[],"vol":"果部"},"橄榄":{"qi":"酸、甘，温，无毒。宗奭曰︰味涩，良久乃甘。震亨曰︰味涩而甘，醉饱宜之。然性热，多食能致上壅。时珍曰︰橄榄盐过则不苦涩，同栗子食甚香。按《延寿书》云︰凡食橄榄必去两头，其性热也。过白露摘食，庶不病。","zhi":"生食、煮饮，并消酒毒，解鲐鱼毒（《开宝》）。嚼汁咽之，治鱼鲠（宗）。生啖、煮汁，能解诸毒（苏颂）。开胃下气，止泻（大明）。生津液，止烦渴，治咽喉痛。咀嚼","fufang":[{"text":"小儿落地时，用橄榄一个。","src":"烧研"},{"text":"朱砂末五分和匀，嚼生脂麻一口，吐唾和药，绢包如枣核大，安儿口中，待咂一个时顷，方可与乳。此药取下肠胃秽毒，令儿少疾，及出痘稀少也。","src":"孙氏《集效方"},{"text":"唇裂生疮︰橄榄炒研，猪脂和涂之。牙齿风疳脓血有虫︰用橄榄烧研，入麝香少许，贴之。","src":"圣惠方"},{"text":"下部疳疮︰橄榄烧存性，研末，油调敷之。或加孩儿茶等分。","src":"乾坤生意"},{"text":"阴肾肿︰橄榄核、荔枝核、山楂核等分。","src":"烧存性，"},{"text":"研末。每服二钱，空心茴香汤调下。耳足冻疮︰橄榄核烧研，油调涂之。","src":"乾坤生意"}],"vol":"果部"},"木威子":{"qi":"酸、辛，无毒。时珍曰︰按《广州记》云︰苦，涩。","zhi":"心中恶水，水气（藏器）。","fufang":[],"vol":"果部"},"庵摩勒":{"qi":"甘，寒，无毒。曰︰苦、酸、甘，微寒，涩。","zhi":"风虚热气（《唐本》）。补益强气。合铁粉一斤用，变白不老。取子压汁，和油涂头，生发去风痒，令发生如漆黑也（藏器）。主丹石伤肺，上气咳嗽。久服，轻身延年长生。服乳石人，宜常食之（李）。为末点汤服，解金石毒（宗）。解硫黄毒（时珍。出《益部","fufang":[],"vol":"果部"},"毗梨勒":{"qi":"苦，寒，无毒。曰︰味苦带涩，微温无毒。作浆性热。","zhi":"风虚热气，功同庵摩勒（《唐本》）。暖肠腹，去一切冷气。作浆染须发，变黑色（甄权）。下气，止泻痢。（大明）烧灰，干血有效（李）。","fufang":[{"text":"毗梨勒烧灰，频擦有效。","src":"圣惠方"},{"text":"主消食涩肠下气，及上气咳嗽。并宜入面药。","src":"李"}],"vol":"果部"},"五敛子":{"qi":"酸、甘、涩，平，无毒。","zhi":"风热，生津止渴（时珍）。","fufang":[],"vol":"果部"},"五子实":{"qi":"甘，温，无毒。","zhi":"霍乱金疮，宜食之（时珍。《潮州志》）。","fufang":[],"vol":"果部"},"榧实":{"qi":"甘，平，涩，无毒。瑞曰︰性热，同鹅肉食，生断节风，又上壅人，忌火气。时珍曰︰按︰《物类相感志》云︰榧煮素羹，味更甜美。猪脂炒榧，黑皮自脱。榧子同甘蔗食，其渣自软。又云︰榧子皮反绿豆，能杀人也。","zhi":"常食，治五痔，去三虫蛊毒，鬼疰恶毒（《别录》）。食之，疗寸白虫（弘景）。消谷，助筋骨，行营卫，明目轻身，令人能食。多食一、二升，亦不发病（孟诜）。多食滑肠，五痔人宜之（宗）。治咳嗽白浊，助阳道子（《本经》。旧作彼）【气味】甘，温，有【主治】腹中邪气，去三虫，蛇螫蛊毒，鬼疰伏尸（《本经》）。","fufang":[{"text":"诜曰︰日食榧子七颗，满七日，虫皆化为水也。《外台秘要》︰用榧子一百枚，去皮火燃，啖之，经好食茶叶面黄者︰每日食榧子七令发不落︰榧子三个，胡桃二个，侧柏叶一两，捣浸雪水梳头，发永不落且润也。","src":"圣惠方"},{"text":"猝吐血出︰先食蒸饼两、三个，以榧子为末，白汤服三钱，日三服。","src":"圣济总录"},{"text":"尸咽痛痒、语言不出︰榧实半两，芜荑一两，杏仁、桂各半两，为末，蜜丸弹子大，含咽。","src":"圣济总华（《别录"}],"vol":"果部"},"海松子":{"qi":"甘，小温，无毒。珣曰︰新罗松子甘美大温，去皮食之甚香，与云南松子不同（云南松子似巴豆，其味不及），与卑占国偏桃仁相似。多食发热毒。时珍曰︰按《医说》云︰食胡羊肉不可食松子；而《物类相感志》云︰凡杂色羊肉入松子则无毒。其说不同，何哉？","zhi":"骨节风，头眩，去死肌，变白，散水气，润五脏，不饥（《开宝》）。逐风痺寒气，虚羸少气，补不足，润皮肤，肥五脏（《大明》）。主诸风，温肠胃。久服，轻身延年不老（李珣）。润肺，治燥结咳嗽（时珍）。同柏子仁，治虚秘（宗奭）。","fufang":[{"text":"去木皮，捣如膏收之。每服鸡子大，酒调下，日三服。百日身轻，三百日行五百里，绝谷，久服神仙。渴即饮水。亦可以炼过松脂同服之。","src":"圣惠方"},{"text":"肺燥咳嗽︰苏游凤髓汤︰用松子仁一两，胡桃仁二两，研膏，和熟蜜半两收之。每服二钱，食后沸汤点服。","src":"外台秘要"},{"text":"小儿寒嗽或作壅喘︰用松子仁五个，百部。","src":""},{"text":"、麻黄各三分，杏仁四十个（去皮尖，以少水略煮三、五沸，化白砂糖丸芡子大。每食后含化十丸，大妙。","src":"钱乙《小儿方"},{"text":"大便虚秘︰松子仁、柏子仁、麻子仁等分，研泥，溶白蜡和，丸梧桐子大。每服五十丸，黄汤下。","src":"寇宗奭"}],"vol":"果部"},"槟榔":{"qi":"苦、辛，温，涩，无毒。甄权曰︰味甘，大寒。大明曰︰味涩。弘景曰︰交州者味甘，广州者味涩。曰︰白者味甘，赤者味苦。元素曰︰味辛而苦，纯阳也。无毒。诜曰︰多食亦发热。","zhi":"消谷逐水，除痰，杀三虫，伏尸，疗寸白（《别录》）。治腹胀，生捣末服，利水谷道；敷疮，生肌肉止痛；烧灰，敷口吻白疮（苏宣利五脏六腑壅滞，破胸中气，下水肿，治心痛积聚（甄权）。除一切风，下一切气，通关节，利九窍，补五劳七伤，健脾调中，除烦，破症结（大明）。主贲豚膀胱诸气，五膈气，风冷气，脚气，宿食不消古）。","fufang":[{"text":"槟榔为末，白汤每服一钱。","src":"御药院方"},{"text":"呕吐痰水︰白槟榔一颗。","src":"煨热"},{"text":"为末。水一盏，煎半盏，温服。","src":"千金"},{"text":"醋心吐水︰槟榔四两，橘皮一两，为末。每服方寸匕，空心生蜜汤调下。","src":"梅师方"},{"text":"伤寒结胸已经汗、下后者︰槟榔二两，酒二盏，煎一盏，分二服。","src":"庞安时《伤寒论"},{"text":"蛔厥腹痛︰方同上。心脾作痛︰鸡心槟榔、高良姜各一钱半，陈米百粒，同以水煎，服之。","src":"直指"},{"text":"膀胱诸气︰槟榔二枚，一生一熟，为末。酒煎服之，良。此太医秦鸣鹤方也。","src":"海药本草"},{"text":"本脏气痛︰鸡心槟榔，以小便磨半个服。或用热酒调末一钱服之。","src":"斗门方"}],"vol":"果部"},"大腹子":{"qi":"辛，涩，温，无毒。","zhi":"与槟榔同功（时珍）。大腹皮","fufang":[{"text":"乌癞风疮︰大腹子，生者或干者，连全皮勿伤动，以酒一升浸之，慢火熬干为末，腊猪脂和敷。","src":"圣济总录"}],"vol":"果部"},"椰子":{"qi":"甘，平，无毒。","zhi":"益气（《开宝》）。治风（汪颖）。食之不饥，令人面泽（时珍。出《异椰子浆【气味】甘，温，无毒。曰︰多食，冷而动气。时珍曰︰其性热，故饮之者多昏如醉状。《异物志》云︰食其肉则不饥，饮其浆则增渴【主治】止消渴。涂头，益发令黑（《开宝》）。治吐血水肿","fufang":[],"vol":"果部"},"无漏子":{"qi":"甘，温，无毒。","zhi":"补中益气，除痰嗽，补虚损，好颜色，令人肥健（藏器）。消食止咳，治虚羸，悦人。久服无损（李）。","fufang":[],"vol":"果部"},"桄榔子":{"qi":"苦，平，无毒。","zhi":"破宿血（《开宝》）。面【气味】甘，平，无毒。【主治】作饼炙食腴美，令人不饥，补益虚羸损乏，腰脚无力。久服轻身辟谷（李）。","fufang":[],"vol":"果部"},"䔋木面":{"qi":"甘，平、温，无毒。","zhi":"补益虚冷，消食（李珣）。温补。久食不饥，长生（藏器）。","fufang":[],"vol":"果部"},"波罗蜜":{"qi":"甘、香、微酸，平，无毒。","zhi":"止渴解烦，醒酒益气，令人悦泽（时珍）。核中仁【气味】同瓤。【主治】补中益气，令人不饥轻健（时珍）。","fufang":[],"vol":"果部"},"无花果":{"qi":"甘，平，无毒。","zhi":"开胃，止泄痢（汪颖）。治五痔，咽喉痛（时珍）。叶【气味】甘、微辛，平，有小毒。【主治】五痔肿痛，煎汤频熏洗之，取效（震亨）。","fufang":[],"vol":"果部"},"阿勒勃":{"qi":"苦，大寒，无毒。","zhi":"心膈间热风，心黄，骨蒸寒热，杀三虫（藏器）。炙黄入药，治热病，下痰，通经络，疗小儿疳气（李）。【附录】罗望子时珍曰︰按︰《桂海志》云︰出广西。壳长数寸，如肥皂及刀豆，色正丹，内有二、三子，煨食甘美。","fufang":[],"vol":"果部"},"沙棠果":{"qi":"甘，平，无毒。","zhi":"食之，却水病（时珍。《山海经》）。","fufang":[],"vol":"果部"},"棎子":{"qi":"甘，涩，平，无毒。","zhi":"生食之，止水痢。熟和蜜食之，去嗽（藏器）。","fufang":[],"vol":"果部"},"麂目":{"qi":"酸、甘，小冷，无毒。多食，发冷痰（藏器）。","zhi":"","fufang":[],"vol":"果部"},"都桷子":{"qi":"酸、涩，平，无毒。","zhi":"久食，益气止泄（藏器）。安神温肠，治痔。久服无损（李）。解酒，止烦渴（时珍）","fufang":[],"vol":"果部"},"都念子":{"qi":"甘、酸，小温，无毒。","zhi":"痰嗽哕气（藏器）。暖腹脏，益肌肉（时珍。《岭表录异》）。","fufang":[],"vol":"果部"},"都咸子":{"qi":"甘，平，无毒。","zhi":"火干作饮，止渴润肺，去烦除痰（藏器）。去伤","fufang":[],"vol":"果部"},"摩厨子":{"qi":"甘，香，平，无毒。","zhi":"益气，润五脏。久服令人肥健（藏器）。安神养血生肌，久服轻健（李）。","fufang":[],"vol":"果部"},"韶子":{"qi":"甘，温，无毒。","zhi":"暴痢，心腹冷气（藏器）。","fufang":[],"vol":"果部"},"马槟榔":{"qi":"甘，寒，无毒。核仁【气味】苦、甘，寒，无毒机曰︰凡嚼之者，以冷水一口送下，其甜如蜜，亦不伤人也。","zhi":"产难，临时细嚼数枚，井华水送下，须臾立产。再以四枚去壳，两手各握二枚，恶水自下也。欲断产者，常嚼二枚，水下。久则子宫冷，自不孕矣（汪机）。伤寒热病，食数枚，冷水下。又治恶疮","fufang":[],"vol":"果部"},"枳椇":{"qi":"甘，平，无毒。诜曰︰多食发蚘虫。","zhi":"头风，小腹拘急（《唐本》）。止渴除烦，去膈上热，润五脏，利大小便，功用同蜂蜜。枝、叶煎膏亦同（藏器）。止呕逆，解酒毒","fufang":[{"text":"此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/果之三&amp;oldid=2675514”分类：PD-old果树此页面最后编辑于2026年3月19日。","src":"星期四"},{"text":"15:24。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。","src":"请参阅使用条款"},{"text":"在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权。","src":"含署名权"},{"text":"Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501。","src":"c"}],"vol":"果部"},"秦椒":{"qi":"辛，温，有毒。《别录》曰︰生温、熟寒，有毒之才曰︰恶栝蒌、防葵，畏雌黄。","zhi":"除风邪气，温中，去寒痺，坚齿发，明目。久服，轻身好颜色，耐老增年通神（《本经》）。疗喉痺吐逆疝瘕，去老血，产后余疾腹痛，出汗，利五脏（《别录》）。上气咳嗽，久风湿痺（孟诜）。治恶风遍身，四肢痺，口齿浮肿摇动，女人月闭不通，产后恶血痢，多年痢，疗腹中冷痛，","fufang":[{"text":"瓜蒂二分，为末。水服方寸匕，日三服。","src":"伤寒类要"},{"text":"乃风也︰椒、盐末等分，醋和敷之，良。","src":"肘后方"},{"text":"损疮中风︰以面作馄饨，包秦椒，于灰中烧之令热，断使开口，封于疮上，冷即易之。（孟久患口疮︰大椒，去闭口者，水洗面拌，煮作粥，空腹吞之，以饭压下。重者可再服，以瘥为度。","src":"食疗本草"},{"text":"牙齿风痛︰秦椒煎醋含漱。","src":"孟诜《食疗"},{"text":"百虫入耳︰椒末一钱，醋半盏，浸良久，稍稍滴入，自出。","src":"续十全方"}],"vol":"果部"},"蜀椒":{"qi":"辛，温，有毒。《别录》曰︰大热。多食，令人乏气喘促。口闭者杀人。诜曰︰十月食椒，损气伤心，令人多忘。李鹏飞曰︰久食，令人失明，伤血脉。之才曰︰杏仁为之使，得盐味佳，畏款冬花、防风、附子、雄黄。可收水银。中其毒者，凉水、麻仁浆解之。","zhi":"邪气咳逆，温中，逐骨节皮肤死肌，寒湿痺痛，下气。久服头不白，轻身增年（《本经》）。除六腑寒冷，伤寒温疟大风汗不出，心腹留饮宿食，肠下痢，泄精，女子字乳余疾，散风邪瘕结，水肿黄胆，鬼疰蛊毒，杀虫、鱼毒。久服开腠理，通血脉，坚齿发，明目，调关节，耐寒暑，可作膏药（《别录》）。治头风下泪，腰脚不遂，虚损留结，破血，下诸石水，治咳嗽，腹内冷痛，除齿痛（甄权）。破症结开胸，治天行时气，产后宿血，壮阳，疗阴汗，暖腰膝，缩小便，止呕逆（大明）。通神去老，益血，利五脏，下乳汁，灭瘢，生毛发（孟诜）。散寒除湿，解郁结，消宿食，通三焦，温脾胃，补右肾命门，杀蛔虫，止泄泻（时珍）。","fufang":[{"text":"治元脏伤惫，目暗耳聋。服此百日，觉身轻少睡，足有力，是其效也。服及三年，心智爽悟，目明倍常，面色红悦，髭发光黑。用蜀椒去目及合口者，炒出汗，曝干，捣取红一斤。以生地黄捣自然汁，入铜器中煎至一升，候稀稠得所，和椒末丸梧桐子大。每空心暖酒下三十丸。合药时勿令妇人、鸡、犬见。诗云︰其椒应五行，其仁通六义。欲知先有功，夜间无梦寐。四时去烦劳，五脏调元气。明目腰不痛，身轻心健记。别更有异能，三年精自秘。回老返婴童，康强不思睡。九虫顿消亡，三尸自逃避。若能久饵之，神仙应可冀。补益心肾︰《仙方》椒苓丸︰补益心肾，明目驻颜，顺气祛风延年。真川椒一斤。","src":"炒去汗"},{"text":"为末，炼蜜丸梧桐子大。每服五十丸，空心盐汤下。忌铁器。","src":"邵真人《经验方"},{"text":"虚冷短气︰川椒三两，去目并合口者，以生绢袋盛，浸无灰酒五升中三日，随性饮之。腹内虚冷︰用生椒择去不拆者，用四十粒，以浆水浸一宿，令合口，空心新汲水吞下。久服暖脏腑，驻颜黑发、明目，令人思饮食。","src":"斗门方"},{"text":"心腹冷痛︰以布裹椒安痛处，用熨斗熨令椒出汗，即止。","src":"孙真人方"},{"text":"冷虫心痛︰川椒四两，炒出汗，酒一碗淋之，服酒。","src":"寿域神方"},{"text":"阴冷入腹︰有人阴冷，渐渐冷气入阴囊肿满，日夜疼闷欲死。以布裹椒包囊下，热气大通，日再易之，以消为度。","src":"千金"},{"text":"呃噫不止︰川椒四两，炒研，面糊丸梧桐子大。每服十丸，醋汤下，神效。","src":"邵以正《经验方"},{"text":"传尸劳疰︰最杀劳虫。用真川椒红色者，去子及合口，以黄草纸二重隔之，炒出汗，取放地上，以砂盆盖定，以火灰密遮四旁，约一时许，为细末，去壳，以老酒浸白糕和，丸梧子大。每服四十丸，食前盐汤下。服至二斤，其疾自愈。此药兼治诸痺，用肉桂煎汤下；腰痛，用茴香汤下；肾冷，用盐汤下。昔有一人病此，遇异人授是方，服至二斤，吐出一虫如蛇而安，遂名神授丸。","src":"陈言《三因方"}],"vol":"果部"},"崖椒":{"qi":"辛，热，无毒。忌盐。时珍曰︰有毒。","zhi":"肺气上喘，兼咳嗽。并野姜为末，酒服一钱匕（苏颂）","fufang":[],"vol":"果部"},"蔓椒":{"qi":"苦，温，无毒。","zhi":"风寒湿痺，历节疼，除四肢厥气，膝痛，煎汤蒸浴，取汗（《本经》）。根主痔，烧末服，并煮汁浸之（藏器）。贼风挛急（孟诜）。通身水肿，用枝叶煎汁，熬如饧状，每空心服一匙，日三服（时珍。出《千金》）。","fufang":[],"vol":"果部"},"地椒":{"qi":"辛，温，有小毒。","zhi":"淋渫肿痛。可作杀蛀虫药（《嘉祐》）。","fufang":[{"text":"地花椒、川芎尖等分。为末，擦之。","src":"海上名方"}],"vol":"果部"},"胡椒":{"qi":"辛，大温，无毒。时珍曰︰辛热纯阳，走气助火，昏目发疮。曰︰多食损肺，令人吐血。","zhi":"下气温中去痰，除脏腑中风冷（《唐本》）。去胃口虚冷气，宿食不消，霍乱气逆，心腹猝痛，冷气上冲（李）。调五脏，壮肾气，治冷痢，杀一切鱼、肉、鳖、蕈毒（大明）。去胃寒吐水，大肠寒滑（宗）。暖肠胃，除寒湿，反","fufang":[{"text":"胡椒三七枚，清酒吞之。或云一岁一粒。","src":"孟诜《食疗"},{"text":"心下大痛︰《寿域方》︰用椒四十九粒，乳香一钱，研匀。男用生姜、女用当归酒下。又方︰用椒五分，没药三钱，研细。分二服，温酒下。又方︰胡椒、绿豆各四十九粒研烂，酒下神效。霍乱吐泻︰孙真人︰用胡椒三十粒，以饮吞之。《直指方》︰用胡椒四十九粒，绿豆一百四十九粒。研匀，木瓜汤服一钱。反胃吐食︰戴原礼方︰用胡椒醋浸，晒干，如此七次，为末，酒糊丸梧桐子大。每服三、四十丸，醋汤下。《圣惠方》︰用胡椒七钱半，煨姜一两，水煎，分二服。《是斋百一方》︰用胡椒、半夏。","src":"汤泡"},{"text":"等分，为末，夏月冷泻及霍乱︰用胡椒碾末，饭丸梧桐子大。每米饮下四十丸。","src":"卫生易简方"},{"text":"赤白下痢︰胡椒、绿豆各一岁一粒，为末，糊丸梧桐子大。红用生姜、白用米汤下。","src":"集简方"},{"text":"大小便闭，关格不通，胀闷二、三日则杀人︰胡椒二十一粒，打碎，水一盏，煎六分，去滓，入芒硝半两，煎化服。","src":"总录"},{"text":"小儿虚胀︰塌气丸︰用胡椒一两，蝎尾半两。为末，面糊丸粟米大。每服五七丸，陈米饮下。一加莱菔子半两。","src":"钱乙方"},{"text":"虚寒积癖在背膜之外，流于两胁，气逆喘急，久则营卫凝滞，溃为痈疽，多致不救︰用胡椒二百五十粒，蝎尾四个，生木香二钱半，为末，粟米饭丸绿豆大。每服二十丸，橘皮汤下。名磨积丸。","src":"济生方"},{"text":"房劳阴毒︰胡椒七粒，葱心二寸半，麝香一分，捣烂，以黄蜡溶和，做成条子，插入阴内，少顷汗出即愈。","src":"孙氏《集效方"}],"vol":"果部"},"毕澄茄":{"qi":"辛，温，无毒。曰︰辛、苦，微温。","zhi":"下气消食，去皮肤风，心腹间气胀，令人能食，疗鬼气。能染发及香身（藏器）。治一切冷气痰，并霍乱吐泻，肚腹痛，肾气膀胱冷","fufang":[{"text":"旧一，新五。脾胃虚弱，胸膈不快，不进饮食︰用荜澄茄为末，姜汁打神曲糊，丸梧桐子大。每姜汤下七十丸，日二服。《济生方》噎食不纳︰荜澄茄、白豆蔻等分。为末。干舐之。","src":"寿域神方"},{"text":"反胃吐食，吐出黑汁，治不愈者︰用荜澄茄为末，米糊丸梧桐子大。每姜汤下三、四十丸，日一服。愈后服平胃散三百帖。","src":"永类钤方"},{"text":"伤寒咳逆呃噫，日夜不定者︰用荜澄茄、高良姜各等分，为末。每服二钱，水六分，煎十沸，入酢少许，服之。","src":"苏颂《图经"},{"text":"痘疮入目，羞明生翳︰荜澄茄末，吹少许入鼻中，三、五次效。","src":"飞鸿集"},{"text":"鼻塞不通，肺气上攻而致者︰荜澄茄丸︰用荜澄茄半两，薄荷叶三钱，荆芥穗一钱半，为末，蜜丸芡子大。时时含咽。","src":"御药院方"}],"vol":"果部"},"吴茱萸":{"qi":"辛，温，有小毒。权曰︰辛、苦，大热，有毒。好古曰︰辛、苦，热。气味俱浓，阳中阴也。半浮半沉，入足太阴经血分，少阴、厥阴经气分。思邈曰︰陈久者良，闭口者有毒。多食伤神，令人起伏气，咽喉不通。时珍曰︰辛热，走气动火，昏目发疮。之才曰︰蓼实为之使。恶丹参、硝石、白垩，畏紫石英。","zhi":"温中下气，止痛，除湿血痺，逐风邪，开腠理，咳逆寒热（《本经》）。利五脏，去痰冷逆气，饮食不消，心腹诸冷绞痛，中恶，心腹痛（《别录》）。霍乱转筋，胃冷吐泻腹痛，产后心痛，治遍身𤸷痺刺痛，腰脚软弱，利大肠壅气，肠风痔疾，杀三虫（甄权）。杀恶虫毒，牙齿虫䘌，鬼魅疰气（藏器）。下产后余血，治肾气、脚气水肿，通关节，起阳健脾（大明）。主痢，止泻，浓肠胃，肥健人（孟诜）。治痞满塞胸，咽膈不通，润肝燥脾（好古）。开郁化滞，治吞酸，厥阴痰涎头痛，阴毒腹痛，疝气血痢，喉舌口疮（时珍）。","fufang":[{"text":"旧二十四，新二十二。风𤸷痒痺︰茱萸一升，酒五升，煮取一升半，温洗之，立止。","src":"孟诜《食疗"},{"text":"贼风口偏，不能语者︰茱萸一升，姜豉三升，清酒五升，和煎五沸，待冷服半升，一日三服，得少汗即瘥。","src":"同上"},{"text":"冬月感寒︰吴茱萸五钱。煎汤服之，取汗。头风作痛︰茱萸煎浓汤，以绵染，频拭发根良。","src":"千金翼方"},{"text":"呕涎头痛︰吴茱萸汤︰用茱萸一升，枣二十枚，生姜一大两，人参一两，以水五升，煎取三升，每服七合，日三服。","src":"仲景方"},{"text":"呕而胸满︰方同上。脚气冲心︰吴茱萸、生姜擂汁饮，甚良。","src":"孟诜方"},{"text":"肾气上哕︰肾气自腹中起，上筑于咽喉，逆气连属而不能出，或至数十声，上下不得喘息。此由寒伤胃脘，肾虚气逆，上乘于胃，与气相并。《难经》谓之哕。《素问》云︰病深者，其声哕。宜服此方。如不止，灸期门、关元、肾俞穴。用吴茱萸。","src":"醋炒热"},{"text":"各一两，为末，面糊丸梧桐子大。每姜汤下七十丸。","src":"孙氏《仁存方"},{"text":"阴毒伤寒，四肢逆冷︰用茱萸一升，酒拌湿，绢袋二个，包蒸极热，更互熨足心。候气透，中恶心痛︰吴茱萸五合。酒三升，煮沸，分三服。","src":"杨氏《产乳"}],"vol":"果部"},"食茱萸":{"qi":"辛、苦，大热，无毒。时珍曰︰有小毒，动脾火，病目者忌之。颖曰︰发疮痔、浮肿、虚恚。之才曰︰畏紫石英。","zhi":"功同吴茱萸，力稍劣尔。疗水气用之佳（苏恭）。心腹冷气痛，中恶，除咳逆，去脏腑冷，温中，甚良（孟诜）。疗蛊毒飞尸著喉口者，刺破，以子揩之，令血出，当下涎沫。煮汁服之，去暴冷腹痛，食不消，杀腥物（藏器）。治冷痢带下，暖胃燥湿（时珍）。","fufang":[{"text":"子、石菖蒲等分，为末。每旦盐、酒温服二钱。","src":"经验方"}],"vol":"果部"},"盐麸子":{"qi":"酸、咸，微寒，无毒。盐霜制汞、硫。","zhi":"除痰饮瘴疟，喉中热结喉痺，止渴，解酒毒黄胆，飞尸蛊毒，天行寒热，痰嗽，变白，生毛发，去头上白屑，捣末服之（藏器）。生津，降火化痰，润肺滋肾，消毒止痢收汗，治风湿眼病（时珍）。","fufang":[],"vol":"果部"},"醋林子":{"qi":"酸，温，无毒。","zhi":"久痢不瘥，及痔漏下血，蛔咬心痛，小儿疳蛔，心腹胀满黄瘦，下寸白虫，单捣为末，酒调一钱匕服之甚效。盐、醋藏者，食之生津液，醒酒止渴。多食，令人口舌粗拆也（苏颂）。","fufang":[],"vol":"果部"},"茗":{"qi":"苦、甘，微寒，无毒藏器曰︰苦寒，久食，令人瘦，去人脂，使人不睡。饮之宜热，冷则聚痰。胡洽曰︰与榧同食，令人身重。李鹏飞曰︰大渴及酒后饮茶，水入肾经，令人腰、脚、膀胱冷痛，兼患水肿、挛痺诸疾。大抵饮茶宜热、宜少，不饮尤佳，空腹最忌之。时珍曰︰服威灵仙、土茯苓者，忌饮茶。","zhi":"疮，利小便，去痰热，止渴，令人少睡，有力悦志（《神农食经》）。下气消食。作饮，加茱萸清头目，治中风昏愦，多睡不醒（好古）。治伤暑。合醋，治泄痢，甚效（陈承）。炒煎饮，治热毒赤白痢。同芎、葱白煎饮，止头痛","fufang":[{"text":"用上春茶末调成膏，置瓦盏内覆转，以巴豆四十粒，作二次烧烟熏之，晒干乳细。每服一字，别入好茶末，食后煎服，立效。","src":"医方大成"},{"text":"热毒下痢︰《食医心镜》︰赤白下痢。以好茶一斤，炙捣末，浓煎一、二盏服。久患痢者，亦宜服之。《直指》︰用蜡茶，赤痢以蜜水煎服，白痢以连皮自然姜汁同水煎服。二、三服即愈。《经验良方》︰用蜡茶二钱，汤点七分，入麻油一蚬壳和服，须臾腹痛大下即止。一少年用之有效。一方︰蜡茶末，以白梅肉和丸。赤痢甘草汤下白痢乌梅汤下，各百丸。一方︰建茶合醋煎，热服，即止。大便下血︰营卫气虚，或受风邪，或食生冷，或啖炙爆，或饮食过度，积热肠间，使脾胃受伤，糟粕不聚，大便下利清血，脐腹作痛，里急后重，及酒毒一切下血，并皆治之。用细茶半斤。","src":"碾末"},{"text":"每服二钱，米饮下，日二服。（《产后秘塞︰以葱涎调蜡茶末，丸百丸，茶服自通。不可用大黄利药，利者百无一生。","src":"郭稽中《妇人方"},{"text":"久年心痛十年、五年者︰煎湖茶，以头醋和匀，服之良腰痛难转︰煎茶五合，投醋二合，顿服。","src":"食医心镜"},{"text":"嗜茶成癖︰一人病此，一方士令以新鞋盛茶令满，任意食尽，再盛一鞋，如此三度，自不吃也。男用女鞋，女用男鞋，用之果愈也。（解诸中毒︰芽茶、白矾等分，碾末，冷水调下。","src":"简便方"},{"text":"痘疮作痒︰房中宜烧茶烟恒熏之。阴囊生疮︰用蜡面茶，为末。先以甘草汤洗，后贴之妙。","src":"经验方"},{"text":"脚丫湿烂︰茶叶嚼烂敷之，有效。","src":"摄生方"},{"text":"蠷尿疮︰初如糁粟，渐大如豆，更大如火烙浆，疼痛至甚者。速以草茶，并蜡茶俱可，以生油调敷。药至，痛立止。（《胜金风痰颠疾︰茶芽、栀子各一两。煎浓汁一碗服。良久探吐。（霍乱烦闷︰茶末一钱煎水，调干姜末一钱，服之即安。","src":"圣济总录"}],"vol":"果部"},"皋芦":{"qi":"苦，平，无毒。时珍曰︰寒。胃冷者不可用。","zhi":"煮饮，止渴明目除烦，令人不睡，消痰利水（藏器）。通小肠，治淋，止头痛烦热（李珣）。噙咽清上膈、利咽喉（时珍）。此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/果之四&amp;oldid=2639626”分类：PD-old果树此页面最后编辑于2026年1月6日(星期二)16:19。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。（请参阅使用条款）在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权（含署名权）永久有效（详情）。Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501(c)(3)免税、非营利、慈善机构。隐私政策关于维基文库免责声明法律与安全事项联系方式行为准则开发者统计Cookie声明移动版视图搜索搜索开关目录本草纲目/果之四添加语言添加话题","fufang":[],"vol":"果部"},"甜瓜":{"qi":"甘，寒，滑，有小毒。大明曰︰无毒。思邈曰︰多食，发黄胆，令人虚羸多忘，解药力。病后食多，或反胃。脚气人食之，患永不除也。诜曰︰多食，令人阴下湿痒生疮，动宿冷症癖病，破腹，发虚热，令人气弱，脚手无力。少食则可。《龙鱼河图》云︰凡瓜有两鼻、两蒂者，杀人。五月瓜沉水者，食之得冷病，终身不瘥。九月被霜者，食之冬病寒热。与油饼同食，发病。多食瓜作胀者，食盐花即化。弘景曰︰食瓜多，即入水自渍，便消。时珍曰︰张华《博物志》言︰人以冷水渍至膝，可顿啖瓜至数十枚；渍至项，其啖转多，水皆作瓜气也。则水浸消瓜，亦物性也。瓜最忌麝与酒，凡食瓜过多，但饮酒及水服麝香，尤胜于食盐、渍水也。","zhi":"止渴，除烦热，利小便，通三焦间壅塞气，治口鼻疮（《嘉》）。暑月食之，永不中","fufang":[{"text":"用甜瓜子杵末，蜜和为丸。每旦漱口后含一丸。亦可贴齿。","src":"千金"},{"text":"腰腿疼痛︰甜瓜子三两，酒浸十日，为末。每服三钱，空心酒下，日三。","src":"寿域神方"},{"text":"肠痈已成︰小腹肿痛，小便似淋，或大便难涩下脓。用甜瓜子一合，当归。","src":""}],"vol":"果部"},"瓜蒂":{"qi":"苦，寒，有毒。大明曰︰无毒。","zhi":"大水，身面四肢浮肿，下水杀蛊毒，咳逆上气，及食诸果，病在胸腹中，皆吐下之（《本经》）。去鼻中息肉，疗黄胆（《别录》）。治脑塞热，眼昏吐痰（《大明》）。吐风热痰涎，治风眩头痛，癫痫喉痺，头目有湿气（时珍）。得麝香、细辛，治鼻不闻香臭（好古）。","fufang":[{"text":"治证见上。其方用瓜蒂二钱半。","src":"熬黄"},{"text":"赤小豆二钱半，为末。每用一钱，以香豉一合，热汤七合，煮糜去滓，和服。稍稍加之，快吐乃止。","src":"仲景《伤寒论"},{"text":"太阳中︰身热头痛而脉微弱，此夏月伤冷水，水行皮中所致。瓜蒂二七个，水一升，煮五合，顿服取吐。","src":"金匮要略"},{"text":"风涎暴作，气塞倒仆︰用瓜蒂为末。每用一、二钱，腻粉一钱匕，以水半合调灌，良久涎自出。不出，含沙糖一块，下咽即涎出也。","src":"寇氏《衍义"},{"text":"诸风诸痫︰诸风膈痰，诸痫涎涌。用瓜蒂炒黄为末，量人以酸齑水一盏，调下取吐。风痫，加蝎梢半钱。湿气肿满，加赤小豆末一钱；有虫，加狗油五、七点，雄黄一钱，甚则加芫花半钱，立吐虫出。","src":"东垣《活法机要"},{"text":"风痫喉风︰咳嗽，及遍身风疹，急中涎潮等症，不拘大人、小儿。此药不大吐逆，只出涎水。瓜蒂为末，壮年服一字，老少半字，早晨井华水下。一食顷，含沙糖一块。良久涎如水出，年深者出墨涎，有块布水上也。涎尽食粥一、两日。如吐多，人困甚，即以麝香泡汤一盏饮之，即止。","src":"经验后方"},{"text":"急黄喘息，心上坚硬，欲得水吃者︰瓜蒂二小合，赤小豆一合，研末。暖浆水五合，服方寸匕。一炊久当吐，不吐再服。吹鼻取水亦可。（《伤遍身如金︰瓜蒂四十九枚，丁香四十九枚，甘锅内烧存性，为末。每用一字，吹鼻取出黄水。亦可揩牙追涎。","src":"经验方"},{"text":"热病发黄︰瓜蒂为末，以大豆许吹鼻中。轻则半日，重则一日，流取黄水乃愈。","src":"千金翼"}],"vol":"果部"},"西瓜":{"qi":"甘、淡，寒，无毒。瑞曰︰有小毒。多食作吐利，胃弱者不可食。同油饼食，损脾。时珍曰︰按《延寿书》云︰北人禀浓，食之犹惯；南人禀薄，多食易至霍乱，冷病终身也。又按︰《相感志》云︰食西瓜后食其子，即不噫瓜气。以瓜划破，曝日中，少顷食，即冷如水也。得酒气、近糯米，即易烂。猫踏之，即易沙。","zhi":"消烦止渴，解暑热（吴瑞）。疗喉痺（汪颖）。宽中下气，利小水，治血痢，解酒毒（宁原）。含汁，治口疮（震享）。","fufang":[{"text":"西瓜青皮，阴干为末，盐酒调服三钱。","src":"摄生众妙方"},{"text":"食瓜过伤︰瓜皮煎汤解之。诸瓜皆同。","src":"事林广记"}],"vol":"果部"},"葡萄":{"qi":"甘，平，涩，无毒。诜曰︰甘、酸，温。多食，令人猝烦闷、眼暗。","zhi":"筋骨湿痺，益气倍力强志，令人肥健，耐饥忍风寒。久食，轻身不老延年。可作酒（《本经》）。逐水，利小便（《别录》）。除肠间水，调中治淋（甄权）。时气痘疮不出，食之，或研酒饮，甚效（苏颂）。","fufang":[{"text":"生葡萄捣滤取汁，以瓦器熬稠，入熟蜜少许同收。点汤饮甚良。","src":"居家必用"},{"text":"、白沙蜜各五合胎上冲心︰葡萄，煎汤饮之，即下。","src":"圣惠方"},{"text":"治腰脚肢腿痛，煎汤淋洗之良。又饮其汁，利小便，通小肠，消肿满。","src":"时珍"}],"vol":"果部"},"婴奥":{"qi":"甘、酸，平、无毒。","zhi":"止渴，悦色益气（苏恭）。藤【气味】甘，平，无毒。【主治】哕逆，伤寒后呕哕，捣汁饮之良（苏恭）。止渴，利小便（时珍）。","fufang":[{"text":"目中障翳︰藤，以水浸过，吹气取汁，滴入目中，去热翳，赤、白障。","src":"拾遗本草"},{"text":"五淋血淋︰木龙汤︰用木龙。","src":"即野葡萄藤也"},{"text":"、竹园荽、淡竹叶、麦门冬。","src":"连根苗"},{"text":"女人腹痛︰方同上。一切肿毒︰赤龙散︰用野葡萄根，晒研为末，水调涂之，即消也。","src":"儒门事亲》方"},{"text":"赤游风肿︰忽然肿痒，不治则杀人。用野葡萄根捣如泥，涂之即消。","src":"通变要法"}],"vol":"果部"},"猕猴桃":{"qi":"酸、甘，寒，无毒。藏器曰︰咸、酸，无毒。多食冷脾胃，动泄。宗奭曰︰有实热者宜食之。太过，则令人脏寒作泄。","zhi":"止暴渴，解烦热，压丹石，下石淋（《开宝》。诜曰︰并宜取瓤和蜜作煎食）。调中下气，主骨节风，瘫缓不随，长年白发，野鸡内痔病（藏器）。藤中汁【气味】甘，滑，寒，无毒。【主治】热壅反胃，和生姜汁服之。又下石淋（藏器）。枝、叶【主治】杀虫。煮汁饲狗，疗疥（《","fufang":[],"vol":"果部"},"甘蔗":{"qi":"甘，平，涩，无毒。大明曰︰冷。诜曰︰共酒食，发痰。瑞曰︰多食，发虚热，动衄血。","zhi":"下气和中，助脾气，利大肠（《别录》）。利大小肠，消痰止渴，除心胸烦热，解酒毒","fufang":[{"text":"旧三，新四。发热口干，小便赤涩︰取甘蔗去皮，嚼汁咽之。饮浆亦可。","src":"外台秘要"},{"text":"痰喘气急︰方见山药。反胃吐食，朝食暮吐，暮食朝吐，旋旋吐者。用甘蔗汁七升，生姜汁一升，和匀，日日细呷之。","src":"梅师方"},{"text":"干呕不息︰蔗汁，温服半升，日三次。入姜汁更佳。","src":"肘后方"},{"text":"疟疲瘵︰见前。眼暴赤肿，碜涩疼痛︰甘蔗汁二合，黄连半两，入铜器内慢火养浓，去滓，点之。","src":"普济"},{"text":"虚热咳嗽，口干涕唾︰用甘蔗汁一升半，青粱米四合，煮粥，日食二次，极润心肺。","src":"董氏方"},{"text":"小儿口疳︰蔗皮烧研，掺之。","src":"简便方"}],"vol":"果部"},"沙糖":{"qi":"甘，寒，无毒。恭曰︰冷利过于石蜜。诜曰︰性温不冷。多食令人心痛，生长虫，消肌肉，损齿，发疳。与鲫鱼同食，成疳虫；与葵同食，生流；与笋同食，","zhi":"心腹热胀，口干渴（《唐本》）。润心肺大小肠热，解酒毒。腊月瓶封窖粪坑中，患天行热狂者，绞汁服，甚良（大明）。和中助脾","fufang":[{"text":"沙糖半斤，乌梅一个，水二碗，煎一碗，时时饮之。","src":"摘玄方"},{"text":"腹中紧胀︰白糖以酒三升，煮服之。不过再服。","src":"子母秘录"},{"text":"痘不落痂︰沙糖，调新汲水一杯服之。","src":"白汤调亦可"},{"text":"虎伤人疮︰水化沙糖一碗服，并涂之。","src":"摘玄方"},{"text":"上气喘嗽，烦热，食即吐逆︰用沙糖、姜汁等分，相和，慢煎二十沸，每咽半匙，取效。食韭口臭︰沙糖解之。","src":"摘要方"}],"vol":"果部"},"石蜜":{"qi":"甘，寒，冷利，无毒。","zhi":"心腹热胀，口干渴（《唐本》）。治目中热膜，明目。和枣肉、巨胜末为丸噙之，润肺气，助五脏，生津（孟诜）。润心肺燥热，治嗽消痰，解酒和中，助珍）。","fufang":[],"vol":"果部"},"刺蜜":{"qi":"甘，平，无毒。","zhi":"骨蒸发热痰嗽，暴痢下血，开胃止渴除烦（藏器）。此作品在全世界都属于公有领域，因为作者逝世已经超过100年，且作品于1931年1月1日之前出版。PublicdomainPublicdomainfalsefalse取自“https://zh.wikisource.org/w/index.php?title=本草纲目/果之五&amp;oldid=1567827”分类：PD-old果树此页面最后编辑于2019年6月2日(星期日)13:34。本站的全部文字在知识共享署名-相同方式共享4.0协议之条款下提供，附加条款亦可能应用。（请参阅使用条款）在部份国家和地区，包括中国大陆、澳门和台湾，作者精神权（含署名权）永久有效（详情）。Wikisource&#174;和维基文库标志是维基媒体基金会的注册商标；维基&#8482;是维基媒体基金会的商标。维基媒体基金会是在美国佛罗里达州登记的501(c)(3)免税、非营利、慈善机构。隐私政策关于维基文库免责声明法律与安全事项联系方式行为准则开发者统计Cookie声明移动版视图搜索搜索开关目录本草纲目/果之五添加语言添加话题","fufang":[],"vol":"果部"},"莲藕":{"qi":"甘，时珍曰︰嫩性平，石莲性温。得茯苓、山药、白术、枸杞子良。诜曰︰生食过多，微动冷气胀人。蒸食甚良。大便燥涩者，不可食。","zhi":"补中养神，益气力，除百疾。久服，轻身耐老，不饥延年（不足，伤中气绝，益十二经脉血气（孟诜）。止渴去热，安心止痢，治腰痛及泄精。多食令人欢喜（大明）。交心肾，浓肠胃，固精气，强筋骨，补虚损，利耳目，除寒湿，止脾泄久痢，赤白浊，女人带下崩中诸血病（时珍）。捣碎和米作粥饭食，轻身益气，令人强健","fufang":[{"text":"诜曰︰石莲肉蒸熟去心，为末，炼蜜丸梧桐子大。日服三十丸。此仙家方也。清心宁神︰宗奭曰︰用莲蓬中干石莲子肉，于砂盆中擦去赤皮，留心，同为末，入龙脑，点补中强志，益耳目聪明︰用莲实半两去皮心，研末，水煮熟，以粳米三合作粥，入末搅匀食。","src":"圣惠方"},{"text":"补虚益损︰水芝丹︰用莲实半升。酒浸二宿，以牙猪肚一个洗净，入莲在内，缝定煮熟，取出晒干为末，酒煮米糊丸梧桐子大。每服五十小便频数，下焦真气虚弱者︰用上方，醋糊丸，服。白浊遗精︰石莲肉、龙骨、益智仁等分。为末。每服二钱，空心米饮下。《普济》︰用莲肉、白茯苓等分，为末。白汤调服。心虚赤浊︰莲子六一汤︰用石莲肉六两，炙甘草一两，为末。每服一钱，灯心汤下。","src":"直指方"},{"text":"久痢禁口︰石莲肉炒为末。每服二钱，陈仓米汤调下，便觉思食，甚妙。加入香连丸，尤妙。","src":"丹溪心法"},{"text":"脾泄肠滑︰方同上。哕逆不止︰石莲肉六枚，炒赤黄色，研末。冷熟水半盏和服，便止。","src":"苏颂《图经"},{"text":"产后咳逆、呕吐，心忡目晕︰用石莲子两半，白茯苓一两，丁香五钱。为末。每米饮服二钱。","src":"良方补遗"},{"text":"一盏，粳米半升，以水煮粥，常食。","src":"普济方"},{"text":"小儿热渴︰莲实二十枚。","src":""},{"text":"浮萍二钱半，生姜少许，水煎，分三服。","src":"圣济总录"}],"vol":"果部"},"红白莲花":{"qi":"甘，平，无毒。","zhi":"久服，令人好颜色，变白却老（藏器）。","fufang":[],"vol":"果部"},"芰实":{"qi":"甘，平，无毒。诜曰︰生食，性冷利。多食，伤人脏腑，损阳气，痿茎，生蛲虫。水族中此物最不治病。若过食腹胀者，可暖姜酒服之即消，亦可含吴茱萸咽津。时珍曰︰《仇池笔记》言︰菱花开背日，芡花开向日，故菱寒而芡暖。《别录》言芰实性平，岂","zhi":"安中补五脏，不饥轻身（《别录》）。蒸曝，和蜜饵之，断谷长生（弘景）。解丹石毒（苏颂）。鲜者，捣烂澄粉食，补中延年（仙）。芰花【气味】涩。【主治】入染须发方（时珍）。乌菱壳【主治】入染须发方，亦止泄痢（时珍）。","fufang":[],"vol":"果部"},"芡实":{"qi":"甘，平，涩，无毒。弘景曰︰小儿多食，令不长。诜曰︰生食多，动风冷气。宗奭曰︰食多，不益脾胃，兼难消化。","zhi":"湿痺，腰脊膝痛，补中，除暴疾，益精气，强志，令耳目聪明。久服，轻身不饥，耐老神仙（《本经》）。开胃助气（《日华》）。止渴益肾，治小便不禁，遗精白浊带下（时珍）。","fufang":[{"text":"益精气，强志意，利耳目。鸡头实三合。","src":"煮熟去壳"},{"text":"粳米一合煮粥，日日空心食。","src":"经验后方"},{"text":"玉锁丹︰治精气虚滑。用芡实、莲茎。","src":"方见藕节下"},{"text":"四精丸︰治思虑、色欲过度，损伤心气，小便数，遗精。用秋石、白茯苓、芡实、莲肉各二两，为末，蒸枣和丸梧桐子大。每服三十丸，空心盐汤送下。","src":"永类方"},{"text":"厘清丸︰治浊病。用芡实粉、白茯苓粉，黄蜡化蜜和，丸梧桐子大。每服百丸，盐汤下。","src":"摘玄方鸡头菜即菜（芡茎也"}],"vol":"果部"},"乌芋":{"qi":"甘，微寒，滑，无毒。诜曰︰性冷。先有冷气人不可食，令人腹胀气满。小儿秋月食多，脐下结痛也。","zhi":"消渴痺热，温中益气（《别录》）。下丹石，消风毒，除胸中实热气。可作粉食，明耳目，消黄胆（孟诜）。开胃下食（大明）。作粉食，浓人肠胃，不饥，能解毒，服金石人宜之（苏颂）。疗五种膈气，消宿食，饭后宜食之。治误吞铜物（汪机）。主血痢下血血崩，辟蛊毒（时珍）。","fufang":[{"text":"荸荠捣汁大半钟，好酒半钟，空心温服。三日见效。","src":"神秘方"},{"text":"下痢赤白︰午日午时取完好荸荠，洗净拭干，勿令损破，于瓶内入好烧酒浸之，黄泥密封收贮。遇有患者，取二枚细嚼，空心用原酒送下。","src":"唐瑶《经验方"},{"text":"妇人血崩︰凫茈一岁一个，烧存性，研末，酒服之。","src":"李氏方"},{"text":"小儿口疮︰用荸荠烧存性，研末，掺之。","src":"杨起《简便方"},{"text":"误吞铜钱︰生凫茈，研汁，细细呷之，自然消化成水。","src":"王《百一选方"}],"vol":"果部"},"慈菇":{"qi":"苦、甘，微寒，无毒。大明曰︰冷，有毒。多食，发虚热，及肠风痔漏，崩中带下，疮疖。以生姜同煮佳。怀孕人不可食。诜曰︰吴人常食之，令人发脚气瘫缓风，损齿失颜色，皮肉干燥。猝食之，使人干呕也。","zhi":"百毒，产后血闷，攻心欲死，产难胞衣不出，捣汁服一升。又下石淋（苏恭）。叶【主治】诸恶疮肿，小儿游瘤丹毒，捣烂涂之，即便消退，甚佳（苏颂）。治蛇、虫咬，捣烂封之（大明）。调蚌粉，","fufang":[],"vol":"果部"}};
;

export function gmOf(name) {
  const k = String(name || '').trim();
  if (!k) return null;
  const hit = GM_ITEMS[k];
  return hit ? { name: k, ...hit } : null;
}

/** 表里所有条目名，给词表和测试用。 */
export function gmWords() {
  return Object.keys(GM_ITEMS);
}

